(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-286":{scenario:{company:"Nam Phong Enterprise Solutions",supervisor:{name:"Đặng Hải Yến",role:{vi:"Giám đốc Khách hàng Doanh nghiệp",en:"Head of Enterprise Sales"}},ref_code:"QO-5560",title:{vi:"Đúng gói giải pháp. Đúng giá trị hợp đồng.",en:"Right plan. Right contract value."},brief:{vi:"Khách hàng là một nhà máy may cần phần mềm quản trị nhân sự, tiền lương cho 180 người dùng, bắt buộc có đăng nhập một lần (SSO). Các gói: STD-50 (tối đa 50 người dùng), BIZ-150 (tối đa 150, không có SSO), ENT-500 (tối đa 500, có SSO) giá niêm yết 95000 đ/người dùng/tháng. Hợp đồng 12 tháng. Đối chiếu đề xuất nháp QO-5560 với hồ sơ đã duyệt, sửa gói đề xuất và giá trị hợp đồng (VND, số liệu mô phỏng), rồi lập báo cáo.",en:"The client, a garment factory, needs HR and payroll software for 180 users with mandatory single sign-on (SSO). Plans: STD-50 (up to 50 users), BIZ-150 (up to 150, no SSO), ENT-500 (up to 500, with SSO) at a list price of 95000 VND per user per month. The contract runs 12 months. Compare draft proposal QO-5560 with the approved file, correct the proposed plan and the contract value (VND, simulated figures), then write a report."},reference_title:{vi:"Hồ sơ yêu cầu khách & chính sách giá đã duyệt · QO-5560",en:"Approved client requirements & pricing policy · QO-5560"},fields:[{id:"PLAN_CODE",label:{vi:"Gói giải pháp đề xuất",en:"Proposed plan"},initial:"BIZ-150",expected:"ENT-500",choices:["STD-50","BIZ-150","ENT-500"],reference:"Bảng yêu cầu khách hàng đã xác nhận",hint:{vi:"Gói phải đáp ứng đủ số người dùng và yêu cầu bắt buộc SSO, không chọn gói rẻ hơn rồi hứa nâng cấp sau.",en:"The plan must cover all users and the mandatory SSO; do not pick a cheaper plan and promise an upgrade later."}},{id:"TCV_VND",label:{vi:"Giá trị hợp đồng trước thuế (VND)",en:"Contract value before tax (VND)"},initial:"174420000",expected:"175446000",reference:"Chính sách chiết khấu đã duyệt",ref_value:{vi:"Chiết khấu 10% khi trên 100 người dùng và 5% khi trả trước cả năm, áp dụng nối tiếp",en:"10% discount above 100 users and 5% for annual prepayment, applied sequentially"},hint:{vi:"Hai chiết khấu áp dụng nối tiếp: nhân lần lượt từng hệ số, không cộng gộp phần trăm.",en:"The two discounts apply in sequence: multiply by each factor in turn, never add the percentages."}}],sop32:{vi:"Giá trị hợp đồng = số người dùng x giá niêm yết x số tháng x (1 - chiết khấu thứ nhất) x (1 - chiết khấu thứ hai); không cộng gộp các tỷ lệ chiết khấu; khách đã xác nhận trả trước cả năm.",en:"Contract value = users x list price x months x (1 - first discount) x (1 - second discount); never add discount rates together; the client has confirmed annual prepayment."},context:{label:"CRM / QO-5560",metrics:[{label:{vi:"Số người dùng",en:"Users"},value:"180"},{label:{vi:"Giá niêm yết (đ/người dùng/tháng)",en:"List price (VND/user/month)"},value:"95,000"},{label:{vi:"Thời hạn (tháng)",en:"Term (months)"},value:"12"}]},crisis:{vi:"Giám đốc vùng nhắn: “Cứ ghi trong đề xuất là đã có tích hợp máy chấm công, hứa khách tháng 1 dùng được để chốt trong quý. Sản phẩm chưa có lộ trình thì tính sau.”",en:"The regional director messages you: “Write in the proposal that time-clock integration already exists and promise it for January to close this quarter. We'll deal with the missing roadmap later.”"},options:{safe:{vi:"Không ghi tính năng chưa có; nêu đúng hiện trạng, đề xuất tích hợp qua API hoặc đối tác có thử nghiệm, báo Giám đốc Khách hàng Doanh nghiệp và xin cam kết chính thức từ bộ phận sản phẩm.",en:"Do not claim a missing feature; state the real status, offer API or partner integration with a pilot, inform the Head of Enterprise Sales and seek a formal product commitment."},shortcut:{vi:"Ghi tính năng tích hợp là ‘đã có’ và hứa tháng 1 để chốt hợp đồng trong quý.",en:"Mark the integration as ‘available’ and promise January to close the deal this quarter."},wait:{vi:"Không gửi đề xuất, chờ khách tự hỏi lại về tích hợp.",en:"Hold the proposal and wait for the client to ask about integration again."}},questions:{vi:["Vì sao đề xuất gói ENT-500 thay vì BIZ-150? Yêu cầu nào của khách chứng minh?","Trình bày cách tính giá trị hợp đồng với hai chiết khấu và cách xử lý áp lực hứa tính năng chưa có trong đề xuất."],en:["Why propose ENT-500 instead of BIZ-150? Which client requirement proves it?","Explain how you calculated the contract value with two discounts and how you handle pressure to promise a feature that does not exist."]},hints:{vi:["Đặt đề xuất nháp cạnh bảng yêu cầu khách đã xác nhận, đánh dấu yêu cầu mà gói hiện tại không đáp ứng.","Áp từng chiết khấu nối tiếp lên giá niêm yết cả năm theo SOP mục 3.2.","Đọc lại SOP mục 4.2: đề xuất phải mô tả đúng năng lực sản phẩm; cam kết lộ trình cần phê duyệt chính thức."],en:["Place the draft proposal next to the confirmed requirements and flag what the current plan cannot meet.","Apply each discount in sequence to the annual list price per SOP 3.2.","Re-read SOP 4.2: proposals must describe real product capability; roadmap commitments need formal approval."]}},learning:{summary:{vi:"Chuyên viên kinh doanh giải pháp doanh nghiệp (Account Executive) tìm kiếm và chốt hợp đồng với khách hàng tổ chức: khai thác bài toán kinh doanh, xác định người ra quyết định, thiết kế giải pháp cùng đội kỹ thuật, lập đề xuất, đàm phán giá và điều khoản. Công việc đòi hỏi bán hàng tư vấn, quản lý chu kỳ bán dài với nhiều bên liên quan, dự báo doanh số chính xác và cam kết trung thực với khách.",en:"A B2B account executive finds and closes deals with organizational clients: uncovering business problems, mapping decision makers, shaping solutions with presales engineers, writing proposals and negotiating price and terms. The role demands consultative selling, managing long multi-stakeholder cycles, accurate forecasting and honest commitments to clients."},responsibilities:{vi:["Tìm kiếm, sàng lọc khách hàng doanh nghiệp phù hợp chân dung khách hàng mục tiêu.","Khai thác nhu cầu, xác định tiêu chí quyết định, ngân sách và sơ đồ người ra quyết định.","Phối hợp kỹ sư giải pháp demo, thử nghiệm (POC) và lập đề xuất giá trị, báo giá.","Đàm phán giá, chiết khấu trong thẩm quyền, điều khoản hợp đồng, SLA và chốt hợp đồng.","Quản lý pipeline trên CRM, dự báo doanh số và bàn giao khách cho đội triển khai, chăm sóc."],en:["Prospect and qualify organizations that fit the ideal customer profile.","Discover needs, decision criteria, budget and the map of decision makers.","Run demos and proofs of concept (POC) with solution engineers and write value proposals and quotes.","Negotiate price, discounts within authority, contract terms and SLAs, and close deals.","Manage the CRM pipeline, forecast revenue and hand clients over to delivery and success teams."]},competencies:[{name:{vi:"Bán hàng tư vấn",en:"Consultative selling"},desc:{vi:"Đặt câu hỏi khai thác bài toán, lượng hóa tác động và gắn giải pháp với kết quả kinh doanh.",en:"Ask discovery questions, quantify impact and tie the solution to business outcomes."}},{name:{vi:"Đánh giá cơ hội",en:"Deal qualification"},desc:{vi:"Áp dụng khung MEDDICC, BANT để xác định cơ hội thật và rủi ro.",en:"Apply MEDDICC and BANT to separate real opportunities from risky ones."}},{name:{vi:"Thiết kế đề xuất & định giá",en:"Proposal & pricing"},desc:{vi:"Chọn đúng gói, tính chiết khấu đúng chính sách và minh bạch giá trị hợp đồng.",en:"Choose the right plan, apply discounts per policy and keep contract value transparent."}},{name:{vi:"Đàm phán nhiều bên",en:"Multi-stakeholder negotiation"},desc:{vi:"Cân bằng lợi ích của mua hàng, CNTT, tài chính và ban giám đốc phía khách.",en:"Balance the interests of the client's procurement, IT, finance and leadership."}},{name:{vi:"Liêm chính bán hàng",en:"Sales integrity"},desc:{vi:"Không hứa tính năng chưa có, không chiết khấu ngầm; mọi cam kết phải có phê duyệt.",en:"Never promise missing features or hidden discounts; every commitment needs approval."}}],knowledge:{vi:["Các phương pháp bán hàng B2B: SPIN Selling, Challenger Sale, MEDDICC và quản lý chu kỳ bán dài.","Chỉ số kinh doanh phần mềm thuê bao: ARR, ACV, TCV, tỷ lệ rời bỏ và tỷ lệ giữ chân doanh thu ròng.","Luật Thương mại 2005 (số 36/2005/QH11) và Bộ luật Dân sự 2015 (số 91/2015/QH13) về hợp đồng và trách nhiệm do vi phạm.","Luật Cạnh tranh 2018 (số 23/2018/QH14) về hành vi cạnh tranh không lành mạnh.","Quy định hiện hành về bảo vệ dữ liệu cá nhân khi giải pháp xử lý dữ liệu nhân sự của khách.","ISO 37001 về hệ thống quản lý chống hối lộ và chính sách quà tặng, chiêu đãi."],en:["B2B selling methods: SPIN Selling, the Challenger Sale, MEDDICC and long-cycle management.","Subscription software metrics: ARR, ACV, TCV, churn and net revenue retention.","Commercial Law 2005 (No. 36/2005/QH11) and Civil Code 2015 (No. 91/2015/QH13) on contracts and liability for breach.","Competition Law 2018 (No. 23/2018/QH14) on unfair competition practices.","Current personal data protection rules when the solution processes the client's HR data.","ISO 37001 anti-bribery management systems and gift and hospitality policies."]},tools:["Hệ thống CRM","Công cụ cấu hình báo giá (CPQ)","Nền tảng ký hợp đồng điện tử","Công cụ họp trực tuyến và demo","Bản đồ người ra quyết định (stakeholder map)"],kpis:{vi:["Doanh số ký mới so với chỉ tiêu (quota attainment).","Giá trị pipeline đủ điều kiện và độ phủ pipeline.","Tỷ lệ chốt và độ dài chu kỳ bán hàng.","Độ chính xác dự báo doanh số theo quý."],en:["New bookings against quota (quota attainment).","Qualified pipeline value and pipeline coverage.","Win rate and sales cycle length.","Quarterly forecast accuracy."]},day:[{time:"08:30",vi:"Rà soát pipeline, cập nhật bước tiếp theo cho các cơ hội sắp chốt trong quý.",en:"Review the pipeline and set next steps for deals closing this quarter."},{time:"10:00",vi:"Họp khám phá nhu cầu với khách mới cùng kỹ sư giải pháp.",en:"Hold a discovery meeting with a new prospect alongside a solution engineer."},{time:"13:30",vi:"Lập đề xuất, cấu hình báo giá trên CPQ và kiểm tra chiết khấu trong thẩm quyền.",en:"Write a proposal, configure the quote in CPQ and check discounts within authority."},{time:"15:30",vi:"Đàm phán điều khoản với bộ phận mua hàng, pháp chế của khách.",en:"Negotiate terms with the client's procurement and legal teams."},{time:"17:00",vi:"Cập nhật CRM, dự báo doanh số và báo cáo rủi ro cơ hội cho trưởng nhóm.",en:"Update the CRM and forecast and report deal risks to the sales lead."}],mistakes:{vi:["Chọn gói rẻ hơn không đáp ứng yêu cầu bắt buộc để thắng giá, gây xung đột khi triển khai.","Cộng gộp các tỷ lệ chiết khấu thay vì áp dụng nối tiếp, làm sai giá trị hợp đồng.","Hứa tính năng chưa có hoặc ghi ‘đã có’ trong đề xuất để chốt quý, gây tranh chấp và mất uy tín."],en:["Proposing a cheaper plan that misses mandatory requirements to win on price, causing conflict at rollout.","Adding discount rates together instead of applying them in sequence, misstating contract value.","Promising unbuilt features or marking them ‘available’ to close the quarter, leading to disputes and lost trust."]},career:[{vi:"Chuyên viên phát triển kinh doanh (SDR)",en:"Sales development representative"},{vi:"Chuyên viên kinh doanh giải pháp doanh nghiệp",en:"B2B account executive"},{vi:"Chuyên viên kinh doanh khách hàng chiến lược",en:"Strategic account executive"},{vi:"Giám đốc kinh doanh khối doanh nghiệp",en:"Head of enterprise sales"}],glossary:[{term:"Pipeline",vi:"Tập hợp cơ hội bán hàng theo từng giai đoạn, dùng để dự báo doanh số.",en:"The set of sales opportunities by stage, used to forecast revenue."},{term:"MEDDICC",vi:"Khung đánh giá cơ hội: chỉ số, người duyệt chi, tiêu chí và quy trình quyết định, nỗi đau, người ủng hộ, đối thủ.",en:"Qualification framework: metrics, economic buyer, decision criteria and process, pain, champion, competition."},{term:"TCV",vi:"Tổng giá trị hợp đồng trong toàn bộ thời hạn cam kết.",en:"Total contract value over the full committed term."},{term:"POC",vi:"Thử nghiệm chứng minh khái niệm trên dữ liệu, quy trình thật của khách trước khi ký.",en:"Proof of concept run on the client's real data and processes before signing."},{term:"Champion",vi:"Người ủng hộ bên trong tổ chức khách hàng, chủ động thúc đẩy giải pháp.",en:"An internal supporter at the client who actively pushes the solution."}],quiz:[{q:{vi:"Giá niêm yết 100 triệu đ, chiết khấu 10% rồi thêm 5% áp dụng nối tiếp. Giá sau chiết khấu là bao nhiêu?",en:"The list price is 100 million VND with 10% then 5% applied in sequence. What is the net price?"},options:{vi:["85 triệu đ","86 triệu đ","85,5 triệu đ","90 triệu đ"],en:["85 million VND","86 million VND","85.5 million VND","90 million VND"]},answer:2,explain:{vi:"100 x 0,9 x 0,95 = 85,5 triệu đ; cộng gộp 15% cho ra 85 triệu đ là sai.",en:"100 x 0.9 x 0.95 = 85.5 million VND; adding to 15% and getting 85 million is wrong."}},{q:{vi:"Trong MEDDICC, ‘Economic Buyer’ là ai?",en:"In MEDDICC, who is the ‘Economic Buyer’?"},options:{vi:["Người có quyền quyết định ngân sách cuối cùng","Người dùng cuối","Nhân viên mua hàng soạn hợp đồng","Đối thủ cạnh tranh"],en:["The person with final budget authority","The end user","The buyer drafting the contract","A competitor"]},answer:0,explain:{vi:"Economic Buyer là người có quyền phê duyệt chi tiêu cuối cùng, cần được tiếp cận sớm.",en:"The Economic Buyer holds final spending authority and should be engaged early."}},{q:{vi:"Cấp trên bảo ghi tính năng chưa phát triển là ‘đã có’ để chốt quý. Bạn làm gì?",en:"Your manager tells you to mark an unbuilt feature as ‘available’ to close the quarter. What do you do?"},options:{vi:["Ghi theo vì sau này sẽ có","Hứa miệng, không ghi văn bản","Bỏ qua yêu cầu của khách","Mô tả đúng hiện trạng, đề xuất phương án thay thế và xin cam kết lộ trình chính thức"],en:["Write it since it will come later","Promise verbally, put nothing in writing","Ignore the client's need","State the real status, offer an alternative and seek a formal roadmap commitment"]},answer:3,explain:{vi:"Mô tả sai năng lực sản phẩm là gian dối thương mại, gây tranh chấp hợp đồng và mất uy tín lâu dài.",en:"Misstating product capability is deceptive, triggers contract disputes and destroys long-term trust."}},{q:{vi:"Khách cần 180 người dùng và bắt buộc SSO; gói BIZ-150 rẻ hơn nhưng tối đa 150 người, không có SSO. Nên làm gì?",en:"A client needs 180 users and mandatory SSO; BIZ-150 is cheaper but caps at 150 users with no SSO. What should you do?"},options:{vi:["Đề xuất BIZ-150 rồi nâng cấp sau","Đề xuất gói đáp ứng đủ yêu cầu và giải thích giá trị","Chia khách thành hai hợp đồng","Bỏ yêu cầu SSO khỏi biên bản"],en:["Propose BIZ-150 and upgrade later","Propose the plan that meets every requirement and explain its value","Split the client into two contracts","Remove SSO from the minutes"]},answer:1,explain:{vi:"Đề xuất phải đáp ứng yêu cầu bắt buộc đã xác nhận; bán thiếu phạm vi sẽ thất bại khi triển khai.",en:"A proposal must meet confirmed mandatory requirements; underscoping fails at rollout."}}],tools_en:["CRM system","Configure-price-quote tool (CPQ)","E-signature platform","Online meeting and demo tools","Decision-maker stakeholder map"]}},"KK-287":{scenario:{company:"Saola Cloud Solutions",supervisor:{name:"Vi Minh Khoa",role:{vi:"Trưởng nhóm Phát triển Kinh doanh",en:"Business Development Team Lead"}},ref_code:"LD-5821",title:{vi:"Đúng giai đoạn. Đúng điểm. Đúng sự thật.",en:"Right stage. Right score. Right facts."},brief:{vi:"Bạn rà soát lead LD-5821 trước khi bàn giao cho AE: công ty logistics 320 nhân sự (đúng ICP), người liên hệ là Trưởng phòng CNTT (chưa phải người quyết định), đã dự webinar, xem trang bảng giá 2 lần, mở email 6 lần nhưng chưa trả lời, chưa xác nhận ngân sách, dự kiến triển khai sau 9 tháng. Quy chuẩn: SQL cần ít nhất 3/4 tiêu chí BANT và bắt buộc có Authority. Sửa giai đoạn lead và điểm lead (mô hình chấm điểm mô phỏng), rồi lập báo cáo có căn cứ.",en:"You are reviewing lead LD-5821 before handing it to an AE: a 320-employee logistics company (ICP fit), the contact is the IT Manager (not the decision maker), attended a webinar, viewed the pricing page twice, opened emails 6 times without replying, budget unconfirmed, go-live expected in 9 months. Standard: an SQL needs at least 3 of 4 BANT criteria including Authority. Correct the lead stage and lead score (training scoring model), then write an evidence-based report."},reference_title:{vi:"Phiếu sàng lọc BANT & mô hình điểm lead đã duyệt · LD-5821",en:"Approved BANT sheet & lead scoring model · LD-5821"},fields:[{id:"LEAD_STAGE",label:{vi:"Giai đoạn lead",en:"Lead stage"},initial:"SQL",expected:"MQL",choices:["SQL","MQL","DQ"],reference:"Phiếu sàng lọc BANT",hint:{vi:"Đếm số tiêu chí BANT có bằng chứng; người liên hệ chưa có thẩm quyền quyết định.",en:"Count the BANT criteria with evidence; the contact has no decision authority."}},{id:"LEAD_SCORE",label:{vi:"Điểm lead",en:"Lead score"},initial:"98",expected:"70",reference:"Mô hình điểm lead",ref_value:{vi:"Fit: ICP, 320 nhân sự, cấp quản lý; hành vi: 1 webinar, 2 lần xem bảng giá, 6 lần mở email; triển khai sau 9 tháng",en:"Fit: ICP, 320 staff, manager level; activity: 1 webinar, 2 pricing views, 6 email opens; go-live in 9 months"},hint:{vi:"Lượt mở email không được tính điểm, và thời điểm triển khai xa phải bị trừ điểm.",en:"Email opens earn no points, and a distant go-live date must be deducted."}}],sop32:{vi:"Điểm lead = ngành ICP +20, quy mô 200-1000 nhân sự +15, cấp quản lý +10, dự webinar +15, mỗi lần xem bảng giá +10; lượt mở email không tính điểm; triển khai sau hơn 6 tháng -10. SQL từ 80 điểm (mô phỏng).",en:"Lead score = ICP industry +20, size 200-1000 staff +15, manager level +10, webinar attended +15, each pricing page view +10; email opens score zero; go-live beyond 6 months -10. SQL from 80 points (training model)."},context:{label:"CRM / LD-5821",metrics:[{label:{vi:"Quy mô doanh nghiệp",en:"Company size"},value:"320 FTE"},{label:{vi:"Lượt xem bảng giá",en:"Pricing page views"},value:"2"},{label:{vi:"Lượt mở email",en:"Email opens"},value:"6"},{label:{vi:"Ngưỡng SQL mô phỏng",en:"Training SQL threshold"},value:"80"}]},crisis:{vi:"Quản lý kinh doanh khu vực nhắn: “Cuối tháng còn thiếu 3 SQL. Cứ chuyển LD-5821 sang SQL, ghi là khách đã xác nhận ngân sách, AE gọi lại sau là được.”",en:"The regional sales manager messages you: “We are 3 SQLs short this month. Just move LD-5821 to SQL and note that the budget is confirmed, the AE can call later.”"},options:{safe:{vi:"Giữ MQL và điểm đúng mô hình, ghi trung thực BANT, báo trưởng nhóm; đề xuất cuộc gọi khám phá với giám đốc vận hành để xác nhận ngân sách và thẩm quyền.",en:"Keep MQL and the correct model score, record BANT honestly, inform the team lead; propose a discovery call with the operations director to confirm budget and authority."},shortcut:{vi:"Chuyển sang SQL và ghi đã có ngân sách cho đủ chỉ tiêu, AE sẽ tự lọc lại sau.",en:"Move it to SQL and record a confirmed budget to hit the target, the AE will filter it later."},wait:{vi:"Để nguyên bản nháp, không bàn giao và không báo ai cho đến hết tháng.",en:"Leave the draft as it is, hand nothing over and tell no one until month end."}},questions:{vi:["Vì sao LD-5821 là MQL chứ không phải SQL? Tiêu chí BANT nào còn thiếu và bằng chứng nằm ở đâu?","Trình bày cách tính điểm lead theo mô hình và rủi ro khi ghi khống ngân sách để đủ chỉ tiêu SQL."],en:["Why is LD-5821 an MQL rather than an SQL? Which BANT criteria are missing and where is the evidence?","Explain how you calculated the lead score and the risk of recording a fake budget to meet the SQL target."]},hints:{vi:["Đặt bản nháp cạnh phiếu sàng lọc BANT và đánh dấu tiêu chí nào có bằng chứng, tiêu chí nào chưa.","Cộng từng hạng mục fit và hành vi theo SOP mục 3.2, chú ý hạng mục không tính điểm và hạng mục bị trừ.","Đọc lại SOP mục 4.2: dữ liệu CRM phải trung thực, mọi áp lực sửa giai đoạn phải được báo cáo."],en:["Place the draft next to the BANT sheet and mark which criteria have evidence and which do not.","Add each fit and activity item per SOP 3.2, watching for items that score zero and items that deduct.","Re-read SOP 4.2: CRM data must be truthful and any pressure to change a stage must be escalated."]}},learning:{summary:{vi:"Chuyên viên phát triển kinh doanh (BDR) mở đầu chu trình bán hàng B2B: nghiên cứu thị trường mục tiêu, tìm và tiếp cận khách hàng tiềm năng qua điện thoại, email, mạng xã hội nghề nghiệp và sự kiện, sàng lọc theo hồ sơ khách hàng lý tưởng (ICP) và khung BANT, rồi đặt lịch hẹn chất lượng cho chuyên viên kinh doanh (AE). Giá trị cốt lõi là đường ống cơ hội thật, dữ liệu CRM trung thực và hoạt động tiếp cận tuân thủ quy định về dữ liệu cá nhân, chống cuộc gọi và thư rác.",en:"A Business Development Representative opens the B2B sales cycle: researching target markets, finding and engaging prospects by phone, email, professional networks and events, qualifying them against the ideal customer profile (ICP) and BANT, then booking quality meetings for account executives (AEs). The core value is a real pipeline, honest CRM data and outreach that complies with personal data and anti-spam rules."},responsibilities:{vi:["Nghiên cứu ngành, xây danh sách tài khoản mục tiêu theo ICP và vẽ sơ đồ người ảnh hưởng.","Thực hiện chuỗi tiếp cận đa kênh: gọi điện, email cá nhân hóa, mạng xã hội nghề nghiệp.","Sàng lọc nhu cầu theo BANT hoặc MEDDIC và ghi nhận bằng chứng vào CRM.","Đặt lịch hẹn khám phá và bàn giao SQL cho AE kèm ghi chú đầy đủ.","Nuôi dưỡng MQL chưa sẵn sàng, cập nhật điểm lead và báo cáo hiệu quả kênh hằng tuần."],en:["Research industries, build target account lists by ICP and map the influencers.","Run multichannel cadences: calls, personalized emails and professional networks.","Qualify needs with BANT or MEDDIC and record the evidence in the CRM.","Book discovery meetings and hand SQLs to AEs with complete notes.","Nurture MQLs that are not ready, update lead scores and report channel results weekly."]},competencies:[{name:{vi:"Nghiên cứu khách hàng",en:"Account research"},desc:{vi:"Đọc báo cáo ngành, tin tuyển dụng, website để tìm tín hiệu nhu cầu và người quyết định.",en:"Read industry reports, job posts and websites to find buying signals and decision makers."}},{name:{vi:"Tiếp cận & mở lời",en:"Prospecting & opening"},desc:{vi:"Viết email ngắn có giá trị, mở cuộc gọi trong 30 giây đầu và xử lý từ chối ban đầu.",en:"Write short value-led emails, open a call in the first 30 seconds and handle early objections."}},{name:{vi:"Sàng lọc có kỷ luật",en:"Disciplined qualification"},desc:{vi:"Áp dụng ICP, BANT và mô hình điểm lead nhất quán, không thổi phồng giai đoạn.",en:"Apply ICP, BANT and the lead scoring model consistently without inflating stages."}},{name:{vi:"Quản trị dữ liệu CRM",en:"CRM data hygiene"},desc:{vi:"Ghi hoạt động, giai đoạn và nguồn lead chính xác để đo được phễu chuyển đổi.",en:"Log activities, stages and lead sources accurately so the funnel can be measured."}},{name:{vi:"Tuân thủ & liêm chính",en:"Compliance & integrity"},desc:{vi:"Chỉ dùng dữ liệu có nguồn hợp pháp, tôn trọng yêu cầu từ chối liên hệ và báo cáo trung thực.",en:"Use only lawfully sourced data, honor opt-out requests and report truthfully."}}],knowledge:{vi:["Khung sàng lọc BANT (Ngân sách, Thẩm quyền, Nhu cầu, Thời điểm) và MEDDIC cho thương vụ phức tạp.","Phễu lead MQL, SAL, SQL và thỏa thuận định nghĩa chung giữa marketing và kinh doanh (SLA).","Hồ sơ khách hàng lý tưởng (ICP), chân dung người mua và sơ đồ đơn vị ra quyết định.","Nghị định 91/2020/NĐ-CP về chống tin nhắn rác, thư điện tử rác, cuộc gọi rác.","Luật Bảo vệ dữ liệu cá nhân và văn bản hướng dẫn hiện hành: căn cứ xử lý dữ liệu, quyền phản đối của chủ thể."],en:["BANT qualification (Budget, Authority, Need, Timing) and MEDDIC for complex deals.","The MQL, SAL, SQL funnel and the shared marketing-sales definition agreement (SLA).","Ideal customer profile (ICP), buyer personas and buying committee mapping.","Decree 91/2020/ND-CP on fighting spam messages, spam emails and spam calls.","Vietnam's Personal Data Protection Law and current guidance: lawful bases and the data subject's right to object."]},tools:["Hệ thống CRM","Nền tảng sales engagement","Tổng đài VoIP / softphone","Cơ sở dữ liệu doanh nghiệp B2B","Công cụ đặt lịch hẹn trực tuyến"],kpis:{vi:["Số cuộc hẹn đủ chuẩn (SQL) được AE chấp nhận mỗi tháng.","Tỷ lệ chuyển đổi từ cuộc hẹn sang cơ hội bán hàng.","Tỷ lệ kết nối cuộc gọi và tỷ lệ phản hồi email của chuỗi tiếp cận.","Giá trị đường ống cơ hội tạo ra trên mỗi BDR mỗi quý."],en:["Qualified meetings (SQLs) accepted by AEs per month.","Conversion rate from meeting to sales opportunity.","Call connect rate and email reply rate of each cadence.","Pipeline value generated per BDR per quarter."]},day:[{time:"08:30",vi:"Nghiên cứu 15 tài khoản mục tiêu mới, tìm tín hiệu nhu cầu và người quyết định.",en:"Research 15 new target accounts for buying signals and decision makers."},{time:"09:30",vi:"Khung giờ gọi tập trung: gọi lạnh và gọi theo dõi các lead đã tương tác.",en:"Power hour: cold calls and follow-up calls to engaged leads."},{time:"13:30",vi:"Gửi chuỗi email cá nhân hóa, trả lời phản hồi và đặt lịch hẹn.",en:"Send personalized email steps, answer replies and book meetings."},{time:"15:30",vi:"Họp bàn giao SQL với AE, cập nhật giai đoạn và ghi chú BANT trên CRM.",en:"Hand SQLs over to AEs, update stages and BANT notes in the CRM."},{time:"17:00",vi:"Rà soát chỉ số trong ngày và chuẩn bị danh sách gọi cho hôm sau.",en:"Review the day's metrics and prepare tomorrow's call list."}],mistakes:{vi:["Đẩy lead lên SQL khi chưa xác nhận thẩm quyền và ngân sách, làm AE mất thời gian.","Tính lượt mở email vào điểm lead dù dữ liệu mở thư không đáng tin cậy.","Dùng danh sách liên hệ không rõ nguồn hoặc tiếp tục gọi người đã yêu cầu từ chối."],en:["Pushing a lead to SQL before authority and budget are confirmed, wasting AE time.","Scoring email opens even though open tracking is unreliable.","Using contact lists of unknown origin or calling people who have opted out."]},career:[{vi:"Thực tập sinh phát triển kinh doanh",en:"Business development intern"},{vi:"Chuyên viên phát triển kinh doanh (BDR)",en:"Business Development Representative"},{vi:"Chuyên viên kinh doanh khách hàng (AE)",en:"Account Executive"},{vi:"Quản lý phát triển kinh doanh",en:"Business Development Manager"}],glossary:[{term:"ICP",vi:"Hồ sơ khách hàng lý tưởng: ngành, quy mô, khu vực của nhóm khách hàng phù hợp nhất với sản phẩm.",en:"Ideal customer profile: the industry, size and region of the best-fit customer group."},{term:"BANT",vi:"Khung sàng lọc gồm Ngân sách, Thẩm quyền, Nhu cầu và Thời điểm mua.",en:"Qualification framework covering Budget, Authority, Need and Timing."},{term:"MQL",vi:"Lead đạt tiêu chí marketing (phù hợp, có tương tác) nhưng chưa đủ điều kiện bàn giao bán hàng.",en:"A lead that meets marketing criteria (fit and engagement) but is not yet ready for sales."},{term:"SQL",vi:"Lead đã được sàng lọc đủ tiêu chí để AE mở cơ hội bán hàng.",en:"A lead qualified enough for an AE to open a sales opportunity."},{term:"Cadence",vi:"Chuỗi tiếp cận gồm nhiều điểm chạm đa kênh theo lịch định sẵn.",en:"A planned sequence of multichannel outreach touches."}],quiz:[{q:{vi:"Theo mô hình trong bài, lead có ICP, quy mô 450 nhân sự, cấp quản lý, dự webinar, xem bảng giá 1 lần, mở email 4 lần, triển khai sau 8 tháng. Điểm lead là bao nhiêu?",en:"Under the training model, a lead is ICP, 450 staff, manager level, attended a webinar, viewed pricing once, opened emails 4 times, go-live in 8 months. What is the score?"},options:{vi:["60","72","70","50"],en:["60","72","70","50"]},answer:0,explain:{vi:"20 + 15 + 10 + 15 + 10 - 10 = 60; lượt mở email không tính điểm.",en:"20 + 15 + 10 + 15 + 10 - 10 = 60; email opens score zero."}},{q:{vi:"Theo quy chuẩn trong bài, lead đạt SQL cần điều kiện nào?",en:"Under the training standard, what does an SQL require?"},options:{vi:["Mở email ít nhất 3 lần","Đã dự một webinar","Đạt ít nhất 3/4 tiêu chí BANT, bắt buộc có Authority","Người liên hệ thuộc phòng CNTT"],en:["At least 3 email opens","Attended one webinar","At least 3 of 4 BANT criteria, Authority mandatory","The contact works in IT"]},answer:2,explain:{vi:"SQL cần bằng chứng sàng lọc; thiếu người có thẩm quyền thì chưa thể mở cơ hội.",en:"An SQL needs qualification evidence; without authority no opportunity can be opened."}},{q:{vi:"Khách hàng tiềm năng nói “đừng gọi cho tôi nữa”. Bạn làm gì?",en:"A prospect says “do not call me again”. What do you do?"},options:{vi:["Đổi số khác gọi lại sau một tuần","Chuyển sang gửi email quảng cáo","Nhờ đồng nghiệp gọi thay","Ghi nhận từ chối trên CRM, dừng mọi kênh và cảm ơn khách"],en:["Call again from another number next week","Switch to promotional emails","Ask a colleague to call instead","Record the opt-out in the CRM, stop all channels and thank them"]},answer:3,explain:{vi:"Tôn trọng quyền từ chối là yêu cầu pháp lý và đạo đức; tiếp tục liên hệ có thể bị coi là cuộc gọi, thư rác.",en:"Honoring opt-outs is a legal and ethical duty; continued contact can count as spam calls or emails."}},{q:{vi:"Vì sao MQL nên được nuôi dưỡng thay vì bàn giao ngay cho AE?",en:"Why should an MQL be nurtured instead of handed straight to an AE?"},options:{vi:["Vì MQL không có giá trị kinh doanh","Vì chưa đủ tín hiệu sẵn sàng mua; bàn giao sớm làm giảm tỷ lệ chuyển đổi","Vì AE chỉ nhận lead từ sự kiện","Vì hệ thống CRM không cho phép"],en:["Because MQLs have no business value","Because buying readiness is not proven; early handover lowers conversion","Because AEs only accept event leads","Because the CRM does not allow it"]},answer:1,explain:{vi:"Nuôi dưỡng giúp lead chín muồi, giữ niềm tin giữa BDR và AE và làm phễu dự báo chính xác hơn.",en:"Nurturing matures the lead, keeps BDR-AE trust and makes the funnel forecast more accurate."}}],tools_en:["CRM system","Sales engagement platform","VoIP phone system / softphone","B2B company database","Online appointment scheduling tools"]}},"KK-288":{scenario:{company:"Mekong Data Systems",supervisor:{name:"Nghiêm Thu Hà",role:{vi:"Giám đốc Tư vấn Giải pháp",en:"Head of Solutions Consulting"}},ref_code:"RFP-3307",title:{vi:"Đúng yêu cầu. Đúng chi phí. Đúng cam kết.",en:"Right fit. Right cost. Right promise."},brief:{vi:"Bạn hoàn thiện hồ sơ trả lời RFP-3307 cho nhà máy điện tử cần phần mềm nhân sự cho 1200 người dùng, hợp đồng 36 tháng. Yêu cầu bắt buộc: dữ liệu lưu tại Việt Nam, môi trường riêng biệt; khách không có đội hạ tầng CNTT. Bảng giá mô phỏng: SaaS dùng chung (máy chủ ở nước ngoài) 4 USD, đám mây riêng tại Việt Nam 6 USD mỗi người dùng mỗi tháng; triển khai 38000 USD, chuyển đổi dữ liệu 12000 USD. Sửa phương án triển khai và TCO 3 năm, rồi lập báo cáo có căn cứ.",en:"You are finalizing the response to RFP-3307 for an electronics plant needing HR software for 1200 users on a 36-month contract. Mandatory: data stored in Vietnam in an isolated environment; the client has no IT infrastructure team. Training price list: shared SaaS (hosted abroad) 4 USD, private cloud in Vietnam 6 USD per user per month; implementation 38000 USD, data migration 12000 USD. Correct the deployment option and the 3-year TCO, then write an evidence-based report."},reference_title:{vi:"Ma trận đáp ứng & bảng tính TCO đã duyệt · RFP-3307",en:"Approved compliance matrix & TCO sheet · RFP-3307"},fields:[{id:"DEPLOY_MODEL",label:{vi:"Phương án triển khai",en:"Deployment option"},initial:"SAAS-SHARED",expected:"PRIVATE-VN",choices:["SAAS-SHARED","PRIVATE-VN","ON-PREM"],reference:"Ma trận đáp ứng yêu cầu bắt buộc",hint:{vi:"Loại phương án vi phạm yêu cầu lưu trữ dữ liệu, rồi loại phương án khách không tự vận hành được.",en:"Rule out the option that breaks data residency, then the one the client cannot operate."}},{id:"TCO_USD",label:{vi:"TCO 3 năm (USD)",en:"3-year TCO (USD)"},initial:"210800",expected:"309200",reference:"Bảng tính TCO",ref_value:{vi:"1200 người dùng x 36 tháng x đơn giá phương án đã chọn; triển khai 38000 + chuyển đổi dữ liệu 12000 USD",en:"1200 users x 36 months x price of the chosen option; implementation 38000 + data migration 12000 USD"},hint:{vi:"Đơn giá phải khớp phương án đáp ứng yêu cầu bắt buộc, và không bỏ sót chi phí một lần nào.",en:"The unit price must match the compliant option, and no one-time cost may be left out."}}],sop32:{vi:"TCO 3 năm = số người dùng x đơn giá tháng của phương án đáp ứng yêu cầu bắt buộc x 36 + mọi chi phí một lần (triển khai, chuyển đổi dữ liệu). Đơn giá trong bài là số liệu mô phỏng.",en:"3-year TCO = users x monthly price of the option meeting all mandatory requirements x 36 + every one-time cost (implementation, data migration). Prices are training figures."},context:{label:"RFP / RFP-3307",metrics:[{label:{vi:"Số người dùng",en:"Named users"},value:"1200"},{label:{vi:"Kỳ hợp đồng (tháng)",en:"Contract term (months)"},value:"36"},{label:{vi:"Nơi lưu trữ bắt buộc",en:"Mandatory data residency"},value:"VN"},{label:{vi:"Chi phí một lần",en:"One-time costs"},value:"50,000 USD"}]},crisis:{vi:"Giám đốc kinh doanh yêu cầu: “Đánh ‘Đáp ứng đầy đủ’ cho cả 142 yêu cầu, kể cả đăng nhập một lần với hệ thống chấm công cũ mà sản phẩm chưa hỗ trợ. Ký được hợp đồng rồi tùy biến sau.”",en:"The sales director demands: “Mark all 142 requirements ‘Fully compliant’, including single sign-on with the legacy time-attendance system the product does not support. Sign first, customize later.”"},options:{safe:{vi:"Ghi trung thực từng mức đáp ứng (đầy đủ, một phần, lộ trình, tùy biến có phí), báo Giám đốc Tư vấn Giải pháp và đề xuất tích hợp qua API kèm ước lượng công.",en:"Record each compliance level honestly (full, partial, roadmap, paid customization), inform the Head of Solutions and propose an API integration with an effort estimate."},shortcut:{vi:"Đánh đáp ứng đầy đủ toàn bộ cho kịp hạn nộp, xử lý chênh lệch khi triển khai.",en:"Mark everything fully compliant to meet the deadline and deal with the gaps during delivery."},wait:{vi:"Không trả lời mục tích hợp và chờ kinh doanh tự quyết định nội dung nộp.",en:"Leave the integration items blank and wait for Sales to decide what to submit."}},questions:{vi:["Vì sao chọn PRIVATE-VN thay vì SAAS-SHARED hay ON-PREM? Yêu cầu bắt buộc nào quyết định lựa chọn?","Trình bày cách tính TCO 3 năm và rủi ro pháp lý, uy tín khi khai năng lực không có thật trong hồ sơ thầu."],en:["Why choose PRIVATE-VN over SAAS-SHARED or ON-PREM? Which mandatory requirement drives the choice?","Explain the 3-year TCO calculation and the legal and reputational risk of claiming capabilities that do not exist."]},hints:{vi:["Đặt bản nháp cạnh ma trận đáp ứng, đánh dấu yêu cầu bắt buộc mà phương án hiện tại không thỏa.","Tính TCO theo SOP mục 3.2: chi phí định kỳ của đủ kỳ hợp đồng cộng mọi chi phí một lần.","Đọc lại SOP mục 4.2: không cam kết năng lực chưa có; khoảng trống phải được ghi rõ và báo cáo."],en:["Place the draft next to the compliance matrix and flag the mandatory item the current option fails.","Compute TCO per SOP 3.2: recurring cost over the full term plus every one-time cost.","Re-read SOP 4.2: never commit capabilities that do not exist; gaps must be stated and escalated."]}},learning:{summary:{vi:"Chuyên viên tư vấn giải pháp (pre-sales) là cầu nối giữa kinh doanh và kỹ thuật: tìm hiểu quy trình và bài toán của khách hàng, thiết kế kiến trúc giải pháp, trình diễn sản phẩm, trả lời RFP, chạy thử nghiệm (POC) và lập phương án chi phí. Nghề đòi hỏi hiểu sâu sản phẩm, kiến trúc hệ thống, bảo mật và tích hợp, đồng thời trung thực về năng lực để thương vụ thắng bền vững và triển khai thành công.",en:"A pre-sales solutions consultant bridges sales and engineering: understanding the client's processes and problems, designing the solution architecture, demonstrating the product, answering RFPs, running proofs of concept (POC) and building the cost case. The role needs deep product, architecture, security and integration knowledge, plus honesty about capabilities so deals are won sustainably and delivered successfully."},responsibilities:{vi:["Tổ chức buổi khảo sát nhu cầu, lập bản đồ quy trình hiện tại và mục tiêu của khách hàng.","Thiết kế kiến trúc, định cỡ hạ tầng và chọn phương án triển khai phù hợp yêu cầu phi chức năng.","Trình diễn sản phẩm theo kịch bản nghiệp vụ và điều phối thử nghiệm POC.","Trả lời RFP, RFI, lập ma trận đáp ứng và bảng tính TCO, ROI.","Bàn giao phạm vi đã cam kết cho đội triển khai, tránh hụt kỳ vọng sau ký hợp đồng."],en:["Run discovery workshops and map the client's current and target processes.","Design the architecture, size the infrastructure and choose a deployment option that meets non-functional needs.","Deliver scenario-based demos and coordinate POCs.","Answer RFPs and RFIs, build the compliance matrix and the TCO and ROI sheets.","Hand the committed scope to the delivery team to avoid expectation gaps after signing."]},competencies:[{name:{vi:"Khám phá nhu cầu",en:"Discovery"},desc:{vi:"Đặt câu hỏi mở, tìm nỗi đau nghiệp vụ, tiêu chí quyết định và người phê duyệt kỹ thuật.",en:"Ask open questions to find business pain, decision criteria and technical approvers."}},{name:{vi:"Thiết kế giải pháp",en:"Solution design"},desc:{vi:"Kết hợp mô-đun, tích hợp, bảo mật và hạ tầng thành kiến trúc khả thi, có giới hạn rõ.",en:"Combine modules, integrations, security and infrastructure into a feasible architecture with clear limits."}},{name:{vi:"Trình diễn thuyết phục",en:"Compelling demos"},desc:{vi:"Trình diễn theo kịch bản của chính khách hàng, nhấn vào giá trị thay vì liệt kê tính năng.",en:"Demo the client's own scenarios and stress value instead of listing features."}},{name:{vi:"Kinh tế giải pháp",en:"Solution economics"},desc:{vi:"Tính TCO, ROI, so sánh mô hình cấp phép và chi phí một lần một cách minh bạch.",en:"Compute TCO and ROI and compare licensing models and one-time costs transparently."}},{name:{vi:"Trung thực về năng lực",en:"Capability honesty"},desc:{vi:"Ghi đúng mức đáp ứng, nêu khoảng trống và đề xuất giải pháp thay thế có ước lượng.",en:"State true compliance levels, disclose gaps and propose estimated alternatives."}}],knowledge:{vi:["Mô hình triển khai SaaS dùng chung, đám mây riêng, tại chỗ và mô hình trách nhiệm chia sẻ về bảo mật.","ISO/IEC 27001 về hệ thống quản lý an toàn thông tin và báo cáo SOC 2 khi khách hàng thẩm định nhà cung cấp.","Yêu cầu phi chức năng: hiệu năng, độ sẵn sàng theo SLA, khả năng mở rộng, tích hợp API, đăng nhập một lần (SSO).","Phương pháp tính TCO, ROI và các mô hình cấp phép theo người dùng định danh, đồng thời hoặc theo gói.","Quy định hiện hành về an ninh mạng và bảo vệ dữ liệu cá nhân, gồm yêu cầu lưu trữ dữ liệu tại Việt Nam trong một số trường hợp."],en:["Shared SaaS, private cloud and on-premise deployment models and the shared security responsibility model.","ISO/IEC 27001 for information security management and SOC 2 reports used in vendor due diligence.","Non-functional requirements: performance, SLA availability, scalability, API integration and single sign-on (SSO).","TCO and ROI methods and named-user, concurrent and bundle licensing models.","Current cybersecurity and personal data protection rules, including data localization in Vietnam in certain cases."]},tools:["Môi trường demo / sandbox","Công cụ vẽ kiến trúc giải pháp","Bảng tính TCO / ROI","Thư viện câu trả lời RFP","Hệ thống CRM"],kpis:{vi:["Tỷ lệ thắng kỹ thuật ở các thương vụ có pre-sales tham gia.","Thời gian hoàn thành hồ sơ RFP so với hạn nộp.","Tỷ lệ POC chuyển thành hợp đồng.","Số yêu cầu thay đổi phát sinh do cam kết sai phạm vi khi bán (mục tiêu bằng 0)."],en:["Technical win rate on deals with pre-sales involvement.","RFP completion time versus the submission deadline.","POC-to-contract conversion rate.","Change requests caused by mis-sold scope (target zero)."]},day:[{time:"08:30",vi:"Rà soát cơ hội mới trên CRM, chuẩn bị câu hỏi khảo sát cho từng khách hàng.",en:"Review new CRM opportunities and prepare discovery questions for each client."},{time:"10:00",vi:"Hội thảo khảo sát quy trình nhân sự, chấm công với nhà máy khách hàng.",en:"Discovery workshop on HR and time-attendance processes at a client plant."},{time:"13:30",vi:"Trình diễn sản phẩm theo kịch bản tính lương ca kíp của khách hàng.",en:"Demo the product using the client's shift payroll scenario."},{time:"15:30",vi:"Hoàn thiện ma trận đáp ứng RFP và bảng tính TCO, gửi rà soát nội bộ.",en:"Complete the RFP compliance matrix and TCO sheet for internal review."},{time:"17:00",vi:"Ghi chú bàn giao phạm vi cho đội triển khai và cập nhật CRM.",en:"Write scope handover notes for delivery and update the CRM."}],mistakes:{vi:["Chọn gói chuẩn rẻ nhất mà bỏ qua yêu cầu bắt buộc phi chức năng như nơi lưu trữ dữ liệu.","Tính TCO thiếu chi phí một lần hoặc chỉ tính 12 tháng cho hợp đồng nhiều năm.","Đánh đáp ứng đầy đủ cho tính năng chưa có, gây tranh chấp và lỗ khi triển khai."],en:["Picking the cheapest standard package while ignoring mandatory non-functional needs such as data residency.","Leaving one-time costs out of TCO or counting only 12 months of a multi-year contract.","Marking missing features fully compliant, causing disputes and losses in delivery."]},career:[{vi:"Kỹ sư hỗ trợ kỹ thuật / triển khai",en:"Support or implementation engineer"},{vi:"Chuyên viên tư vấn giải pháp (pre-sales)",en:"Pre-sales solutions consultant"},{vi:"Kiến trúc sư giải pháp cấp cao",en:"Senior solutions architect"},{vi:"Giám đốc tư vấn giải pháp",en:"Head of solutions consulting"}],glossary:[{term:"RFP",vi:"Hồ sơ mời đề xuất: tài liệu khách hàng nêu yêu cầu và tiêu chí đánh giá nhà cung cấp.",en:"Request for proposal: the client's document of requirements and vendor evaluation criteria."},{term:"POC",vi:"Thử nghiệm chứng minh khái niệm trên dữ liệu hoặc quy trình thật trong phạm vi giới hạn.",en:"Proof of concept on real data or processes within a limited scope."},{term:"TCO",vi:"Tổng chi phí sở hữu trong suốt kỳ sử dụng, gồm chi phí định kỳ và chi phí một lần.",en:"Total cost of ownership over the usage period, recurring plus one-time costs."},{term:"Compliance matrix",vi:"Ma trận đáp ứng: bảng ghi mức độ đáp ứng của giải pháp với từng yêu cầu.",en:"A table stating how the solution meets each requirement."},{term:"SSO",vi:"Đăng nhập một lần: người dùng xác thực một lần để truy cập nhiều ứng dụng.",en:"Single sign-on: users authenticate once to access several applications."}],quiz:[{q:{vi:"800 người dùng, đơn giá 5 USD/người dùng/tháng, hợp đồng 24 tháng, chi phí triển khai một lần 20000 USD. TCO là bao nhiêu?",en:"800 users at 5 USD per user per month, a 24-month contract and a one-time implementation of 20000 USD. What is the TCO?"},options:{vi:["96000 USD","116000 USD","68000 USD","136000 USD"],en:["96000 USD","116000 USD","68000 USD","136000 USD"]},answer:1,explain:{vi:"800 x 5 x 24 = 96000, cộng 20000 chi phí một lần = 116000 USD.",en:"800 x 5 x 24 = 96000, plus the 20000 one-time cost = 116000 USD."}},{q:{vi:"RFP bắt buộc lưu dữ liệu tại Việt Nam, còn gói chuẩn lưu ở nước ngoài. Bạn làm gì?",en:"The RFP mandates data storage in Vietnam but the standard package is hosted abroad. What do you do?"},options:{vi:["Đánh đáp ứng và hứa chuyển dữ liệu sau","Bỏ trống dòng yêu cầu đó","Chỉ ghi chú nhỏ ở phụ lục","Đề xuất phương án lưu trữ tại Việt Nam hoặc ghi rõ không đáp ứng"],en:["Mark it compliant and promise to move data later","Leave that requirement blank","Add a small note in an annex","Offer a Vietnam-hosted option or state non-compliance clearly"]},answer:3,explain:{vi:"Yêu cầu bắt buộc không đáp ứng sẽ bị loại hoặc gây vi phạm; phải có phương án phù hợp hoặc nói rõ.",en:"An unmet mandatory requirement leads to disqualification or breach; offer a fit or say so clearly."}},{q:{vi:"Giám đốc kinh doanh muốn đánh ‘Đáp ứng đầy đủ’ cho tính năng chưa có. Phương án đúng là gì?",en:"The sales director wants a missing feature marked ‘Fully compliant’. What is right?"},options:{vi:["Ghi đúng mức đáp ứng, báo cấp trên và đề xuất giải pháp thay thế có ước lượng","Làm theo vì đã có chỉ đạo","Xóa yêu cầu khỏi ma trận","Đánh đáp ứng nhưng tăng giá dự phòng"],en:["State the true level, escalate and propose an estimated alternative","Comply because it is an instruction","Delete the requirement from the matrix","Mark it compliant but add a hidden buffer"]},answer:0,explain:{vi:"Khai năng lực không có thật là gian dối trong chào thầu và dẫn tới tranh chấp hợp đồng.",en:"Claiming non-existent capability is misrepresentation in bidding and leads to contract disputes."}},{q:{vi:"Tiêu chuẩn nào quy định hệ thống quản lý an toàn thông tin có thể được chứng nhận?",en:"Which standard specifies a certifiable information security management system?"},options:{vi:["ISO 9001","ISO 14001","ISO/IEC 27001","ISO 45001"],en:["ISO 9001","ISO 14001","ISO/IEC 27001","ISO 45001"]},answer:2,explain:{vi:"ISO/IEC 27001 quy định yêu cầu cho ISMS; ISO 9001 là chất lượng, 14001 là môi trường, 45001 là an toàn lao động.",en:"ISO/IEC 27001 sets ISMS requirements; 9001 is quality, 14001 environment and 45001 occupational safety."}}],tools_en:["Demo / sandbox environment","Solution architecture diagramming tool","TCO / ROI spreadsheet","RFP response library","CRM system"]}},"KK-289":{scenario:{company:"Cao Nguyên Xanh Realty",supervisor:{name:"Lò Hoàng Nam",role:{vi:"Trưởng sàn Giao dịch Bất động sản",en:"Brokerage Floor Manager"}},ref_code:"BDS-4418",title:{vi:"Đúng pháp lý. Đúng lợi suất. Đúng khách hàng.",en:"Right title. Right yield. Right client."},brief:{vi:"Đây là tình huống đào tạo. Khách là cá nhân người nước ngoài, ngân sách tối đa 4,5 tỷ đồng, cần căn 2 phòng ngủ để cho thuê. Giỏ hàng: A-1205 (2PN, 4,2 tỷ, tòa A đã đủ hạn mức 30% căn hộ cho người nước ngoài), B-0807 (2PN, 4,4 tỷ, tòa B mới đạt 22%), C-1510 (3PN, 5,1 tỷ). Giá thuê dự kiến 18 triệu đồng/tháng. Sửa căn đề xuất và lợi suất cho thuê ròng (số liệu mô phỏng), rồi lập báo cáo tư vấn có căn cứ.",en:"This is a training scenario. The client is a foreign individual with a budget of up to 4.5 billion VND who needs a 2-bedroom unit to rent out. Inventory: A-1205 (2BR, 4.2 bn, Tower A already at the 30% foreign ownership cap), B-0807 (2BR, 4.4 bn, Tower B at 22%), C-1510 (3BR, 5.1 bn). Expected rent 18 million VND per month. Correct the recommended unit and the net rental yield (training figures), then write an evidence-based advisory report."},reference_title:{vi:"Hồ sơ pháp lý giỏ hàng & bảng phân tích dòng tiền đã duyệt · BDS-4418",en:"Approved inventory legal file & cash flow sheet · BDS-4418"},fields:[{id:"UNIT_CODE",label:{vi:"Căn hộ đề xuất",en:"Recommended unit"},initial:"A-1205",expected:"B-0807",choices:["A-1205","B-0807","C-1510"],reference:"Hồ sơ pháp lý giỏ hàng",hint:{vi:"Lọc theo ba điều kiện cùng lúc: số phòng ngủ, ngân sách và hạn mức sở hữu của người nước ngoài từng tòa.",en:"Filter on three conditions at once: bedrooms, budget and each tower's foreign ownership quota."}},{id:"NET_YIELD",label:{vi:"Lợi suất cho thuê ròng (%)",en:"Net rental yield (%)"},initial:"5.14",expected:"3.57",reference:"Bảng phân tích dòng tiền",ref_value:{vi:"Giá 4400 triệu; chi phí mua 2%; thuê 18 triệu x 11 tháng; thuế 10% doanh thu thuê; vận hành 18 triệu/năm",en:"Price 4400 million; purchase costs 2%; rent 18 million x 11 months; tax 10% of rent; operating 18 million/year"},hint:{vi:"Lợi suất gộp chưa trừ tháng trống, thuế, chi phí vận hành và chưa cộng chi phí mua vào vốn đầu tư.",en:"Gross yield ignores the vacant month, tax, operating costs and the purchase costs in the investment base."}}],sop32:{vi:"Lợi suất ròng (%) = (tiền thuê thu được 11 tháng/năm - thuế cho thuê 10% doanh thu - chi phí vận hành năm) / (giá mua + chi phí mua 2%) x 100, làm tròn 2 chữ số thập phân. Tỷ lệ trong bài là số liệu mô phỏng.",en:"Net yield (%) = (rent collected over 11 months - rental tax 10% of revenue - annual operating cost) / (price + 2% purchase costs) x 100, rounded to 2 decimals. Rates are training figures."},context:{label:"CRM / BDS-4418",metrics:[{label:{vi:"Ngân sách khách hàng",en:"Client budget"},value:"4.5 bn VND"},{label:{vi:"Hạn mức sở hữu nước ngoài",en:"Foreign ownership cap"},value:"30%"},{label:{vi:"Tỷ lệ đã dùng tòa B",en:"Tower B quota used"},value:"22%"},{label:{vi:"Giá thuê dự kiến",en:"Expected rent"},value:"18,000,000 VND"}]},crisis:{vi:"Đại diện chủ đầu tư nhắn: “Khách thích A-1205 thì cứ để một người Việt đứng tên hộ, ký thêm giấy ủy quyền riêng. Chốt cọc trong tuần này thì sàn được thưởng nóng.”",en:"The developer's representative messages you: “If the client likes A-1205, just put it under a Vietnamese nominee with a private power of attorney. Close the deposit this week and the floor gets a bonus.”"},options:{safe:{vi:"Từ chối phương án đứng tên hộ, giải thích rủi ro pháp lý cho khách và báo Trưởng sàn; đề xuất căn B-0807 còn hạn mức hoặc phương án thuê dài hạn hợp lệ.",en:"Refuse the nominee scheme, explain the legal risk to the client and inform the floor manager; propose B-0807 within quota or a lawful long-term lease."},shortcut:{vi:"Đồng ý cho người Việt đứng tên hộ để chốt cọc kịp nhận thưởng.",en:"Agree to the nominee arrangement to close the deposit and earn the bonus."},wait:{vi:"Không trả lời chủ đầu tư và để khách tự tìm cách mua căn A-1205.",en:"Ignore the developer and let the client find their own way to buy A-1205."}},questions:{vi:["Vì sao đề xuất B-0807 thay vì A-1205 hay C-1510? Căn cứ pháp lý và tiêu chí nào loại hai căn còn lại?","Trình bày cách tính lợi suất ròng và rủi ro cho khách nếu chỉ nhìn lợi suất gộp hoặc mua qua người đứng tên hộ."],en:["Why recommend B-0807 instead of A-1205 or C-1510? Which legal basis and criteria rule out the other two?","Explain the net yield calculation and the client's risk of relying on gross yield or buying through a nominee."]},hints:{vi:["Đặt bản nháp cạnh hồ sơ pháp lý giỏ hàng, kiểm tra tình trạng hạn mức sở hữu nước ngoài của từng tòa.","Tính theo SOP mục 3.2: thu nhập thực sau tháng trống, thuế và chi phí chia cho tổng vốn đầu tư.","Đọc lại SOP mục 4.2: không tư vấn lách luật; mọi đề nghị đứng tên hộ phải từ chối và báo cáo."],en:["Place the draft next to the inventory legal file and check each tower's foreign ownership quota.","Compute per SOP 3.2: real income after vacancy, tax and costs divided by the total investment.","Re-read SOP 4.2: never advise ways around the law; any nominee request must be refused and escalated."]}},learning:{summary:{vi:"Chuyên viên tư vấn và môi giới bất động sản giúp khách mua, bán, thuê hoặc đầu tư nhà đất: tìm hiểu mục tiêu tài chính, thẩm định pháp lý sản phẩm, phân tích giá và dòng tiền, dẫn xem thực tế, đàm phán và đồng hành đến khi ký hợp đồng, bàn giao. Nghề đòi hỏi nắm vững pháp luật đất đai, nhà ở, kinh doanh bất động sản, có chứng chỉ hành nghề và hoạt động qua doanh nghiệp dịch vụ môi giới, đặt quyền lợi hợp pháp của khách hàng lên trên hoa hồng.",en:"A real estate investment consultant helps clients buy, sell, lease or invest in property: clarifying financial goals, checking the legal status of products, analyzing price and cash flow, arranging viewings, negotiating and supporting clients through contract and handover. The role requires solid knowledge of land, housing and real estate business law, a practice certificate and work through a licensed brokerage firm, and putting the client's lawful interests above commission."},responsibilities:{vi:["Khảo sát nhu cầu, ngân sách, mục tiêu ở hay đầu tư và khẩu vị rủi ro của khách hàng.","Thẩm định pháp lý dự án, căn hộ: giấy chứng nhận, giấy phép xây dựng, điều kiện mở bán, bảo lãnh ngân hàng.","Phân tích giá so sánh, lợi suất cho thuê và dòng tiền vay vốn cho từng phương án.","Dẫn khách xem thực tế, đàm phán giá, điều khoản thanh toán và soạn thỏa thuận đặt cọc theo mẫu đã duyệt.","Theo dõi ký hợp đồng, thanh toán, bàn giao và chăm sóc khách sau giao dịch."],en:["Assess the client's needs, budget, live-in or investment goal and risk appetite.","Check project and unit legal status: certificates, building permit, sale conditions and bank guarantee.","Analyze comparable prices, rental yield and financed cash flow for each option.","Arrange viewings, negotiate price and payment terms and prepare deposit agreements on approved templates.","Follow contract signing, payments and handover, and care for clients after the deal."]},competencies:[{name:{vi:"Thẩm định pháp lý",en:"Legal due diligence"},desc:{vi:"Đọc giấy chứng nhận, quy hoạch, giấy phép và điều kiện chuyển nhượng, phát hiện rủi ro tranh chấp.",en:"Read certificates, zoning, permits and transfer conditions to spot dispute risks."}},{name:{vi:"Phân tích đầu tư",en:"Investment analysis"},desc:{vi:"Tính lợi suất gộp, ròng, dòng tiền vay và so sánh giá thị trường một cách thận trọng.",en:"Compute gross and net yield and financed cash flow and compare market prices prudently."}},{name:{vi:"Tư vấn & đàm phán",en:"Advisory & negotiation"},desc:{vi:"Lắng nghe mục tiêu khách, trình bày phương án rõ ràng và đàm phán điều khoản cân bằng.",en:"Listen to client goals, present options clearly and negotiate balanced terms."}},{name:{vi:"Hiểu biết thị trường",en:"Market knowledge"},desc:{vi:"Theo dõi nguồn cung, giá giao dịch, hạ tầng và chính sách tín dụng theo khu vực.",en:"Track supply, transaction prices, infrastructure and credit policy by area."}},{name:{vi:"Liêm chính & tuân thủ",en:"Integrity & compliance"},desc:{vi:"Không cam kết lợi nhuận, không tư vấn lách luật, nhận diện và báo cáo giao dịch đáng ngờ.",en:"Never guarantee returns or advise around the law; identify and report suspicious transactions."}}],knowledge:{vi:["Luật Kinh doanh bất động sản 2023: điều kiện hành nghề môi giới, chứng chỉ hành nghề và điều kiện bán nhà ở hình thành trong tương lai.","Luật Nhà ở 2023: quyền sở hữu nhà ở của tổ chức, cá nhân nước ngoài và hạn mức 30% số căn hộ mỗi tòa chung cư.","Luật Đất đai 2024: giấy chứng nhận, quy hoạch sử dụng đất và điều kiện chuyển nhượng.","Luật Phòng, chống rửa tiền 2022: nhận biết khách hàng và báo cáo giao dịch đáng ngờ trong kinh doanh bất động sản.","Phương pháp định giá so sánh, phương pháp thu nhập và chỉ số lợi suất gộp, lợi suất ròng."],en:["Real Estate Business Law 2023: brokerage practice conditions, practice certificates and conditions for selling off-plan housing.","Housing Law 2023: foreign ownership rights and the 30% cap on apartments per building.","Land Law 2024: land use certificates, land use planning and transfer conditions.","Anti-Money Laundering Law 2022: customer due diligence and suspicious transaction reporting in real estate.","Sales comparison and income valuation methods and gross versus net yield."]},tools:["Hệ thống CRM bất động sản","Phần mềm quản lý giỏ hàng","Bảng tính phân tích dòng tiền","Bản đồ quy hoạch trực tuyến","Công cụ tham quan ảo 360 độ"],kpis:{vi:["Số giao dịch thành công và giá trị giao dịch mỗi quý.","Tỷ lệ chuyển đổi từ khách xem nhà sang đặt cọc.","Tỷ lệ hủy cọc hoặc khiếu nại do tư vấn sai (mục tiêu bằng 0).","Điểm hài lòng và tỷ lệ khách giới thiệu khách mới."],en:["Closed deals and transaction value per quarter.","Viewing-to-deposit conversion rate.","Deposit cancellations or complaints caused by wrong advice (target zero).","Satisfaction score and referral rate."]},day:[{time:"08:30",vi:"Cập nhật tin thị trường, giỏ hàng và tình trạng hạn mức sở hữu nước ngoài từng tòa.",en:"Update market news, inventory and each tower's foreign ownership quota."},{time:"10:00",vi:"Dẫn khách xem căn hộ mẫu và tiện ích thực tế của dự án.",en:"Show a client the model unit and the project's actual amenities."},{time:"13:30",vi:"Lập bảng phân tích dòng tiền, lợi suất cho từng căn trong danh sách rút gọn.",en:"Build cash flow and yield sheets for each shortlisted unit."},{time:"15:30",vi:"Kiểm tra pháp lý dự án: giấy phép xây dựng, bảo lãnh ngân hàng, văn bản đủ điều kiện bán.",en:"Check project legal papers: building permit, bank guarantee and sale eligibility notice."},{time:"17:30",vi:"Cập nhật CRM, gửi báo cáo tư vấn và lịch hẹn tiếp theo cho khách.",en:"Update the CRM and send the advisory report and next appointment to the client."}],mistakes:{vi:["Đề xuất căn ở tòa đã đủ hạn mức sở hữu cho khách nước ngoài.","Quảng cáo lợi suất gộp như lợi nhuận thực, bỏ qua tháng trống, thuế và chi phí.","Hứa cam kết lợi nhuận hoặc tư vấn đứng tên hộ để chốt giao dịch nhanh."],en:["Recommending a unit in a tower whose foreign quota is already full.","Selling gross yield as real profit while ignoring vacancy, tax and costs.","Guaranteeing returns or suggesting nominee ownership to close faster."]},career:[{vi:"Cộng tác viên / thực tập sinh môi giới",en:"Brokerage trainee"},{vi:"Chuyên viên tư vấn bất động sản (có chứng chỉ hành nghề)",en:"Licensed real estate consultant"},{vi:"Trưởng nhóm kinh doanh sàn giao dịch",en:"Brokerage sales team lead"},{vi:"Giám đốc sàn / Giám đốc tư vấn đầu tư bất động sản",en:"Brokerage or real estate investment director"}],glossary:[{term:"Net yield",vi:"Lợi suất ròng: thu nhập cho thuê sau thuế, chi phí và tháng trống chia cho tổng vốn đầu tư.",en:"Rental income after tax, costs and vacancy divided by the total investment."},{term:"Thông thủy",vi:"Diện tích sử dụng căn hộ tính theo kích thước thông thủy, dùng ghi trong hợp đồng mua bán.",en:"Net usable floor area of an apartment, used in the sale contract."},{term:"Off-plan",vi:"Nhà ở hình thành trong tương lai: đang xây dựng, chưa nghiệm thu đưa vào sử dụng.",en:"Housing still under construction and not yet accepted for use."},{term:"Đặt cọc",vi:"Khoản tiền bảo đảm giao kết hoặc thực hiện hợp đồng, có điều khoản phạt cọc rõ ràng.",en:"A deposit securing the signing or performance of a contract, with clear forfeiture terms."},{term:"KYC",vi:"Nhận biết khách hàng: xác minh danh tính, nguồn tiền theo quy định phòng, chống rửa tiền.",en:"Know your customer: verifying identity and source of funds under anti-money laundering rules."}],quiz:[{q:{vi:"Căn hộ giá 3000 triệu đồng, cho thuê 15 triệu đồng/tháng đủ 12 tháng. Lợi suất gộp là bao nhiêu?",en:"A unit costs 3000 million VND and rents for 15 million VND per month for 12 months. What is the gross yield?"},options:{vi:["5%","6%","6,5%","7,2%"],en:["5%","6%","6.5%","7.2%"]},answer:1,explain:{vi:"15 x 12 = 180 triệu; 180 / 3000 = 6%. Lợi suất ròng sẽ thấp hơn sau thuế, chi phí và tháng trống.",en:"15 x 12 = 180 million; 180 / 3000 = 6%. Net yield is lower after tax, costs and vacancy."}},{q:{vi:"Theo Luật Nhà ở, tổ chức, cá nhân nước ngoài được sở hữu tối đa bao nhiêu phần trăm số căn hộ trong một tòa chung cư?",en:"Under the Housing Law, what share of apartments in one building may foreign entities and individuals own at most?"},options:{vi:["10%","20%","30%","50%"],en:["10%","20%","30%","50%"]},answer:2,explain:{vi:"Hạn mức là 30% số căn hộ của một tòa nhà chung cư; khi tòa đã đủ, người nước ngoài không mua thêm được.",en:"The cap is 30% of the apartments in a building; once reached, foreigners cannot buy more there."}},{q:{vi:"Khách nước ngoài muốn mua căn ở tòa đã đủ hạn mức và đề nghị nhờ người Việt đứng tên hộ. Bạn làm gì?",en:"A foreign client wants a unit in a tower at its quota and suggests a Vietnamese nominee. What do you do?"},options:{vi:["Từ chối, giải thích rủi ro pháp lý và đề xuất căn còn hạn mức","Giới thiệu người đứng tên quen biết","Đồng ý nếu khách ký cam kết tự chịu","Im lặng để khách tự xử lý"],en:["Refuse, explain the legal risk and offer a unit within quota","Introduce a nominee you know","Agree if the client signs a waiver","Stay silent and let the client handle it"]},answer:0,explain:{vi:"Đứng tên hộ là lách luật, khách có thể mất tài sản khi tranh chấp; môi giới phải tư vấn phương án hợp pháp.",en:"Nominee ownership circumvents the law and the client may lose the asset in a dispute; advise lawful options."}},{q:{vi:"Diện tích căn hộ ghi trong hợp đồng mua bán theo quy định hiện hành là diện tích nào?",en:"Under current rules, which area is stated in an apartment sale contract?"},options:{vi:["Diện tích tim tường","Diện tích sàn xây dựng toàn tòa","Diện tích có ban công tính gấp đôi","Diện tích sử dụng tính theo kích thước thông thủy"],en:["Wall-centerline area","Gross floor area of the building","Area with balconies counted twice","Net usable area measured wall to wall"]},answer:3,explain:{vi:"Hợp đồng mua bán căn hộ ghi diện tích sử dụng thông thủy; tư vấn giá trên diện tích tim tường dễ gây hiểu nhầm.",en:"Apartment contracts state the net usable area; quoting price on centerline area misleads clients."}}],tools_en:["Real estate CRM system","Unit inventory management software","Cash flow analysis spreadsheet","Online land-use planning map","360-degree virtual tour tools"]}},"KK-290":{scenario:{company:"Kim Ngưu Foods",supervisor:{name:"Vũ Đức Thắng",role:{vi:"Giám đốc Kinh doanh Toàn quốc",en:"National Sales Director"}},ref_code:"PLAN-MT27",title:{vi:"Đúng kênh. Đúng chỉ tiêu. Đúng doanh thu.",en:"Right channel. Right target. Right revenue."},brief:{vi:"Bạn hoàn thiện kế hoạch kinh doanh quý 1 miền Trung PLAN-MT27 với chỉ tiêu vùng 24000 triệu đồng. Quảng Ngãi chiếm 15% doanh số năm trước nhưng 25% tiềm năng thị trường (chỉ số mô phỏng). Hợp đồng độc quyền với nhà phân phối hiện tại ở Quảng Ngãi còn hiệu lực đến 12/2027; chính sách công ty không bán trực tiếp cho điểm bán lẻ. Sửa phương án mở rộng độ phủ và chỉ tiêu quý của Quảng Ngãi, rồi lập báo cáo có căn cứ.",en:"You are finalizing the Q1 Central region sales plan PLAN-MT27 with a regional target of 24000 million VND. Quang Ngai holds 15% of last year's sales but 25% of market potential (training index). The exclusive contract with the current Quang Ngai distributor runs until 12/2027, and company policy forbids selling directly to retail outlets. Correct the coverage expansion option and Quang Ngai's quarterly target, then write an evidence-based report."},reference_title:{vi:"Chính sách kênh & bảng phân bổ chỉ tiêu đã duyệt · PLAN-MT27",en:"Approved channel policy & target allocation sheet · PLAN-MT27"},fields:[{id:"COVER_MODEL",label:{vi:"Phương án mở rộng độ phủ",en:"Coverage expansion option"},initial:"NEW-DIST",expected:"SUB-DIST",choices:["NEW-DIST","SUB-DIST","DIRECT"],reference:"Chính sách kênh phân phối",hint:{vi:"Kiểm tra điều khoản độc quyền lãnh thổ và chính sách bán hàng trực tiếp trước khi chọn mô hình.",en:"Check the territory exclusivity clause and the direct sales policy before choosing a model."}},{id:"QNG_TARGET",label:{vi:"Chỉ tiêu quý Quảng Ngãi (triệu VND)",en:"Quang Ngai quarterly target (million VND)"},initial:"3600",expected:"4560",reference:"Bảng phân bổ chỉ tiêu",ref_value:{vi:"Chỉ tiêu vùng 24000 triệu; Quảng Ngãi: 15% doanh số năm trước, 25% tiềm năng thị trường",en:"Regional target 24000 million; Quang Ngai: 15% of last year's sales, 25% of market potential"},hint:{vi:"Bản nháp chỉ dùng tỷ trọng lịch sử; mô hình đã duyệt còn tính trọng số tiềm năng.",en:"The draft uses only the historical share; the approved model also weights market potential."}}],sop32:{vi:"Chỉ tiêu tỉnh = chỉ tiêu vùng x (60% x tỷ trọng doanh số năm trước + 40% x tỷ trọng tiềm năng thị trường). Đơn vị triệu đồng; trọng số là số liệu mô phỏng.",en:"Province target = regional target x (60% x share of last year's sales + 40% x share of market potential). Unit million VND; weights are training figures."},context:{label:"SALES PLAN / PLAN-MT27",metrics:[{label:{vi:"Chỉ tiêu vùng",en:"Regional target"},value:"24,000 m VND"},{label:{vi:"Tỷ trọng doanh số QNg",en:"Quang Ngai sales share"},value:"15%"},{label:{vi:"Tỷ trọng tiềm năng QNg",en:"Quang Ngai potential share"},value:"25%"},{label:{vi:"Độc quyền NPP đến",en:"Distributor exclusivity until"},value:"12/2027"}]},crisis:{vi:"Giám sát khu vực Quảng Ngãi đề xuất: “Cuối quý còn hụt 2000 triệu. Anh duyệt cho nhà phân phối nhận thêm hàng, hứa miệng quý sau cho trả lại, xuất hóa đơn trước để đạt chỉ tiêu.”",en:"The Quang Ngai area supervisor proposes: “We are 2000 million short at quarter end. Approve extra stock for the distributor with a verbal promise to take it back next quarter, invoice now to hit the target.”"},options:{safe:{vi:"Không duyệt đẩy hàng kèm cam kết trả lại ngoài hợp đồng; báo Giám đốc Kinh doanh Toàn quốc và tài chính, nộp dự báo thực tế và đề xuất chương trình sell-out đã phê duyệt.",en:"Reject stock loading with an off-contract return promise; inform the National Sales Director and finance, submit a realistic forecast and propose an approved sell-out program."},shortcut:{vi:"Duyệt xuất hóa đơn đẩy hàng cho đạt chỉ tiêu, quý sau xử lý hàng trả lại.",en:"Approve the invoiced stock push to hit the target and handle returns next quarter."},wait:{vi:"Không trả lời giám sát và để báo cáo quý tự phản ánh kết quả.",en:"Do not answer the supervisor and let the quarterly report speak for itself."}},questions:{vi:["Vì sao chọn SUB-DIST thay vì NEW-DIST hay DIRECT? Điều khoản hợp đồng và chính sách nào quyết định?","Trình bày cách phân bổ chỉ tiêu Quảng Ngãi và rủi ro doanh thu, tài chính khi đẩy hàng kèm cam kết trả lại."],en:["Why choose SUB-DIST over NEW-DIST or DIRECT? Which contract clause and policy decide it?","Explain the Quang Ngai target allocation and the revenue and financial risk of loading stock with a return promise."]},hints:{vi:["Đặt bản nháp cạnh chính sách kênh, đánh dấu phương án nào vi phạm hợp đồng độc quyền hoặc chính sách.","Áp dụng công thức trọng số ở SOP mục 3.2 cho đúng hai tỷ trọng của tỉnh.","Đọc lại SOP mục 4.2: doanh thu phải phản ánh giao dịch thật; cam kết ngoài hợp đồng phải được báo cáo."],en:["Place the draft next to the channel policy and flag which option breaches exclusivity or policy.","Apply the weighted formula in SOP 3.2 to the province's two shares.","Re-read SOP 4.2: revenue must reflect real transactions; side promises must be escalated."]}},learning:{summary:{vi:"Quản lý kinh doanh khu vực chịu trách nhiệm doanh số, độ phủ và lợi nhuận của một vùng: xây dựng kế hoạch, phân bổ chỉ tiêu, dẫn dắt đội giám sát và nhân viên bán hàng, phát triển và đánh giá nhà phân phối, triển khai chương trình thương mại và dự báo doanh số. Vai trò đòi hỏi tư duy chiến lược dựa trên dữ liệu, năng lực lãnh đạo đội ngũ phân tán và kỷ luật tuân thủ trong ghi nhận doanh thu và chính sách kênh.",en:"A regional sales manager owns the sales, coverage and profit of a region: building the plan, allocating targets, leading supervisors and sales reps, developing and reviewing distributors, rolling out trade programs and forecasting sales. The role needs data-driven strategic thinking, leadership of a dispersed team and discipline in revenue recognition and channel policy."},responsibilities:{vi:["Lập kế hoạch kinh doanh vùng, phân bổ chỉ tiêu theo tỉnh, kênh và ngành hàng.","Quản trị nhà phân phối: tồn kho, công nợ, độ phủ, nhân sự bán hàng và tuân thủ chính sách giá.","Huấn luyện giám sát, đi tuyến thị trường và đánh giá năng suất nhân viên bán hàng.","Triển khai chương trình thương mại, đo hiệu quả và đề xuất điều chỉnh ngân sách.","Dự báo doanh số tuần, tháng, quý và báo cáo khoảng cách so với kế hoạch."],en:["Build the regional plan and allocate targets by province, channel and category.","Manage distributors: stock, receivables, coverage, sales staff and price policy compliance.","Coach supervisors, ride routes in the market and review rep productivity.","Roll out trade programs, measure results and propose budget changes.","Forecast weekly, monthly and quarterly sales and report gaps against plan."]},competencies:[{name:{vi:"Hoạch định vùng & chỉ tiêu",en:"Territory & target planning"},desc:{vi:"Kết hợp dữ liệu lịch sử, tiềm năng và năng lực kênh để đặt chỉ tiêu thách thức nhưng khả thi.",en:"Combine history, potential and channel capacity to set stretching yet achievable targets."}},{name:{vi:"Quản trị kênh phân phối",en:"Channel management"},desc:{vi:"Thiết kế độ phủ, đánh giá nhà phân phối và xử lý xung đột kênh theo hợp đồng.",en:"Design coverage, evaluate distributors and resolve channel conflicts by contract."}},{name:{vi:"Lãnh đạo đội ngũ",en:"Team leadership"},desc:{vi:"Tuyển chọn, huấn luyện, giao mục tiêu và giữ kỷ luật cho đội bán hàng phân tán.",en:"Select, coach, set goals for and keep discipline in a dispersed sales team."}},{name:{vi:"Phân tích & dự báo",en:"Analysis & forecasting"},desc:{vi:"Đọc báo cáo sell-in, sell-out, tồn kho để dự báo sát và phát hiện rủi ro sớm.",en:"Read sell-in, sell-out and stock data to forecast accurately and spot risks early."}},{name:{vi:"Liêm chính thương mại",en:"Commercial integrity"},desc:{vi:"Không đẩy hàng ảo, không cam kết ngoài hợp đồng, báo cáo số liệu trung thực.",en:"No fake stock loading or side promises; report figures truthfully."}}],knowledge:{vi:["Mô hình phân bổ chỉ tiêu theo doanh số lịch sử, tiềm năng thị trường và năng lực độ phủ.","Chỉ số phân phối: độ phủ số, độ phủ có trọng số, số điểm bán hoạt động, số SKU mỗi điểm bán.","Quản trị nhà phân phối: tồn kho theo ngày bán (DOS), công nợ, chính sách giá, lãnh thổ độc quyền.","VAS 14 và IFRS 15 về ghi nhận doanh thu, gồm ảnh hưởng của quyền trả lại hàng.","Luật Cạnh tranh 2018 về thỏa thuận hạn chế cạnh tranh và Luật Thương mại 2005 về đại lý thương mại."],en:["Target allocation models based on sales history, market potential and coverage capacity.","Distribution metrics: numeric and weighted distribution, active outlets and SKUs per outlet.","Distributor management: days of stock (DOS), receivables, price policy and exclusive territories.","VAS 14 and IFRS 15 on revenue recognition, including the effect of return rights.","Competition Law 2018 on anti-competitive agreements and Commercial Law 2005 on commercial agency."]},tools:["Hệ thống DMS quản lý nhà phân phối","Hệ thống CRM / SFA","Bảng điều khiển BI doanh số","Bảng tính phân bổ chỉ tiêu","Ứng dụng giám sát đi tuyến"],kpis:{vi:["Tỷ lệ đạt chỉ tiêu doanh số và sản lượng theo tỉnh.","Độ phủ số và số điểm bán hoạt động hằng tháng.","Tồn kho nhà phân phối theo ngày bán trong ngưỡng chính sách.","Sai số dự báo doanh số quý."],en:["Sales and volume target achievement by province.","Numeric distribution and active outlets per month.","Distributor days of stock within the policy range.","Quarterly sales forecast error."]},day:[{time:"07:30",vi:"Họp trực tuyến đầu ngày với các giám sát, rà soát doanh số hôm qua.",en:"Morning online huddle with supervisors to review yesterday's sales."},{time:"09:00",vi:"Đi tuyến cùng nhân viên bán hàng, kiểm tra trưng bày và giá tại điểm bán.",en:"Ride a route with a rep and check displays and prices in outlets."},{time:"13:30",vi:"Làm việc với nhà phân phối về tồn kho, công nợ và kế hoạch mở điểm bán.",en:"Meet a distributor on stock, receivables and outlet expansion."},{time:"15:30",vi:"Phân tích bảng BI, điều chỉnh phân bổ chỉ tiêu và ngân sách khuyến mại.",en:"Analyze BI dashboards and adjust target and promotion allocations."},{time:"17:30",vi:"Gửi dự báo tuần và báo cáo khoảng cách kế hoạch cho giám đốc toàn quốc.",en:"Send the weekly forecast and gap report to the national director."}],mistakes:{vi:["Phân bổ chỉ tiêu chỉ theo doanh số năm trước, bỏ lỡ tỉnh có tiềm năng lớn.","Bổ nhiệm nhà phân phối mới chồng lấn lãnh thổ độc quyền, gây xung đột và tranh chấp hợp đồng.","Đẩy hàng cuối kỳ kèm cam kết trả lại, làm sai lệch doanh thu và tồn kho kênh."],en:["Allocating targets on last year's sales only and missing high-potential provinces.","Appointing a new distributor inside an exclusive territory, causing conflict and contract disputes.","Loading stock at period end with return promises, distorting revenue and channel stock."]},career:[{vi:"Giám sát bán hàng",en:"Sales supervisor"},{vi:"Quản lý bán hàng khu vực (ASM)",en:"Area Sales Manager"},{vi:"Quản lý kinh doanh vùng (RSM)",en:"Regional Sales Manager"},{vi:"Giám đốc kinh doanh toàn quốc",en:"National Sales Director"}],glossary:[{term:"Numeric distribution",vi:"Độ phủ số: tỷ lệ điểm bán có hàng trên tổng số điểm bán trong vùng.",en:"Share of outlets stocking the product among all outlets in the area."},{term:"DOS",vi:"Số ngày tồn kho: lượng tồn đủ bán bao nhiêu ngày theo tốc độ bán hiện tại.",en:"Days of stock: how many days current stock lasts at the current sales rate."},{term:"Sell-in / Sell-out",vi:"Hàng công ty bán vào nhà phân phối so với hàng nhà phân phối bán ra thị trường.",en:"Company sales into distributors versus distributor sales out to the market."},{term:"Channel stuffing",vi:"Đẩy hàng vào kênh vượt nhu cầu thực để làm đẹp doanh số kỳ báo cáo.",en:"Pushing stock into the channel beyond real demand to inflate period sales."},{term:"Sub-distributor",vi:"Nhà phân phối cấp 2 nhận hàng từ nhà phân phối chính để phủ vùng sâu, vùng xa.",en:"A second-tier distributor supplied by the main distributor to reach remote areas."}],quiz:[{q:{vi:"Chỉ tiêu vùng 20000 triệu; tỉnh X chiếm 30% doanh số năm trước và 20% tiềm năng; trọng số 60/40. Chỉ tiêu tỉnh X là bao nhiêu?",en:"Regional target 20000 million; province X has 30% of last year's sales and 20% of potential; weights 60/40. What is X's target?"},options:{vi:["6000 triệu","5200 triệu","4000 triệu","5600 triệu"],en:["6000 million","5200 million","4000 million","5600 million"]},answer:1,explain:{vi:"20000 x (0,6 x 30% + 0,4 x 20%) = 20000 x 26% = 5200 triệu.",en:"20000 x (0.6 x 30% + 0.4 x 20%) = 20000 x 26% = 5200 million."}},{q:{vi:"Số ngày tồn kho (DOS) của nhà phân phối là 45 ngày nghĩa là gì?",en:"What does a distributor DOS of 45 days mean?"},options:{vi:["Tồn kho đủ bán 45 ngày theo tốc độ bán hiện tại","Công nợ quá hạn 45 ngày","Hàng đã hết hạn sau 45 ngày","Đơn hàng giao trễ 45 ngày"],en:["Stock lasts 45 days at the current sales rate","Receivables are 45 days overdue","Goods expire after 45 days","Orders are delivered 45 days late"]},answer:0,explain:{vi:"DOS = tồn kho / bán ra bình quân ngày; DOS quá cao báo hiệu tồn ứ, nguy cơ cận date.",en:"DOS = stock / average daily sales; a high DOS signals overstock and expiry risk."}},{q:{vi:"Hợp đồng độc quyền với nhà phân phối còn hiệu lực, vùng cần tăng độ phủ. Phương án phù hợp là gì?",en:"The distributor's exclusive contract is still valid and coverage must grow. What fits?"},options:{vi:["Bổ nhiệm thêm nhà phân phối mới cùng lãnh thổ","Bán trực tiếp cho điểm lẻ bất chấp chính sách","Phát triển nhà phân phối cấp 2 dưới nhà phân phối hiện tại và đồng đầu tư đội bán hàng","Chờ hết hợp đồng mới làm gì đó"],en:["Appoint another distributor in the same territory","Sell directly to outlets against policy","Develop sub-distributors under the current distributor and co-invest in sales staff","Do nothing until the contract expires"]},answer:2,explain:{vi:"Mở rộng qua cấp 2 tôn trọng hợp đồng độc quyền và chính sách, vẫn tăng được độ phủ.",en:"Expanding through sub-distributors respects exclusivity and policy while growing coverage."}},{q:{vi:"Cấp dưới đề nghị đẩy hàng cuối quý cho nhà phân phối và hứa miệng cho trả lại. Bạn làm gì?",en:"A subordinate proposes loading stock at quarter end with a verbal return promise. What do you do?"},options:{vi:["Duyệt vì giúp đạt chỉ tiêu","Duyệt nhưng không ghi vào biên bản","Để nhà phân phối tự quyết","Từ chối, báo cấp trên và tài chính, nộp dự báo thực tế"],en:["Approve it to hit the target","Approve it without recording it","Let the distributor decide","Refuse, escalate to management and finance, submit a real forecast"]},answer:3,explain:{vi:"Cam kết trả lại ngoài hợp đồng làm sai doanh thu và che giấu rủi ro; phải từ chối và báo cáo.",en:"Off-contract return promises misstate revenue and hide risk; refuse and escalate."}}],tools_en:["Distributor management system (DMS)","CRM / SFA system","Sales BI dashboards","Sales target allocation spreadsheets","Field sales route tracking app"]}},"KK-291":{scenario:{company:"Hải Âu Paints & Coatings",supervisor:{name:"Ngô Thị Lan",role:{vi:"Quản lý Kênh Phân phối",en:"Channel Sales Manager"}},ref_code:"DL-2093",title:{vi:"Đúng hạng. Đúng thưởng. Đúng chính sách.",en:"Right tier. Right rebate. Right policy."},brief:{vi:"Bạn chốt xếp hạng và thưởng chiết khấu quý 3 cho đại lý DL-2093. Đại lý mua 1620 triệu đồng, trả lại 72 triệu hàng lỗi và còn khoản nợ 85 triệu quá hạn 40 ngày. Chính sách mô phỏng: GOLD khi doanh số mua thuần từ 1500 triệu và không có nợ quá hạn; SILVER khi từ 800 triệu và nợ quá hạn không quá 60 ngày; còn lại STANDARD. Sửa hạng đại lý và tiền thưởng chiết khấu, rồi lập báo cáo có căn cứ.",en:"You are closing the Q3 tier and rebate for dealer DL-2093. The dealer bought 1620 million VND, returned 72 million of defective goods and still has 85 million overdue by 40 days. Training policy: GOLD from 1500 million net purchases with no overdue debt; SILVER from 800 million with overdue debt of at most 60 days; otherwise STANDARD. Correct the dealer tier and the rebate amount, then write an evidence-based report."},reference_title:{vi:"Chính sách đại lý quý 3 & bảng đối soát thưởng đã duyệt · DL-2093",en:"Approved Q3 dealer policy & rebate reconciliation · DL-2093"},fields:[{id:"DEALER_TIER",label:{vi:"Hạng đại lý quý 3",en:"Q3 dealer tier"},initial:"GOLD",expected:"SILVER",choices:["GOLD","SILVER","STANDARD"],reference:"Chính sách xếp hạng đại lý",hint:{vi:"Hạng không chỉ phụ thuộc doanh số; kiểm tra cả điều kiện công nợ của từng hạng.",en:"Tier depends on more than volume; check each tier's receivables condition too."}},{id:"REBATE_M",label:{vi:"Thưởng chiết khấu (triệu VND)",en:"Rebate (million VND)"},initial:"56.7",expected:"30.96",reference:"Bảng đối soát thưởng",ref_value:{vi:"Doanh số mua 1620 triệu; hàng trả lại 72 triệu; hạng xác định theo chính sách quý 3",en:"Purchases 1620 million; returns 72 million; tier set by the Q3 policy"},hint:{vi:"Bản nháp dùng sai tỷ lệ và tính trên doanh số gộp chưa trừ hàng trả lại.",en:"The draft uses the wrong rate and the gross purchases before returns."}}],sop32:{vi:"Thưởng chiết khấu = doanh số mua thuần (doanh số mua - hàng trả lại) x tỷ lệ theo hạng: GOLD 3,5%, SILVER 2%, STANDARD 1% (số liệu mô phỏng). Đơn vị triệu đồng, giữ 2 chữ số thập phân.",en:"Rebate = net purchases (purchases - returns) x tier rate: GOLD 3.5%, SILVER 2%, STANDARD 1% (training figures). Unit million VND, 2 decimals."},context:{label:"DMS / DL-2093",metrics:[{label:{vi:"Doanh số mua quý 3",en:"Q3 purchases"},value:"1,620 m VND"},{label:{vi:"Hàng trả lại",en:"Returns"},value:"72 m VND"},{label:{vi:"Nợ quá hạn",en:"Overdue debt"},value:"85 m VND / 40 d"}]},crisis:{vi:"Chủ đại lý nhắn riêng: “Em cứ xếp anh hạng GOLD quý này, phần thưởng chênh lệch anh gửi lại em 1% doanh số, không ai biết đâu. Đầu tháng anh trả nợ sau.”",en:"The dealer owner messages you privately: “Just put me in GOLD this quarter and I will send you back 1% of sales from the extra rebate, nobody will know. I will pay the debt next month.”"},options:{safe:{vi:"Từ chối khoản lại quả, giữ hạng SILVER theo chính sách và báo Quản lý Kênh theo quy định xung đột lợi ích; đề xuất lộ trình trả nợ để đại lý đạt GOLD quý sau.",en:"Refuse the kickback, keep SILVER per policy and report to the Channel Sales Manager under the conflict-of-interest rule; propose a repayment plan so the dealer can reach GOLD next quarter."},shortcut:{vi:"Xếp GOLD để giữ quan hệ với đại lý lớn và coi khoản 1% là quà cảm ơn.",en:"Grant GOLD to keep a big dealer happy and treat the 1% as a thank-you gift."},wait:{vi:"Không trả lời đại lý và để hệ thống tự xếp hạng theo bản nháp.",en:"Do not reply to the dealer and let the system apply the draft tier."}},questions:{vi:["Vì sao DL-2093 được xếp SILVER chứ không phải GOLD? Điều kiện nào của chính sách quyết định?","Trình bày cách tính thưởng chiết khấu và rủi ro khi nhận lại quả từ đại lý."],en:["Why is DL-2093 SILVER rather than GOLD? Which policy condition decides it?","Explain the rebate calculation and the risk of accepting a kickback from a dealer."]},hints:{vi:["Đặt bản nháp cạnh chính sách xếp hạng, kiểm tra lần lượt điều kiện doanh số thuần và điều kiện nợ quá hạn.","Theo SOP mục 3.2, trừ hàng trả lại trước rồi mới nhân tỷ lệ của đúng hạng.","Đọc lại SOP mục 4.2: mọi đề nghị lợi ích cá nhân từ đối tác phải từ chối và báo cáo."],en:["Place the draft next to the tier policy and check the net purchase and overdue conditions in turn.","Per SOP 3.2, deduct returns first and then apply the rate of the correct tier.","Re-read SOP 4.2: any personal benefit offered by a partner must be refused and reported."]}},learning:{summary:{vi:"Chuyên viên kinh doanh kênh phân phối và đại lý phát triển, quản lý mạng lưới đại lý, nhà phân phối trên địa bàn: tuyển chọn đối tác, triển khai chính sách giá, chiết khấu, đặt chỉ tiêu, theo dõi đơn hàng, tồn kho, công nợ và hỗ trợ bán ra bằng trưng bày, đào tạo, khuyến mại. Nghề đòi hỏi tính toán chính sách chính xác, kiểm soát rủi ro tín dụng và giữ quan hệ minh bạch, công bằng với mọi đại lý.",en:"A channel and distributor sales executive develops and manages the dealer and distributor network in a territory: selecting partners, applying price and discount policy, setting targets, tracking orders, stock and receivables, and supporting sell-out through displays, training and promotions. The role requires accurate policy calculations, credit risk control and transparent, fair relationships with every dealer."},responsibilities:{vi:["Tìm kiếm, thẩm định năng lực tài chính và mặt bằng của đại lý mới.","Triển khai chính sách giá, chiết khấu, thưởng doanh số và hỗ trợ trưng bày cho từng hạng đại lý.","Theo dõi đơn hàng, tồn kho, công nợ và hạn mức tín dụng của đại lý.","Hỗ trợ bán ra: đào tạo sản phẩm, vật phẩm trưng bày, chương trình khuyến mại tại điểm bán.","Đánh giá, xếp hạng đại lý định kỳ và đối soát thưởng minh bạch."],en:["Find new dealers and assess their finances and premises.","Apply price, discount, volume rebate and display support policies for each dealer tier.","Track dealer orders, stock, receivables and credit limits.","Support sell-out: product training, display materials and in-store promotions.","Review and tier dealers periodically and reconcile rebates transparently."]},competencies:[{name:{vi:"Phát triển mạng lưới",en:"Network development"},desc:{vi:"Lập bản đồ địa bàn, tìm khoảng trống độ phủ và chọn đối tác phù hợp.",en:"Map the territory, find coverage gaps and select suitable partners."}},{name:{vi:"Tính toán chính sách",en:"Policy calculation"},desc:{vi:"Tính đúng chiết khấu, thưởng, hàng trả lại và điều kiện xếp hạng theo văn bản.",en:"Compute discounts, rebates, returns and tier conditions exactly as written."}},{name:{vi:"Quản lý tín dụng",en:"Credit control"},desc:{vi:"Theo dõi tuổi nợ, nhắc nợ, đề xuất khóa đơn hoặc lộ trình trả nợ.",en:"Track debt aging, chase payments and propose order holds or repayment plans."}},{name:{vi:"Hỗ trợ bán ra",en:"Sell-out support"},desc:{vi:"Giúp đại lý bán hàng ra thị trường thay vì chỉ ép nhận hàng vào kho.",en:"Help dealers sell to the market instead of just pushing stock in."}},{name:{vi:"Minh bạch & công bằng",en:"Transparency & fairness"},desc:{vi:"Áp dụng chính sách như nhau cho mọi đại lý, từ chối quà tặng, lại quả.",en:"Apply policy equally to all dealers and refuse gifts or kickbacks."}}],knowledge:{vi:["Luật Thương mại 2005 về đại lý thương mại: quyền, nghĩa vụ của bên giao đại lý, bên đại lý và thù lao đại lý.","Cấu trúc chính sách kênh: giá niêm yết, chiết khấu trên hóa đơn, thưởng doanh số cuối kỳ, hỗ trợ trưng bày.","Quản lý tín dụng thương mại: hạn mức, tuổi nợ, chỉ số DSO và quy trình khóa đơn khi nợ quá hạn.","Nghị định 123/2020/NĐ-CP về hóa đơn, chứng từ (và văn bản sửa đổi): xử lý chiết khấu thương mại, hàng bán bị trả lại.","Luật Cạnh tranh 2018 về thỏa thuận hạn chế cạnh tranh và lạm dụng vị trí thống lĩnh thị trường."],en:["Commercial Law 2005 on commercial agency: rights and duties of principal and agent and agency fees.","Channel policy structure: list price, on-invoice discount, period-end volume rebate and display support.","Trade credit control: limits, debt aging, DSO and the order hold process for overdue accounts.","Decree 123/2020/ND-CP on invoices and documents (as amended): treating trade discounts and sales returns.","Competition Law 2018 on anti-competitive agreements and abuse of dominant position."]},tools:["Hệ thống DMS","Phần mềm ERP / công nợ","Ứng dụng đặt hàng cho đại lý","Bảng tính đối soát thưởng","Vật phẩm trưng bày (POSM)"],kpis:{vi:["Doanh số sell-in và sell-out qua mạng lưới đại lý.","Số đại lý hoạt động và đại lý mới mỗi quý.","Tỷ lệ nợ quá hạn và số ngày thu tiền bình quân (DSO).","Số khiếu nại do tính thưởng sai (mục tiêu bằng 0)."],en:["Sell-in and sell-out through the dealer network.","Active and new dealers per quarter.","Overdue ratio and days sales outstanding (DSO).","Complaints caused by rebate errors (target zero)."]},day:[{time:"08:00",vi:"Kiểm tra đơn hàng mới, công nợ và đại lý chạm hạn mức trên DMS.",en:"Check new orders, receivables and dealers at their credit limit in the DMS."},{time:"09:30",vi:"Thăm đại lý, kiểm tra trưng bày, tồn kho và giá bán lẻ.",en:"Visit dealers to check displays, stock and retail prices."},{time:"13:30",vi:"Đào tạo sản phẩm và cách pha màu cho nhân viên đại lý mới.",en:"Train a new dealer's staff on products and color mixing."},{time:"15:30",vi:"Đối soát thưởng chiết khấu, hàng trả lại với kế toán công nợ.",en:"Reconcile rebates and returns with accounts receivable."},{time:"17:00",vi:"Báo cáo doanh số, rủi ro công nợ và kế hoạch thăm đại lý ngày mai.",en:"Report sales, credit risks and tomorrow's dealer visits."}],mistakes:{vi:["Xếp hạng đại lý chỉ theo doanh số mà bỏ qua điều kiện nợ quá hạn.","Tính thưởng trên doanh số gộp chưa trừ hàng trả lại.","Nhận quà, lại quả hoặc ưu ái riêng một đại lý, phá vỡ công bằng chính sách."],en:["Tiering dealers on volume only and ignoring the overdue condition.","Computing rebates on gross purchases before returns.","Accepting gifts or kickbacks or favoring one dealer, breaking policy fairness."]},career:[{vi:"Nhân viên kinh doanh đại lý",en:"Dealer sales representative"},{vi:"Chuyên viên kinh doanh kênh phân phối",en:"Channel sales executive"},{vi:"Giám sát kênh phân phối khu vực",en:"Area channel supervisor"},{vi:"Quản lý kênh phân phối toàn quốc",en:"National channel manager"}],glossary:[{term:"Rebate",vi:"Thưởng chiết khấu cuối kỳ dựa trên doanh số mua thuần và hạng đại lý.",en:"A period-end payment based on net purchases and dealer tier."},{term:"Credit limit",vi:"Hạn mức tín dụng: dư nợ tối đa đại lý được phép trước khi bị khóa đơn.",en:"The maximum balance a dealer may owe before orders are held."},{term:"Aging",vi:"Tuổi nợ: phân loại công nợ theo số ngày kể từ hạn thanh toán.",en:"Grouping receivables by days past the due date."},{term:"DSO",vi:"Số ngày thu tiền bình quân, đo tốc độ đại lý thanh toán.",en:"Days sales outstanding, measuring how fast dealers pay."},{term:"POSM",vi:"Vật phẩm hỗ trợ bán hàng tại điểm bán: kệ, bảng hiệu, bảng màu, tờ rơi.",en:"Point-of-sale materials: racks, signs, color cards and leaflets."}],quiz:[{q:{vi:"Đại lý mua 900 triệu, trả lại 50 triệu, hạng SILVER 2%. Thưởng chiết khấu là bao nhiêu?",en:"A dealer bought 900 million, returned 50 million and is SILVER at 2%. What is the rebate?"},options:{vi:["18 triệu","16 triệu","17 triệu","29,75 triệu"],en:["18 million","16 million","17 million","29.75 million"]},answer:2,explain:{vi:"(900 - 50) x 2% = 17 triệu; thưởng tính trên doanh số mua thuần.",en:"(900 - 50) x 2% = 17 million; rebates use net purchases."}},{q:{vi:"Theo chính sách trong bài, đại lý mua thuần 1600 triệu nhưng có nợ quá hạn 20 ngày được xếp hạng nào?",en:"Under the training policy, a dealer with 1600 million net purchases and debt 20 days overdue gets which tier?"},options:{vi:["SILVER","GOLD","STANDARD","Không xếp hạng"],en:["SILVER","GOLD","STANDARD","No tier"]},answer:0,explain:{vi:"GOLD yêu cầu không có nợ quá hạn; nợ quá hạn dưới 60 ngày và doanh số trên 800 triệu thì đạt SILVER.",en:"GOLD requires no overdue debt; under 60 days overdue with over 800 million qualifies for SILVER."}},{q:{vi:"Vì sao cần khóa đơn khi đại lý vượt hạn mức tín dụng?",en:"Why hold orders when a dealer exceeds the credit limit?"},options:{vi:["Để phạt đại lý","Để kiểm soát rủi ro nợ xấu và giữ công bằng chính sách với đại lý khác","Để giảm doanh số cuối kỳ","Vì kế toán yêu cầu không cần lý do"],en:["To punish the dealer","To control bad-debt risk and keep policy fair to other dealers","To lower period sales","Because accounting says so without reason"]},answer:1,explain:{vi:"Hạn mức tín dụng bảo vệ dòng tiền công ty; ngoại lệ phải được cấp có thẩm quyền phê duyệt.",en:"Credit limits protect company cash flow; exceptions need approval from the proper authority."}},{q:{vi:"Đại lý đề nghị chia lại 1% doanh số nếu bạn xếp họ hạng cao hơn. Bạn làm gì?",en:"A dealer offers you 1% of sales if you give them a higher tier. What do you do?"},options:{vi:["Nhận vì là quà cảm ơn","Nhận nhưng chuyển vào quỹ nhóm","Từ chối nhưng vẫn nâng hạng","Từ chối, giữ hạng đúng chính sách và báo cáo quản lý"],en:["Accept it as a thank-you","Accept it for the team fund","Refuse but upgrade anyway","Refuse, keep the correct tier and report to management"]},answer:3,explain:{vi:"Lại quả là hành vi tham nhũng trong doanh nghiệp, gây thiệt hại cho công ty và bất công với đại lý khác.",en:"A kickback is private-sector bribery that harms the company and is unfair to other dealers."}}],tools_en:["Distribution management system (DMS)","ERP / accounts receivable software","Dealer ordering app","Rebate reconciliation spreadsheet","Point-of-sale materials (POSM)"]}},"KK-292":{scenario:{company:"Vạn Xuân Packaging Solutions",supervisor:{name:"Ông Thanh Tùng",role:{vi:"Giám đốc Khách hàng Chiến lược",en:"Head of Strategic Accounts"}},ref_code:"KA-7740",title:{vi:"Đúng cam kết. Đúng công thức. Đúng bảo mật.",en:"Right volume. Right formula. Right confidentiality."},brief:{vi:"Bạn chuẩn bị phụ lục gia hạn hợp đồng 2027 KA-7740 cung cấp thùng carton cho một nhà máy nước giải khát. Khách đã xác nhận bằng văn bản dự báo 2,4 triệu thùng; dòng sản phẩm mới thêm 0,8 triệu thùng chưa được duyệt, chưa có thư cam kết. Bậc khối lượng: TIER-1 dưới 2 triệu, TIER-2 từ 2 đến dưới 3 triệu, TIER-3 từ 3 triệu. Giá cơ sở 4200 đồng/thùng; chỉ số giá giấy tăng từ 820 lên 943 USD/tấn. Sửa bậc khối lượng và đơn giá mới, rồi lập báo cáo có căn cứ.",en:"You are preparing the 2027 renewal addendum KA-7740 for supplying cartons to a beverage plant. The client confirmed a 2.4 million carton forecast in writing; a new product line would add 0.8 million but is not approved and has no letter of intent. Volume tiers: TIER-1 below 2 million, TIER-2 from 2 to below 3 million, TIER-3 from 3 million. Base price 4200 VND per carton; the paper index rose from 820 to 943 USD per ton. Correct the volume tier and the new unit price, then write an evidence-based report."},reference_title:{vi:"Hợp đồng khung & phụ lục cơ chế giá đã duyệt · KA-7740",en:"Approved framework contract & pricing mechanism annex · KA-7740"},fields:[{id:"VOL_TIER",label:{vi:"Bậc khối lượng năm 2027",en:"2027 volume tier"},initial:"TIER-3",expected:"TIER-2",choices:["TIER-1","TIER-2","TIER-3"],reference:"Biên bản xác nhận dự báo khối lượng",hint:{vi:"Chỉ khối lượng khách đã cam kết bằng văn bản mới được dùng để xác định bậc.",en:"Only volume committed in writing by the client may set the tier."}},{id:"UNIT_PRICE",label:{vi:"Đơn giá mới (VND/thùng)",en:"New unit price (VND/carton)"},initial:"4637",expected:"4486",reference:"Phụ lục cơ chế điều chỉnh giá",ref_value:{vi:"Giá cơ sở 4200 đồng/thùng; chỉ số giá giấy kỳ gốc 820, kỳ điều chỉnh 943 USD/tấn",en:"Base price 4200 VND/carton; paper index base 820, adjustment period 943 USD/ton"},hint:{vi:"Bản nháp chuyển toàn bộ mức tăng chỉ số vào giá và dùng chiết khấu của bậc chưa đạt.",en:"The draft passes the full index rise into price and uses the discount of an unearned tier."}}],sop32:{vi:"Đơn giá mới = giá cơ sở x (1 + 60% x mức thay đổi chỉ số giá giấy) x (1 - chiết khấu bậc); chỉ điều chỉnh khi chỉ số đổi quá 5%. Chiết khấu TIER-1 0%, TIER-2 2%, TIER-3 4%; làm tròn đến đồng (mô phỏng).",en:"New price = base price x (1 + 60% x paper index change) x (1 - tier discount); adjust only if the index moves over 5%. Discounts TIER-1 0%, TIER-2 2%, TIER-3 4%; round to the dong (training)."},context:{label:"KAM / KA-7740",metrics:[{label:{vi:"Dự báo đã xác nhận",en:"Confirmed forecast"},value:"2,400,000"},{label:{vi:"Khối lượng chưa cam kết",en:"Uncommitted volume"},value:"800,000"},{label:{vi:"Giá cơ sở",en:"Base price"},value:"4,200 VND"},{label:{vi:"Chỉ số giá giấy",en:"Paper index"},value:"820 / 943 USD/t"}]},crisis:{vi:"Trưởng phòng mua hàng của khách gợi ý: “Anh gửi tôi bảng giá và sản lượng bên anh đang bán cho đối thủ của chúng tôi để tham chiếu, tôi ký gia hạn ngay trong tuần.”",en:"The client's procurement head suggests: “Send me the prices and volumes you sell to our competitor as a benchmark, and I will sign the renewal this week.”"},options:{safe:{vi:"Từ chối cung cấp thông tin bảo mật của khách hàng khác, báo Giám đốc Khách hàng Chiến lược; đề xuất tham chiếu hợp lệ bằng chỉ số giá giấy công khai và phân tích chi phí của chính hợp đồng.",en:"Refuse to share another client's confidential data and inform the Head of Strategic Accounts; offer a lawful benchmark using the public paper index and this contract's own cost analysis."},shortcut:{vi:"Gửi bảng giá của khách hàng kia nhưng xóa tên để giữ được hợp đồng lớn.",en:"Send the other client's price list with the name removed to keep the big contract."},wait:{vi:"Không phản hồi khách và để phụ lục gia hạn treo đến khi khách đổi ý.",en:"Do not respond and leave the renewal pending until the client changes its mind."}},questions:{vi:["Vì sao hợp đồng 2027 áp dụng TIER-2 chứ không phải TIER-3? Văn bản nào chứng minh khối lượng cam kết?","Trình bày cách tính đơn giá theo cơ chế chỉ số và rủi ro pháp lý khi tiết lộ thông tin của khách hàng khác."],en:["Why does the 2027 contract use TIER-2 instead of TIER-3? Which document proves the committed volume?","Explain the index-linked price calculation and the legal risk of disclosing another client's information."]},hints:{vi:["Đặt bản nháp cạnh biên bản xác nhận dự báo, tách phần đã cam kết khỏi phần còn chờ duyệt.","Tính theo SOP mục 3.2: mức thay đổi chỉ số, tỷ lệ chuyển giá, rồi chiết khấu của bậc đúng.","Đọc lại SOP mục 4.2: thông tin giá của khách hàng khác là bí mật kinh doanh, mọi yêu cầu phải báo cáo."],en:["Place the draft next to the forecast confirmation and separate committed from pending volume.","Compute per SOP 3.2: index change, pass-through rate, then the correct tier discount.","Re-read SOP 4.2: other clients' prices are trade secrets and any request must be escalated."]}},learning:{summary:{vi:"Chuyên viên quản trị khách hàng chiến lược (KAM) phụ trách một số ít khách hàng lớn mang lại phần lớn doanh thu: xây dựng kế hoạch khách hàng nhiều năm, quản lý quan hệ nhiều tầng, đàm phán hợp đồng khung, giá và cơ chế điều chỉnh giá, theo dõi mức độ dịch vụ và mở rộng cơ hội hợp tác. Nghề đòi hỏi hiểu sâu chuỗi giá trị của khách, năng lực phân tích thương mại, đàm phán cân bằng và giữ bảo mật thông tin tuyệt đối.",en:"A key account manager looks after a few large clients that generate most of the revenue: building multi-year account plans, managing relationships at several levels, negotiating framework contracts, prices and price adjustment mechanisms, tracking service levels and expanding the partnership. The role needs deep insight into the client's value chain, commercial analysis, balanced negotiation and strict confidentiality."},responsibilities:{vi:["Lập kế hoạch khách hàng nhiều năm và sơ đồ các bên liên quan từ vận hành đến ban giám đốc.","Đàm phán hợp đồng khung, giá, bậc khối lượng và cơ chế điều chỉnh theo chỉ số nguyên liệu.","Điều phối sản xuất, chất lượng, giao hàng nội bộ để đạt cam kết mức độ dịch vụ.","Chủ trì họp đánh giá kinh doanh định kỳ (QBR) với khách hàng.","Theo dõi lợi nhuận, công nợ, rủi ro và cơ hội mở rộng của từng khách hàng chiến lược."],en:["Build multi-year account plans and stakeholder maps from operations to the board.","Negotiate framework contracts, prices, volume tiers and raw-material index adjustments.","Coordinate internal production, quality and delivery to meet service level commitments.","Lead quarterly business reviews (QBR) with the client.","Track profit, receivables, risks and growth opportunities for each strategic account."]},competencies:[{name:{vi:"Hoạch định khách hàng",en:"Account planning"},desc:{vi:"Phân tích chiến lược của khách, xác định mục tiêu chung và lộ trình tăng trưởng nhiều năm.",en:"Analyze the client's strategy, set shared goals and a multi-year growth roadmap."}},{name:{vi:"Đàm phán thương mại",en:"Commercial negotiation"},desc:{vi:"Đàm phán dựa trên dữ liệu chi phí, giá trị và điều khoản cân bằng rủi ro hai bên.",en:"Negotiate on cost and value data with terms that balance both sides' risks."}},{name:{vi:"Phân tích lợi nhuận khách hàng",en:"Account profitability"},desc:{vi:"Tính biên lợi nhuận theo khách, tác động của chiết khấu, điều chỉnh giá và chi phí phục vụ.",en:"Compute margin per client and the effect of discounts, price changes and cost to serve."}},{name:{vi:"Điều phối liên chức năng",en:"Cross-functional coordination"},desc:{vi:"Kéo sản xuất, chất lượng, kho vận, tài chính cùng giữ cam kết với khách.",en:"Align production, quality, logistics and finance behind client commitments."}},{name:{vi:"Bảo mật & liêm chính",en:"Confidentiality & integrity"},desc:{vi:"Không tiết lộ thông tin khách hàng khác, không trao đổi lợi ích cá nhân với người mua.",en:"Never disclose other clients' data or trade personal benefits with buyers."}}],knowledge:{vi:["Luật Thương mại 2005 về hợp đồng mua bán hàng hóa; mức phạt vi phạm tối đa 8% giá trị phần nghĩa vụ bị vi phạm.","Bộ luật Dân sự 2015 về giao kết, sửa đổi hợp đồng và hoàn cảnh thay đổi cơ bản.","Bảo vệ bí mật kinh doanh theo Luật Sở hữu trí tuệ và điều khoản bảo mật trong hợp đồng.","Cơ chế giá theo chỉ số nguyên liệu: kỳ gốc, ngưỡng kích hoạt, tỷ lệ chuyển giá, chu kỳ điều chỉnh.","Chỉ số mức độ dịch vụ OTIF, tỷ lệ lỗi chất lượng và thời gian xử lý khiếu nại."],en:["Commercial Law 2005 on sale of goods contracts; contractual penalties capped at 8% of the breached obligation.","Civil Code 2015 on contract formation, amendment and fundamental change of circumstances.","Trade secret protection under the Intellectual Property Law and contract confidentiality clauses.","Index-linked pricing: base period, trigger threshold, pass-through rate and adjustment cycle.","Service level metrics: OTIF, quality defect rate and complaint resolution time."]},tools:["Hệ thống CRM","Bảng tính mô hình giá","BI lợi nhuận khách hàng","Hệ thống ERP đơn hàng","Cổng hợp tác nhà cung cấp"],kpis:{vi:["Tỷ lệ gia hạn hợp đồng và giữ chân khách hàng chiến lược.","Tăng trưởng doanh thu từ nhóm khách hàng chiến lược.","Biên lợi nhuận gộp theo từng khách hàng.","Tỷ lệ giao hàng đúng hạn, đủ số lượng (OTIF)."],en:["Contract renewal and strategic account retention rate.","Revenue growth from strategic accounts.","Gross margin per account.","On-time in-full delivery rate (OTIF)."]},day:[{time:"08:30",vi:"Xem báo cáo OTIF, khiếu nại chất lượng và đơn hàng gấp của các khách chiến lược.",en:"Review OTIF, quality complaints and urgent orders for strategic accounts."},{time:"10:00",vi:"Chủ trì QBR với khách: kết quả quý, kế hoạch sản phẩm mới, cải tiến bao bì.",en:"Lead a client QBR: quarterly results, new products and packaging improvements."},{time:"13:30",vi:"Cập nhật mô hình giá theo chỉ số giấy và kiểm tra biên lợi nhuận phụ lục mới.",en:"Update the paper-index price model and check the new addendum's margin."},{time:"15:30",vi:"Họp nội bộ với sản xuất, kho vận về năng lực đáp ứng mùa cao điểm.",en:"Meet production and logistics on peak-season capacity."},{time:"17:00",vi:"Cập nhật kế hoạch khách hàng và nhật ký liên hệ trên CRM.",en:"Update the account plan and contact log in the CRM."}],mistakes:{vi:["Xác định bậc khối lượng trên sản lượng khách chưa cam kết bằng văn bản.","Chuyển toàn bộ mức tăng chỉ số nguyên liệu vào giá thay vì tỷ lệ chuyển giá đã thỏa thuận.","Chia sẻ thông tin giá, sản lượng của khách hàng khác để chốt nhanh hợp đồng."],en:["Setting the volume tier on volume the client has not committed in writing.","Passing the full raw-material increase into price instead of the agreed pass-through rate.","Sharing another client's prices or volumes to close a deal faster."]},career:[{vi:"Chuyên viên kinh doanh B2B",en:"B2B sales executive"},{vi:"Chuyên viên quản trị khách hàng chiến lược (KAM)",en:"Key Account Manager"},{vi:"Quản lý khách hàng chiến lược cấp cao",en:"Senior or global key account manager"},{vi:"Giám đốc khách hàng chiến lược",en:"Head of strategic accounts"}],glossary:[{term:"Account plan",vi:"Kế hoạch khách hàng: mục tiêu, sơ đồ quan hệ, cơ hội và hành động cho một khách chiến lược.",en:"Goals, relationship map, opportunities and actions for one strategic client."},{term:"QBR",vi:"Họp đánh giá kinh doanh hằng quý giữa nhà cung cấp và khách hàng.",en:"Quarterly business review between supplier and client."},{term:"OTIF",vi:"Tỷ lệ đơn hàng giao đúng hạn và đủ số lượng.",en:"Share of orders delivered on time and in full."},{term:"Index-linked pricing",vi:"Cơ chế điều chỉnh giá theo biến động chỉ số nguyên liệu đã thỏa thuận.",en:"Price adjustment tied to an agreed raw-material index."},{term:"Pass-through rate",vi:"Tỷ lệ chuyển giá: phần biến động chi phí nguyên liệu được phản ánh vào giá bán.",en:"The share of a raw-material cost change reflected in the selling price."}],quiz:[{q:{vi:"Giá cơ sở 5000 đồng, chỉ số nguyên liệu tăng 10%, tỷ lệ chuyển giá 60%, không chiết khấu. Giá mới là bao nhiêu?",en:"Base price 5000 VND, raw-material index up 10%, pass-through 60%, no discount. What is the new price?"},options:{vi:["5500 đồng","5050 đồng","5600 đồng","5300 đồng"],en:["5500 VND","5050 VND","5600 VND","5300 VND"]},answer:3,explain:{vi:"5000 x (1 + 0,6 x 10%) = 5000 x 1,06 = 5300 đồng.",en:"5000 x (1 + 0.6 x 10%) = 5000 x 1.06 = 5300 VND."}},{q:{vi:"Theo Luật Thương mại 2005, mức phạt vi phạm hợp đồng thông thường tối đa là bao nhiêu?",en:"Under the Commercial Law 2005, what is the usual maximum contractual penalty?"},options:{vi:["5% giá trị hợp đồng","8% giá trị phần nghĩa vụ bị vi phạm","10% giá trị hợp đồng","Không giới hạn"],en:["5% of contract value","8% of the breached obligation","10% of contract value","No limit"]},answer:1,explain:{vi:"Mức phạt do các bên thỏa thuận nhưng không quá 8% giá trị phần nghĩa vụ bị vi phạm, trừ trường hợp luật có quy định riêng.",en:"The parties agree the penalty but it may not exceed 8% of the breached obligation, unless a special rule applies."}},{q:{vi:"Người mua đề nghị bạn gửi bảng giá đang bán cho đối thủ của họ để tham chiếu. Bạn làm gì?",en:"A buyer asks for the prices you charge their competitor as a benchmark. What do you do?"},options:{vi:["Từ chối, báo cấp trên và đề xuất tham chiếu hợp lệ như chỉ số công khai","Gửi bản đã xóa tên khách hàng","Đọc qua điện thoại để không để lại dấu vết","Gửi nếu họ ký thỏa thuận bảo mật"],en:["Refuse, escalate and offer a lawful benchmark such as a public index","Send it with the client name removed","Read it out by phone to leave no trace","Send it if they sign an NDA"]},answer:0,explain:{vi:"Giá của khách hàng khác là bí mật kinh doanh được bảo vệ; tiết lộ vi phạm hợp đồng và làm mất niềm tin.",en:"Other clients' prices are protected trade secrets; disclosure breaches contracts and destroys trust."}},{q:{vi:"Khách xác nhận 2,4 triệu thùng, thêm 0,8 triệu đang chờ duyệt. Bậc khối lượng nên tính theo khối lượng nào?",en:"The client confirmed 2.4 million cartons with 0.8 million pending approval. Which volume should set the tier?"},options:{vi:["3,2 triệu vì sớm muộn sẽ có","Trung bình 2,8 triệu","2,4 triệu đã cam kết; phần chờ duyệt đưa vào điều khoản xem xét lại","0,8 triệu của dòng mới"],en:["3.2 million as it will come eventually","An average of 2.8 million","The committed 2.4 million; put the pending part in a review clause","The new line's 0.8 million"]},answer:2,explain:{vi:"Chiết khấu bậc phải dựa trên cam kết có căn cứ; khối lượng chưa chắc chắn xử lý bằng điều khoản điều chỉnh khi có thư cam kết.",en:"Tier discounts must rest on firm commitments; uncertain volume is handled by a review clause once committed."}}],tools_en:["CRM system","Pricing model spreadsheet","Customer profitability BI","ERP order processing system","Supplier collaboration portal"]}},"KK-331":{scenario:{company:"Mộc Lan Home Appliances",supervisor:{name:"Bùi Ngọc Ánh",role:{vi:"Trưởng nhóm Vận hành Sàn TMĐT",en:"Marketplace Operations Lead"}},ref_code:"FS-1212",title:{vi:"Đúng giá gốc. Đúng lãi. Đúng luật chơi.",en:"Right reference price. Right margin. Fair play."},brief:{vi:"Bạn thiết lập flash sale 12.12 trên sàn thương mại điện tử cho nồi chiên không dầu mã NC-55L, giá bán 1290000 đồng. Lịch sử giá 30 ngày: giá bán thực tế 1590000 đồng; tuần trước có người nâng giá niêm yết lên 1890000; giá in trên hộp 2100000 chưa từng áp dụng. Shop tài trợ voucher 50000 đồng/đơn; giá vốn 820000, đóng gói 15000; tổng phí sàn mô phỏng 15%. Sửa giá gốc hiển thị và lãi đóng góp mỗi đơn, rồi lập báo cáo có căn cứ.",en:"You are setting up the 12.12 flash sale on a marketplace for air fryer NC-55L at 1290000 VND. 30-day price history: actual selling price 1590000 VND; last week someone raised the list price to 1890000; the 2100000 printed on the box was never used. The shop funds a 50000 VND voucher per order; cost of goods 820000, packaging 15000; total training marketplace fees 15%. Correct the displayed reference price and the contribution margin per order, then write an evidence-based report."},reference_title:{vi:"Lịch sử giá 30 ngày & bảng tính lãi chiến dịch đã duyệt · FS-1212",en:"Approved 30-day price history & campaign margin sheet · FS-1212"},fields:[{id:"ORIG_PRICE",label:{vi:"Giá gốc hiển thị (VND)",en:"Displayed reference price (VND)"},initial:"1890000",expected:"1590000",choices:["1890000","1590000","2100000"],reference:"Lịch sử giá 30 ngày",hint:{vi:"Giá gốc phải là giá đã thực sự bán cho khách trước chương trình, không phải giá vừa nâng hay giá in sẵn.",en:"The reference price must be the price actually charged before the campaign, not a raised or printed price."}},{id:"CM_PER_ORDER",label:{vi:"Lãi đóng góp mỗi đơn (VND)",en:"Contribution margin per order (VND)"},initial:"351800",expected:"219000",reference:"Bảng tính lãi chiến dịch",ref_value:{vi:"Giá flash sale 1290000; voucher shop 50000; phí sàn 8% + 4% + 3%; giá vốn 820000; đóng gói 15000",en:"Flash price 1290000; shop voucher 50000; fees 8% + 4% + 3%; cost 820000; packaging 15000"},hint:{vi:"Bản nháp chỉ trừ hoa hồng trên giá chưa trừ voucher và quên phí thanh toán, phí chiến dịch.",en:"The draft deducts only commission on the pre-voucher price and forgets payment and campaign fees."}}],sop32:{vi:"Lãi đóng góp mỗi đơn = (giá flash sale - voucher shop tài trợ) x (1 - tổng phí sàn 15% gồm hoa hồng 8%, thanh toán 4%, chiến dịch 3%) - giá vốn - đóng gói. Phí tính trên giá sau voucher shop (mô phỏng).",en:"Contribution per order = (flash price - shop-funded voucher) x (1 - total fees 15%: commission 8%, payment 4%, campaign 3%) - cost of goods - packaging. Fees apply to the post-voucher price (training)."},context:{label:"SELLER CENTER / FS-1212",metrics:[{label:{vi:"Giá flash sale",en:"Flash sale price"},value:"1,290,000 VND"},{label:{vi:"Voucher shop tài trợ",en:"Shop-funded voucher"},value:"50,000 VND"},{label:{vi:"Tổng phí sàn mô phỏng",en:"Training fee total"},value:"15%"},{label:{vi:"Giá vốn",en:"Cost of goods"},value:"820,000 VND"}]},crisis:{vi:"Trưởng phòng kinh doanh online nhắn: “Tạo 300 đơn ảo bằng tài khoản người quen rồi đánh giá 5 sao để NC-55L lên top trước giờ flash sale, chi phí công ty chịu.”",en:"The online sales manager messages you: “Create 300 fake orders from friends' accounts and leave 5-star reviews so NC-55L ranks top before the flash sale, the company pays.”"},options:{safe:{vi:"Từ chối tạo đơn ảo, đánh giá giả và báo Trưởng nhóm Vận hành; đề xuất quảng cáo trong sàn, tối ưu nội dung sản phẩm và mời người mua thật đánh giá sau khi nhận hàng.",en:"Refuse fake orders and reviews and inform the Operations Lead; propose in-platform ads, better listing content and inviting real buyers to review after delivery."},shortcut:{vi:"Tạo một ít đơn ảo bằng tài khoản người quen cho an toàn rồi xóa đánh giá sau chiến dịch.",en:"Create a few fake orders from friends' accounts to be safe and delete the reviews after the campaign."},wait:{vi:"Không làm gì, chờ xem các shop khác có làm không rồi tính sau.",en:"Do nothing and wait to see whether other shops do it."}},questions:{vi:["Vì sao giá gốc hiển thị phải là 1590000 chứ không phải 1890000 hay 2100000? Dữ liệu nào chứng minh?","Trình bày cách tính lãi đóng góp mỗi đơn và hậu quả với shop nếu tạo đơn ảo, đánh giá giả."],en:["Why must the reference price be 1590000 rather than 1890000 or 2100000? Which data proves it?","Explain the contribution margin calculation and the consequences for the shop of fake orders and reviews."]},hints:{vi:["Đặt bản nháp cạnh lịch sử giá 30 ngày, đánh dấu mức giá khách đã thực sự trả.","Tính theo SOP mục 3.2: trừ voucher shop trước, áp đủ ba loại phí rồi trừ giá vốn và đóng gói.","Đọc lại SOP mục 4.2: thao túng đơn hàng, đánh giá là vi phạm; mọi yêu cầu như vậy phải báo cáo."],en:["Place the draft next to the 30-day price history and mark the price buyers actually paid.","Compute per SOP 3.2: deduct the shop voucher first, apply all three fees, then cost and packaging.","Re-read SOP 4.2: manipulating orders or reviews is a violation and any such request must be escalated."]}},learning:{summary:{vi:"Chuyên viên vận hành gian hàng thương mại điện tử quản lý hoạt động hằng ngày của shop trên các sàn: đăng và tối ưu sản phẩm, quản lý giá, tồn kho, chương trình khuyến mại, xử lý đơn hàng, vận chuyển, đổi trả, đánh giá và chỉ số sức khỏe gian hàng. Nghề đòi hỏi đọc dữ liệu nhanh, tính đúng lãi sau phí sàn, nắm chính sách từng sàn và tuân thủ pháp luật về thương mại điện tử, khuyến mại và bảo vệ người tiêu dùng.",en:"An e-commerce store operations specialist runs a shop's daily activity on marketplaces: listing and optimizing products, managing prices, stock and promotions, processing orders, shipping, returns, reviews and store health metrics. The role needs fast data reading, correct margin math after platform fees, knowledge of each platform's policy and compliance with e-commerce, promotion and consumer protection law."},responsibilities:{vi:["Đăng sản phẩm đúng ngành hàng, tối ưu tiêu đề, hình ảnh, thuộc tính và từ khóa.","Thiết lập giá, voucher, flash sale và tính lãi sau phí sàn trước khi chạy chiến dịch.","Đồng bộ tồn kho đa sàn, theo dõi đơn hàng, đóng gói và bàn giao vận chuyển đúng hạn.","Xử lý đổi trả, khiếu nại, đánh giá và giữ chỉ số vận hành shop trong ngưỡng an toàn.","Báo cáo doanh số, tỷ lệ chuyển đổi, chi phí quảng cáo và đề xuất tối ưu hằng tuần."],en:["List products in the right category and optimize titles, images, attributes and keywords.","Set prices, vouchers and flash sales and compute post-fee margin before each campaign.","Sync stock across platforms, track orders, pack and hand over to carriers on time.","Handle returns, complaints and reviews and keep store metrics within safe limits.","Report sales, conversion and ad spend weekly with optimization proposals."]},competencies:[{name:{vi:"Tối ưu hiển thị sản phẩm",en:"Listing optimization"},desc:{vi:"Viết tiêu đề, mô tả, chọn từ khóa và hình ảnh giúp sản phẩm được tìm thấy và chuyển đổi tốt.",en:"Write titles and descriptions and choose keywords and images that get found and convert."}},{name:{vi:"Định giá & khuyến mại",en:"Pricing & promotions"},desc:{vi:"Thiết kế khuyến mại có lãi, đúng quy định về giá gốc và mức giảm.",en:"Design profitable promotions that respect reference price and discount rules."}},{name:{vi:"Vận hành đơn hàng",en:"Order operations"},desc:{vi:"Kiểm soát tồn kho, thời gian chuẩn bị hàng, tỷ lệ hủy và giao trễ.",en:"Control stock, preparation time, cancellation and late shipment rates."}},{name:{vi:"Phân tích dữ liệu shop",en:"Store analytics"},desc:{vi:"Đọc lưu lượng, tỷ lệ chuyển đổi, ROAS để quyết định nhanh dựa trên số liệu.",en:"Read traffic, conversion and ROAS to make fast data-based decisions."}},{name:{vi:"Tuân thủ & trung thực",en:"Compliance & honesty"},desc:{vi:"Không giảm giá ảo, không đơn ảo, không đánh giá giả, thông tin sản phẩm trung thực.",en:"No fake discounts, fake orders or fake reviews, and truthful product information."}}],knowledge:{vi:["Nghị định 52/2013/NĐ-CP về thương mại điện tử (sửa đổi bởi Nghị định 85/2021/NĐ-CP) và các quy định mới về thương mại điện tử.","Luật Bảo vệ quyền lợi người tiêu dùng 2023: thông tin trung thực về hàng hóa, giá, khuyến mại và quyền đổi trả.","Nghị định 81/2018/NĐ-CP về xúc tiến thương mại: hình thức khuyến mại, mức giảm giá tối đa và nghĩa vụ thông báo.","Cơ cấu phí sàn: hoa hồng, phí thanh toán, phí dịch vụ chiến dịch, phí vận chuyển và cách tính lãi sau phí.","Chỉ số sức khỏe gian hàng: tỷ lệ hủy, giao trễ, phản hồi chat, điểm phạt và hậu quả."],en:["Decree 52/2013/ND-CP on e-commerce (amended by Decree 85/2021/ND-CP) and newer e-commerce rules.","Consumer Protection Law 2023: truthful product, price and promotion information and return rights.","Decree 81/2018/ND-CP on trade promotion: promotion types, maximum discount and notification duties.","Marketplace fee structure: commission, payment fee, campaign fee, shipping and post-fee margin.","Store health metrics: cancellation, late shipment, chat response, penalty points and their effects."]},tools:["Kênh người bán (seller center) của sàn","Phần mềm quản lý bán hàng đa kênh (OMS)","Công cụ quảng cáo trong sàn","Bảng tính giá & lãi chiến dịch","Hệ thống chat tập trung"],kpis:{vi:["Tổng giá trị hàng hóa bán ra (GMV) và tỷ lệ chuyển đổi.","Tỷ lệ giao hàng đúng hạn và tỷ lệ đơn hủy do shop.","Doanh thu trên chi phí quảng cáo (ROAS).","Điểm đánh giá trung bình và tỷ lệ phản hồi chat."],en:["Gross merchandise value (GMV) and conversion rate.","On-time shipment rate and seller-caused cancellation rate.","Return on ad spend (ROAS).","Average rating and chat response rate."]},day:[{time:"08:00",vi:"Kiểm tra đơn hàng qua đêm, tồn kho đa sàn và cảnh báo vận hành.",en:"Check overnight orders, multi-platform stock and store warnings."},{time:"09:30",vi:"Xử lý đơn, in vận đơn và bàn giao cho đơn vị vận chuyển trước giờ lấy hàng.",en:"Process orders, print waybills and hand over before carrier pickup."},{time:"11:00",vi:"Tối ưu tiêu đề, hình ảnh cho sản phẩm có tỷ lệ chuyển đổi thấp.",en:"Optimize titles and images for low-converting products."},{time:"14:00",vi:"Cài flash sale, voucher và kiểm tra lãi sau phí trên bảng tính.",en:"Set up flash sales and vouchers and check post-fee margin in the sheet."},{time:"16:30",vi:"Phản hồi đánh giá, khiếu nại và gửi báo cáo ngày cho trưởng nhóm.",en:"Answer reviews and complaints and send the daily report to the lead."}],mistakes:{vi:["Nâng giá niêm yết ngay trước chương trình để hiển thị mức giảm giá ảo.","Tính lãi quên phí thanh toán, phí chiến dịch hoặc voucher do shop tài trợ.","Tạo đơn ảo, mua đánh giá giả để lên top, dẫn tới phạt điểm hoặc khóa shop."],en:["Raising the list price just before a campaign to show a fake discount.","Computing margin without payment fees, campaign fees or shop-funded vouchers.","Creating fake orders or buying reviews to rank higher, leading to penalties or store bans."]},career:[{vi:"Nhân viên xử lý đơn hàng thương mại điện tử",en:"E-commerce order processing assistant"},{vi:"Chuyên viên vận hành gian hàng",en:"Store operations specialist"},{vi:"Trưởng nhóm vận hành sàn thương mại điện tử",en:"Marketplace operations team lead"},{vi:"Quản lý kênh thương mại điện tử",en:"E-commerce channel manager"}],glossary:[{term:"GMV",vi:"Tổng giá trị hàng hóa bán ra trong kỳ, chưa trừ hủy, trả hàng và phí.",en:"Gross merchandise value sold in a period, before cancellations, returns and fees."},{term:"ROAS",vi:"Doanh thu tạo ra trên mỗi đồng chi phí quảng cáo.",en:"Revenue generated per unit of ad spend."},{term:"Flash sale",vi:"Chương trình giảm giá trong khung giờ ngắn với số lượng giới hạn.",en:"A short time-boxed discount with limited quantity."},{term:"SKU",vi:"Mã định danh từng phiên bản sản phẩm theo màu, dung tích, kích cỡ.",en:"A unique code for each product variant by color, capacity or size."},{term:"Brushing",vi:"Đơn ảo: tạo giao dịch giả để thổi phồng doanh số, xếp hạng và đánh giá.",en:"Fake transactions created to inflate sales, ranking and reviews."}],quiz:[{q:{vi:"Giá bán 500000 đồng, voucher shop 20000, phí sàn 10% tính trên giá sau voucher, giá vốn 300000. Lãi đóng góp mỗi đơn là bao nhiêu?",en:"Price 500000 VND, shop voucher 20000, 10% fees on the post-voucher price, cost 300000. What is the contribution per order?"},options:{vi:["132000 đồng","150000 đồng","180000 đồng","128000 đồng"],en:["132000 VND","150000 VND","180000 VND","128000 VND"]},answer:0,explain:{vi:"(500000 - 20000) x 90% - 300000 = 432000 - 300000 = 132000 đồng.",en:"(500000 - 20000) x 90% - 300000 = 432000 - 300000 = 132000 VND."}},{q:{vi:"Giá gốc hiển thị khi chạy giảm giá phải là giá nào?",en:"Which price must be shown as the reference price in a discount?"},options:{vi:["Giá cao nhất từng niêm yết","Giá in trên bao bì","Giá thực tế đã bán ngay trước chương trình","Giá của đối thủ"],en:["The highest list price ever","The price printed on the pack","The actual selling price right before the campaign","A competitor's price"]},answer:2,explain:{vi:"Mức giảm phải tính trên giá bán thật trước khuyến mại; nâng giá rồi giảm là thông tin gây nhầm lẫn cho người tiêu dùng.",en:"Discounts must be based on the real pre-promotion price; raising then cutting misleads consumers."}},{q:{vi:"Cấp trên yêu cầu tạo đơn ảo và đánh giá 5 sao để lên top. Bạn làm gì?",en:"Your manager asks for fake orders and 5-star reviews to rank higher. What do you do?"},options:{vi:["Làm theo vì công ty chịu chi phí","Từ chối, báo cáo và đề xuất cách tăng hiển thị hợp lệ","Chỉ tạo 50 đơn cho an toàn","Thuê đơn vị bên ngoài làm thay"],en:["Comply because the company pays","Refuse, escalate and propose lawful ways to gain visibility","Make only 50 orders to be safe","Hire an outside agency to do it"]},answer:1,explain:{vi:"Đơn ảo, đánh giá giả lừa dối người mua, vi phạm chính sách sàn và có thể khiến shop bị khóa.",en:"Fake orders and reviews deceive buyers, break platform policy and can get the store banned."}},{q:{vi:"Theo Nghị định 81/2018/NĐ-CP, mức giảm giá tối đa thông thường cho hàng hóa khuyến mại là bao nhiêu?",en:"Under Decree 81/2018/ND-CP, what is the usual maximum discount for promoted goods?"},options:{vi:["30%","70%","100%","50% giá ngay trước khuyến mại"],en:["30%","70%","100%","50% of the price right before the promotion"]},answer:3,explain:{vi:"Mức giảm thông thường không vượt quá 50%; một số chương trình khuyến mại tập trung theo quy định được áp dụng mức cao hơn.",en:"The usual cap is 50%; certain officially designated concentrated promotion programs allow more."}}],tools_en:["Marketplace seller center","Multichannel order management software (OMS)","In-marketplace advertising tools","Pricing & campaign margin spreadsheets","Centralized chat system"]}},"KK-332":{scenario:{company:"Gió Mùa Online Mart",supervisor:{name:"Hoàng Gia Bảo",role:{vi:"Giám đốc Ngành hàng",en:"Head of Category"}},ref_code:"AR-0917",title:{vi:"Đúng quyết định. Đúng biên lãi. Đúng hồ sơ.",en:"Right call. Right margin. Right paperwork."},brief:{vi:"Bạn rà soát danh mục quý 4 ngành gia dụng AR-0917. Nồi cơm điện RC-18: 90 ngày nhận 1000 chiếc, bán 180; tồn 820 chiếc, tuổi tồn 135 ngày; hàng mua đứt, nhà cung cấp không nhận trả. Chính sách: sell-through 90 ngày dưới 25% và tuổi tồn trên 120 ngày thì MARKDOWN để xả; chỉ DELIST khi tồn dưới 50 chiếc; từ 25% trở lên thì KEEP. Giá vốn 459000 đồng; khi xả phải giữ biên lợi nhuận gộp tối thiểu 10%. Sửa quyết định SKU và giá xả tối thiểu, rồi lập báo cáo có căn cứ.",en:"You are reviewing the Q4 home appliance assortment AR-0917. Rice cooker RC-18: 1000 units received and 180 sold in 90 days; 820 in stock aged 135 days; bought outright with no supplier returns. Policy: 90-day sell-through below 25% and stock age over 120 days means MARKDOWN to clear; DELIST only when stock is below 50 units; 25% or more means KEEP. Cost 459000 VND; a clearance must keep at least a 10% gross margin. Correct the SKU decision and the minimum clearance price, then write an evidence-based report."},reference_title:{vi:"Chính sách rà soát danh mục & bảng tính giá xả đã duyệt · AR-0917",en:"Approved assortment review policy & clearance price sheet · AR-0917"},fields:[{id:"SKU_ACTION",label:{vi:"Quyết định với SKU RC-18",en:"Decision for SKU RC-18"},initial:"DELIST",expected:"MARKDOWN",choices:["KEEP","DELIST","MARKDOWN"],reference:"Chính sách rà soát danh mục",hint:{vi:"Tính sell-through, đối chiếu tuổi tồn và kiểm tra điều kiện tồn kho bắt buộc trước khi loại SKU.",en:"Compute sell-through, compare stock age and check the stock condition required before delisting."}},{id:"FLOOR_PRICE",label:{vi:"Giá xả tối thiểu chưa VAT (VND)",en:"Minimum clearance price excl. VAT (VND)"},initial:"504900",expected:"510000",reference:"Bảng tính giá xả",ref_value:{vi:"Giá vốn 459000 đồng; biên lợi nhuận gộp tối thiểu 10% tính trên giá bán chưa VAT",en:"Cost 459000 VND; minimum gross margin 10% on the selling price excl. VAT"},hint:{vi:"Bản nháp cộng 10% lên giá vốn; biên lợi nhuận gộp lại được tính trên giá bán.",en:"The draft adds 10% to cost; gross margin is measured on the selling price."}}],sop32:{vi:"Giá xả tối thiểu = giá vốn / (1 - biên lợi nhuận gộp tối thiểu); biên tính trên giá bán chưa VAT, không phải tỷ lệ cộng thêm trên giá vốn. Làm tròn đến đồng (mô phỏng).",en:"Minimum clearance price = cost / (1 - minimum gross margin); margin is measured on the selling price excl. VAT, not as a markup on cost. Round to the dong (training)."},context:{label:"CATEGORY / AR-0917",metrics:[{label:{vi:"Nhận / bán 90 ngày",en:"90-day received / sold"},value:"1000 / 180"},{label:{vi:"Tuổi tồn kho",en:"Stock age"},value:"135 d"},{label:{vi:"Tồn kho hiện tại",en:"Stock on hand"},value:"820"},{label:{vi:"Giá vốn",en:"Unit cost"},value:"459,000 VND"}]},crisis:{vi:"Nhà cung cấp dòng nồi cơm nhập khẩu mới đề nghị: “Cho lên sàn trước đợt 12.12 đi, giấy chứng nhận hợp quy an toàn điện bọn tôi bổ sung sau. Chúng tôi tài trợ thêm 200 triệu phí trưng bày.”",en:"The supplier of a new imported rice cooker line proposes: “List it before 12.12 and we will add the electrical safety conformity certificate later. We will pay an extra 200 million in display fees.”"},options:{safe:{vi:"Không mở bán khi chưa đủ chứng nhận hợp quy và hồ sơ chất lượng, báo Giám đốc Ngành hàng; đề xuất lịch ra mắt sau khi pháp chế và bộ phận chất lượng kiểm tra đủ hồ sơ.",en:"Do not list without the conformity certificate and quality file, inform the Head of Category; propose a launch date after legal and quality have checked the full file."},shortcut:{vi:"Mở bán trước để nhận tài trợ, gỡ sản phẩm nếu có người kiểm tra.",en:"List it now to get the sponsorship and take it down if anyone checks."},wait:{vi:"Không trả lời nhà cung cấp và để nhóm vận hành tự quyết có đăng hay không.",en:"Ignore the supplier and let operations decide whether to list it."}},questions:{vi:["Vì sao RC-18 phải MARKDOWN chứ không phải DELIST hay KEEP? Chỉ số và điều khoản mua hàng nào quyết định?","Trình bày cách tính giá xả tối thiểu và rủi ro khi mở bán hàng chưa có chứng nhận hợp quy."],en:["Why must RC-18 be MARKDOWN rather than DELIST or KEEP? Which metric and purchase term decide it?","Explain the minimum clearance price calculation and the risk of listing goods without a conformity certificate."]},hints:{vi:["Đặt bản nháp cạnh chính sách rà soát, tính sell-through rồi kiểm tra từng điều kiện theo thứ tự.","Áp dụng công thức SOP mục 3.2: biên lợi nhuận tính trên giá bán, không phải trên giá vốn.","Đọc lại SOP mục 4.2: hàng hóa thiếu hồ sơ hợp quy không được mở bán dù có tài trợ."],en:["Place the draft next to the review policy, compute sell-through and check each condition in order.","Apply the SOP 3.2 formula: margin is measured on selling price, not on cost.","Re-read SOP 4.2: goods missing conformity papers may not be listed, sponsorship or not."]}},learning:{summary:{vi:"Quản lý ngành hàng thương mại điện tử chịu trách nhiệm doanh thu, lợi nhuận và trải nghiệm mua sắm của một ngành hàng: xây dựng danh mục sản phẩm, chọn và đàm phán với nhà cung cấp, định giá, lập kế hoạch khuyến mại, kiểm soát tồn kho và hiệu quả vốn. Nghề đòi hỏi tư duy phân tích dữ liệu bán hàng, hiểu khách hàng và đối thủ, đàm phán thương mại vững và trách nhiệm bảo đảm hàng hóa hợp pháp, an toàn cho người tiêu dùng.",en:"An e-commerce category manager owns the revenue, profit and shopping experience of a category: building the assortment, selecting and negotiating with suppliers, pricing, planning promotions and controlling stock and capital efficiency. The role needs analytical thinking on sales data, customer and competitor insight, strong commercial negotiation and responsibility for lawful, safe products."},responsibilities:{vi:["Xây dựng chiến lược, vai trò ngành hàng và mục tiêu doanh thu, biên lợi nhuận.","Lập danh mục sản phẩm, thêm hoặc loại SKU dựa trên dữ liệu bán hàng và nhu cầu khách.","Đàm phán giá, chiết khấu, hỗ trợ marketing, điều kiện trả hàng và thanh toán với nhà cung cấp.","Định giá, lập kế hoạch khuyến mại và xả hàng chậm luân chuyển có kiểm soát biên lợi nhuận.","Theo dõi tồn kho, sell-through, GMROI và kiểm soát hồ sơ pháp lý, chất lượng sản phẩm."],en:["Set the category strategy, role and revenue and margin targets.","Build the assortment and add or delist SKUs based on sales data and customer demand.","Negotiate prices, discounts, marketing support, return and payment terms with suppliers.","Price products and plan promotions and slow-mover clearance with margin control.","Track stock, sell-through and GMROI and control product legal and quality files."]},competencies:[{name:{vi:"Phân tích danh mục",en:"Assortment analysis"},desc:{vi:"Đọc dữ liệu bán, tồn, tìm kiếm để biết SKU nào cần giữ, đẩy, xả hay loại.",en:"Read sales, stock and search data to decide which SKUs to keep, push, clear or delist."}},{name:{vi:"Đàm phán nhà cung cấp",en:"Supplier negotiation"},desc:{vi:"Thương lượng điều khoản cân bằng giá vốn, hỗ trợ bán hàng và rủi ro tồn kho.",en:"Negotiate terms that balance cost, sales support and stock risk."}},{name:{vi:"Định giá & biên lợi nhuận",en:"Pricing & margin"},desc:{vi:"Tính đúng biên lợi nhuận, markup, giá xả và tác động của khuyến mại.",en:"Compute margin, markup, clearance price and promotion impact correctly."}},{name:{vi:"Quản trị tồn kho & vốn",en:"Inventory & capital control"},desc:{vi:"Lập kế hoạch mua theo ngân sách, hạn chế tồn ứ và hàng chậm luân chuyển.",en:"Plan buying within budget and limit overstock and slow movers."}},{name:{vi:"Tuân thủ chất lượng",en:"Product compliance"},desc:{vi:"Chỉ mở bán hàng đủ hồ sơ hợp quy, nhãn mác, nguồn gốc theo quy định.",en:"List only goods with complete conformity, labeling and origin documents."}}],knowledge:{vi:["Quy trình quản trị ngành hàng 8 bước: định nghĩa, vai trò, đánh giá, thẻ điểm, chiến lược, chiến thuật, triển khai, rà soát.","Chỉ số danh mục: sell-through, tuổi tồn, số ngày tồn, GMROI, biên lợi nhuận gộp và phân biệt margin với markup.","Luật Chất lượng sản phẩm, hàng hóa và quy chuẩn kỹ thuật quốc gia: hàng thuộc diện quản lý phải chứng nhận, công bố hợp quy trước khi lưu thông.","Luật Bảo vệ quyền lợi người tiêu dùng 2023 và quy định thương mại điện tử về thông tin sản phẩm trung thực.","Điều khoản thương mại với nhà cung cấp: mua đứt, ký gửi, chiết khấu, phí trưng bày, điều kiện đổi trả."],en:["The 8-step category management process: definition, role, assessment, scorecard, strategy, tactics, implementation, review.","Assortment metrics: sell-through, stock age, days of stock, GMROI, gross margin and margin versus markup.","Product quality law and national technical regulations: regulated goods need conformity certification and declaration before sale.","Consumer Protection Law 2023 and e-commerce rules on truthful product information.","Supplier trade terms: outright purchase, consignment, discounts, display fees and return conditions."]},tools:["Hệ thống ERP / quản lý mua hàng","BI phân tích ngành hàng","Công cụ theo dõi giá thị trường","Bảng tính kế hoạch mua (OTB)","Cổng hồ sơ nhà cung cấp"],kpis:{vi:["Doanh thu và tăng trưởng của ngành hàng.","Biên lợi nhuận gộp và GMROI.","Tỷ lệ giá trị tồn kho quá 120 ngày.","Tỷ lệ hết hàng của các SKU chủ lực."],en:["Category revenue and growth.","Gross margin and GMROI.","Share of stock value older than 120 days.","Out-of-stock rate of core SKUs."]},day:[{time:"08:30",vi:"Xem bảng BI doanh số, tồn kho và giá thị trường của ngành hàng.",en:"Review category sales, stock and market price dashboards."},{time:"10:00",vi:"Đàm phán điều khoản quý mới với một nhà cung cấp chủ lực.",en:"Negotiate next quarter's terms with a key supplier."},{time:"13:30",vi:"Rà soát danh mục, đề xuất thêm, xả hoặc loại SKU theo chính sách.",en:"Review the assortment and propose adds, clearances or delists per policy."},{time:"15:00",vi:"Kiểm tra hồ sơ hợp quy, nhãn mác của sản phẩm mới trước khi mở bán.",en:"Check conformity and labeling files of new products before listing."},{time:"17:00",vi:"Hoàn thiện kế hoạch khuyến mại và kế hoạch mua cho tháng tới.",en:"Finalize next month's promotion and buying plans."}],mistakes:{vi:["Nhầm biên lợi nhuận gộp với tỷ lệ cộng thêm trên giá vốn khi định giá.","Loại SKU mua đứt khi còn tồn lớn không thể trả nhà cung cấp.","Mở bán hàng chưa đủ hồ sơ hợp quy vì áp lực doanh số hoặc tài trợ."],en:["Confusing gross margin with markup on cost when pricing.","Delisting an outright-purchase SKU while large unreturnable stock remains.","Listing goods without conformity papers because of sales pressure or sponsorship."]},career:[{vi:"Trợ lý ngành hàng",en:"Category assistant"},{vi:"Chuyên viên mua hàng ngành hàng",en:"Category buyer"},{vi:"Quản lý ngành hàng",en:"Category manager"},{vi:"Giám đốc ngành hàng / Giám đốc mua hàng",en:"Head of category or buying director"}],glossary:[{term:"Sell-through",vi:"Tỷ lệ số lượng bán ra trên số lượng nhận trong kỳ.",en:"Units sold divided by units received in the period."},{term:"GMROI",vi:"Lợi nhuận gộp tạo ra trên mỗi đồng tồn kho bình quân tính theo giá vốn.",en:"Gross margin earned per unit of average inventory at cost."},{term:"Markdown",vi:"Giảm giá có kế hoạch để xả hàng chậm luân chuyển hoặc cuối mùa.",en:"A planned price cut to clear slow-moving or end-of-season stock."},{term:"OTB",vi:"Ngân sách mua còn được phép trong kỳ sau khi trừ tồn kho và đơn đã đặt.",en:"Open-to-buy: remaining buying budget after stock and open orders."},{term:"Assortment",vi:"Danh mục sản phẩm: tập hợp SKU, mức giá, thương hiệu mà ngành hàng chào bán.",en:"The set of SKUs, price points and brands a category offers."}],quiz:[{q:{vi:"Giá vốn 360000 đồng, cần biên lợi nhuận gộp 20% trên giá bán. Giá bán là bao nhiêu?",en:"Cost is 360000 VND and a 20% gross margin on price is required. What is the price?"},options:{vi:["432000 đồng","450000 đồng","380000 đồng","460000 đồng"],en:["432000 VND","450000 VND","380000 VND","460000 VND"]},answer:1,explain:{vi:"360000 / (1 - 20%) = 450000; 432000 là markup 20% trên giá vốn, chỉ cho biên 16,7%.",en:"360000 / (1 - 20%) = 450000; 432000 is a 20% markup giving only 16.7% margin."}},{q:{vi:"Sell-through 90 ngày được tính như thế nào?",en:"How is 90-day sell-through calculated?"},options:{vi:["Tồn cuối kỳ / tồn đầu kỳ","Doanh thu / giá vốn","Số bán / số tồn cuối kỳ","Số lượng bán / số lượng nhận trong kỳ"],en:["Closing stock / opening stock","Revenue / cost","Units sold / closing stock","Units sold / units received in the period"]},answer:3,explain:{vi:"Sell-through cho biết bao nhiêu phần hàng nhận về đã bán được, ví dụ 180 / 1000 = 18%.",en:"Sell-through shows how much received stock has sold, e.g. 180 / 1000 = 18%."}},{q:{vi:"Nhà cung cấp đề nghị mở bán trước, bổ sung hồ sơ hợp quy sau, kèm tài trợ lớn. Bạn làm gì?",en:"A supplier asks to list now and add conformity papers later, with a big sponsorship. What do you do?"},options:{vi:["Nhận tài trợ và mở bán ngay","Mở bán ở mục ít người xem","Từ chối mở bán đến khi đủ hồ sơ, báo cáo và lên lịch ra mắt hợp lệ","Để nhà cung cấp tự đăng"],en:["Take the money and list now","List it in a low-traffic section","Refuse until the file is complete, escalate and schedule a lawful launch","Let the supplier list it themselves"]},answer:2,explain:{vi:"Hàng thuộc diện quản lý chưa hợp quy có thể gây mất an toàn và bị xử phạt; tài trợ không thay được hồ sơ.",en:"Regulated goods without conformity may be unsafe and fined; sponsorship never replaces paperwork."}},{q:{vi:"Chỉ số GMROI đo điều gì?",en:"What does GMROI measure?"},options:{vi:["Lợi nhuận gộp trên mỗi đồng tồn kho bình quân theo giá vốn","Tốc độ tăng trưởng doanh thu","Tỷ lệ khách quay lại mua","Chi phí quảng cáo trên doanh thu"],en:["Gross margin per unit of average inventory at cost","Revenue growth rate","Repeat purchase rate","Ad spend over revenue"]},answer:0,explain:{vi:"GMROI cho biết vốn tồn kho sinh lời ra sao, giúp quyết định giữ, xả hay loại SKU.",en:"GMROI shows how well inventory capital earns, guiding keep, clear or delist decisions."}}],tools_en:["ERP / procurement system","Category analytics BI","Market price tracking tool","Open-to-buy (OTB) planning spreadsheet","Supplier information portal"]}},"KK-333":{scenario:{legacy:"C"},learning:{summary:{vi:"Chuyên viên chăm sóc khách hàng và xử lý khiếu nại đa kênh tiếp nhận, giải quyết yêu cầu của khách qua tổng đài, chat, email, mạng xã hội, sàn thương mại điện tử và cửa hàng; ghi nhận đầy đủ trên hệ thống quản lý yêu cầu, phân loại mức ưu tiên, xử lý theo chính sách đổi trả, bảo hành, hoàn tiền và chuyển cấp đúng thời hạn cam kết (SLA). Nghề đòi hỏi kỹ năng lắng nghe, kiềm chế cảm xúc, hiểu sản phẩm, chính sách, pháp luật bảo vệ người tiêu dùng và giữ bí mật dữ liệu cá nhân của khách hàng.",en:"An omnichannel customer service specialist receives and resolves customer requests across the hotline, chat, email, social media, marketplaces and stores; logs every case in the ticketing system, sets priority, applies return, warranty and refund policies and escalates within the committed service level (SLA). The role requires active listening, emotional self-control, product and policy knowledge, consumer protection law and strict protection of customers' personal data."},responsibilities:{vi:["Tiếp nhận yêu cầu, khiếu nại trên mọi kênh và tạo phiếu với đầy đủ thông tin, bằng chứng.","Phân loại, xác định mức ưu tiên và xử lý theo chính sách đổi trả, bảo hành, hoàn tiền.","Chuyển cấp vụ việc vượt thẩm quyền cho bộ phận liên quan và theo dõi đến khi đóng phiếu.","Phản hồi khách đúng SLA và giữ thông tin nhất quán giữa các kênh.","Ghi nhận nguyên nhân gốc của khiếu nại và đề xuất cải tiến sản phẩm, quy trình."],en:["Receive requests and complaints on every channel and open tickets with full details and evidence.","Classify, prioritize and resolve cases under return, warranty and refund policies.","Escalate cases beyond your authority to the right team and follow them until closure.","Reply within the SLA and keep information consistent across channels.","Record complaint root causes and propose product and process improvements."]},competencies:[{name:{vi:"Lắng nghe & thấu cảm",en:"Active listening & empathy"},desc:{vi:"Nghe hết vấn đề, xác nhận lại cảm xúc và nhu cầu của khách trước khi đưa giải pháp.",en:"Hear the whole issue and acknowledge the customer's feelings and needs before offering a fix."}},{name:{vi:"Giải quyết vấn đề",en:"Problem solving"},desc:{vi:"Xác minh dữ kiện, tìm nguyên nhân và chọn phương án nằm trong chính sách.",en:"Verify facts, find causes and choose a solution within policy."}},{name:{vi:"Am hiểu chính sách & sản phẩm",en:"Policy & product knowledge"},desc:{vi:"Nắm điều kiện đổi trả, bảo hành, hoàn tiền và cách tra cứu cơ sở tri thức nhanh.",en:"Know return, warranty and refund conditions and search the knowledge base fast."}},{name:{vi:"Giao tiếp đa kênh",en:"Omnichannel communication"},desc:{vi:"Viết chat ngắn gọn, email chuẩn mực và phản hồi công khai trên mạng xã hội an toàn.",en:"Write concise chats, proper emails and safe public replies on social media."}},{name:{vi:"Bảo mật & chính trực",en:"Privacy & integrity"},desc:{vi:"Xác minh danh tính trước khi cung cấp thông tin, không hứa vượt thẩm quyền, không che giấu phản hồi tiêu cực.",en:"Verify identity before sharing data, never promise beyond authority and never hide negative feedback."}}],knowledge:{vi:["Luật Bảo vệ quyền lợi người tiêu dùng 2023: quyền khiếu nại của người tiêu dùng và nghĩa vụ tiếp nhận, giải quyết của tổ chức kinh doanh.","ISO 10002 hướng dẫn xử lý khiếu nại trong tổ chức và ISO 10004 về theo dõi, đo lường sự hài lòng của khách hàng.","ISO 18295 về yêu cầu đối với trung tâm liên lạc khách hàng.","Quy định về bảo vệ dữ liệu cá nhân: xác minh chủ thể, chỉ cung cấp thông tin đúng người, thông báo khi ghi âm cuộc gọi.","Chỉ số dịch vụ FCR, CSAT, NPS, AHT và cam kết SLA phản hồi, giải quyết."],en:["Consumer Protection Law 2023: consumers' right to complain and businesses' duty to receive and resolve complaints.","ISO 10002 guidelines for complaints handling and ISO 10004 for monitoring and measuring customer satisfaction.","ISO 18295 requirements for customer contact centres.","Personal data protection rules: verify the data subject, share data only with the right person, announce call recording.","Service metrics FCR, CSAT, NPS and AHT and response and resolution SLAs."]},tools:["Hệ thống quản lý yêu cầu (ticketing)","Tổng đài đa kênh (contact center)","Hệ thống CRM","Cơ sở tri thức nội bộ","Công cụ khảo sát hài lòng"],kpis:{vi:["Tỷ lệ giải quyết ngay lần liên hệ đầu tiên (FCR).","Điểm hài lòng sau tương tác (CSAT).","Tỷ lệ phiếu được phản hồi và giải quyết đúng SLA.","Tỷ lệ phiếu bị mở lại hoặc khiếu nại leo thang ra bên ngoài."],en:["First contact resolution rate (FCR).","Post-interaction satisfaction score (CSAT).","Share of tickets answered and resolved within SLA.","Reopened tickets or complaints escalated outside the company."]},day:[{time:"08:00",vi:"Đọc bàn giao ca, rà soát phiếu tồn sắp quá SLA và cảnh báo sự cố sản phẩm.",en:"Read the shift handover and review tickets near SLA breach and product incident alerts."},{time:"09:00",vi:"Trực tổng đài và chat giờ cao điểm, xử lý yêu cầu đổi trả, giao hàng.",en:"Handle peak-hour calls and chats on returns and deliveries."},{time:"11:30",vi:"Trả lời email, tin nhắn sàn thương mại điện tử và bình luận mạng xã hội.",en:"Answer emails, marketplace messages and social media comments."},{time:"14:00",vi:"Họp với kho, kỹ thuật về một vụ khiếu nại bảo hành phức tạp.",en:"Meet warehouse and technical teams on a complex warranty complaint."},{time:"16:30",vi:"Ghi nhận nguyên nhân gốc, cập nhật cơ sở tri thức và báo cáo cuối ca.",en:"Record root causes, update the knowledge base and file the end-of-shift report."}],mistakes:{vi:["Đóng phiếu khi khách chưa xác nhận vấn đề đã được giải quyết.","Cung cấp thông tin đơn hàng, tài khoản khi chưa xác minh đúng chủ thể dữ liệu.","Hứa bồi hoàn vượt thẩm quyền hoặc trả lời mỗi kênh một kiểu, làm khiếu nại leo thang."],en:["Closing a ticket before the customer confirms the issue is solved.","Sharing order or account data before verifying the data subject.","Promising compensation beyond authority or answering differently on each channel, escalating the complaint."]},career:[{vi:"Nhân viên chăm sóc khách hàng",en:"Customer service agent"},{vi:"Chuyên viên xử lý khiếu nại đa kênh",en:"Omnichannel complaints specialist"},{vi:"Trưởng nhóm / giám sát dịch vụ khách hàng",en:"Customer service team lead or supervisor"},{vi:"Quản lý trải nghiệm khách hàng",en:"Customer experience manager"}],glossary:[{term:"FCR",vi:"Tỷ lệ yêu cầu được giải quyết ngay trong lần liên hệ đầu tiên.",en:"Share of requests resolved in the first contact."},{term:"CSAT",vi:"Điểm hài lòng của khách sau một lần tương tác hoặc giải quyết khiếu nại.",en:"Customer satisfaction score after an interaction or complaint resolution."},{term:"NPS",vi:"Chỉ số sẵn lòng giới thiệu: tỷ lệ khách chấm 9-10 trừ tỷ lệ khách chấm 0-6.",en:"Net Promoter Score: share of 9-10 scores minus share of 0-6 scores."},{term:"SLA",vi:"Cam kết mức độ dịch vụ: thời hạn phản hồi và giải quyết cho từng mức ưu tiên.",en:"Service level agreement: response and resolution times per priority."},{term:"Escalation",vi:"Chuyển cấp: chuyển vụ việc vượt thẩm quyền lên cấp hoặc bộ phận có quyền quyết định.",en:"Passing a case beyond your authority to the level or team that can decide."}],quiz:[{q:{vi:"Khảo sát 200 khách: 110 chấm 9-10, 50 chấm 7-8, 40 chấm 0-6. NPS là bao nhiêu?",en:"Of 200 surveyed customers, 110 scored 9-10, 50 scored 7-8 and 40 scored 0-6. What is the NPS?"},options:{vi:["55","15","35","45"],en:["55","15","35","45"]},answer:2,explain:{vi:"Tỷ lệ khách ủng hộ 55% trừ tỷ lệ khách phản đối 20% = 35; nhóm 7-8 là trung lập, không tính.",en:"55% promoters minus 20% detractors = 35; the 7-8 group is passive and not counted."}},{q:{vi:"Chỉ số FCR đo điều gì?",en:"What does FCR measure?"},options:{vi:["Tỷ lệ vấn đề được giải quyết ngay lần liên hệ đầu tiên","Thời gian xử lý trung bình mỗi cuộc gọi","Số cuộc gọi nhỡ trong ca","Điểm hài lòng sau khảo sát"],en:["Share of issues resolved in the first contact","Average handling time per call","Missed calls per shift","Post-survey satisfaction score"]},answer:0,explain:{vi:"FCR cao giảm số lần khách phải liên hệ lại và thường đi cùng mức hài lòng cao hơn.",en:"High FCR reduces repeat contacts and usually goes with higher satisfaction."}},{q:{vi:"Người gọi tự xưng là chồng của chủ tài khoản, yêu cầu đọc địa chỉ và lịch sử đơn hàng của vợ. Bạn làm gì?",en:"A caller says he is the account holder's husband and asks for her address and order history. What do you do?"},options:{vi:["Đọc vì là người nhà","Chỉ đọc địa chỉ giao hàng","Gửi thông tin qua tin nhắn cho người gọi","Từ chối khi chưa xác minh đúng chủ tài khoản và hướng dẫn chủ tài khoản liên hệ"],en:["Share it because he is family","Share only the delivery address","Text the data to the caller","Decline until the account holder is verified and guide her to contact you"]},answer:3,explain:{vi:"Dữ liệu cá nhân chỉ được cung cấp cho đúng chủ thể hoặc người được ủy quyền hợp lệ sau khi xác minh.",en:"Personal data may only go to the verified data subject or a validly authorized person."}},{q:{vi:"Khách đòi bồi thường vượt chính sách và dọa đăng lên mạng xã hội. Phương án đúng là gì?",en:"A customer demands compensation beyond policy and threatens to post on social media. What is right?"},options:{vi:["Đồng ý ngay để tránh khủng hoảng","Lắng nghe, ghi nhận, giải thích chính sách, chuyển cấp có thẩm quyền xét ngoại lệ và hẹn thời hạn phản hồi","Chặn khách trên mọi kênh","Xóa bình luận tiêu cực của khách"],en:["Agree at once to avoid a crisis","Listen, log it, explain the policy, escalate for an exception review and commit a reply time","Block the customer on all channels","Delete the customer's negative comments"]},answer:1,explain:{vi:"Xử lý bình tĩnh, minh bạch và đúng thẩm quyền giữ được niềm tin; hứa vượt chính sách hoặc che giấu đều làm vụ việc tệ hơn.",en:"Calm, transparent handling within authority keeps trust; over-promising or hiding feedback makes it worse."}}],tools_en:["Ticketing system","Omnichannel contact center","CRM system","Internal knowledge base","Customer satisfaction survey tools"]}},"KK-334":{scenario:{company:"Hạt Sen Mini Mart",supervisor:{name:"Trịnh Văn Long",role:{vi:"Quản lý Vùng Cửa hàng",en:"Area Store Manager"}},ref_code:"STK-0458",title:{vi:"Đúng nguyên nhân. Đúng tỷ lệ. Đúng sự thật.",en:"Right cause. Right rate. Right facts."},brief:{vi:"Bạn chốt báo cáo kiểm kê tháng 10 STK-0458 của cửa hàng. Tổng chênh lệch thiếu theo giá bán lẻ là 18600000 đồng; doanh thu thuần tháng 1240000000 đồng. Riêng sữa tươi thùng 48 hộp thiếu 12 thùng (4200000 đồng): camera và phiếu giao cho thấy nhà cung cấp giao 36 thùng nhưng nhân viên ký nhận 48, nhà cung cấp đã xác nhận bù. Sửa mã nguyên nhân của mặt hàng này và tỷ lệ hao hụt tháng, rồi lập báo cáo có căn cứ.",en:"You are closing the October stock count report STK-0458 for your store. Total count shortage at retail value is 18600000 VND; monthly net sales are 1240000000 VND. Fresh milk cases of 48 are 12 cases short (4200000 VND): camera footage and the delivery note show the supplier delivered 36 cases but staff signed for 48, and the supplier has confirmed a credit. Correct this item's variance reason code and the monthly shrink rate, then write an evidence-based report."},reference_title:{vi:"Biên bản kiểm kê & bảng đối soát hao hụt đã duyệt · STK-0458",en:"Approved stock count record & shrink reconciliation · STK-0458"},fields:[{id:"VAR_REASON",label:{vi:"Mã nguyên nhân chênh lệch sữa tươi",en:"Fresh milk variance reason code"},initial:"UNKNOWN-LOSS",expected:"ADMIN-ERROR",choices:["UNKNOWN-LOSS","ADMIN-ERROR","DAMAGE"],reference:"Biên bản đối chiếu nhận hàng",hint:{vi:"Chênh lệch đã có bằng chứng camera và phiếu giao thì không còn là hao hụt không rõ nguyên nhân.",en:"A variance proven by camera and delivery note is no longer an unexplained loss."}},{id:"SHRINK_PCT",label:{vi:"Tỷ lệ hao hụt tháng (%)",en:"Monthly shrink rate (%)"},initial:"1.50",expected:"1.16",reference:"Bảng đối soát hao hụt",ref_value:{vi:"Chênh lệch 18600000 đ (giá bán lẻ), gồm 4200000 đ NCC giao thiếu đã xác nhận bù; doanh thu thuần 1240000000 đ",en:"Shortage 18600000 VND at retail, incl. 4200000 VND supplier short-delivery credited; net sales 1240000000 VND"},hint:{vi:"Bản nháp chia toàn bộ chênh lệch cho doanh thu, chưa loại phần lỗi chứng từ đã được bù.",en:"The draft divides the full shortage by sales without removing the credited paperwork error."}}],sop32:{vi:"Tỷ lệ hao hụt (%) = (tổng chênh lệch kiểm kê theo giá bán lẻ - phần lỗi chứng từ đã được nhà cung cấp xác nhận bù) / doanh thu thuần tháng x 100, làm tròn 2 chữ số thập phân. Mục tiêu mô phỏng 1%.",en:"Shrink rate (%) = (total count shortage at retail - paperwork errors credited by the supplier) / monthly net sales x 100, rounded to 2 decimals. Training target 1%."},context:{label:"POS-ERP / STK-0458",metrics:[{label:{vi:"Chênh lệch kiểm kê",en:"Count shortage"},value:"18,600,000 VND"},{label:{vi:"Doanh thu thuần tháng",en:"Monthly net sales"},value:"1,240,000,000 VND"},{label:{vi:"NCC xác nhận bù",en:"Supplier credit"},value:"4,200,000 VND"},{label:{vi:"Mục tiêu hao hụt",en:"Shrink target"},value:"1.00%"}]},crisis:{vi:"Cửa hàng phó đề xuất: “Tỷ lệ vẫn trên 1%, quý này xét thưởng cả cửa hàng. Chị ghi phần thiếu còn lại thành hàng hư hỏng, rồi trừ đều vào lương 6 bạn ca tối cho xong.”",en:"The assistant store manager proposes: “The rate is still above 1% and the store bonus is reviewed this quarter. Record the remaining shortage as damage and deduct it evenly from the six evening staff's wages.”"},options:{safe:{vi:"Không ghi sai mã nguyên nhân và không tự trừ lương khi chưa xác minh; báo Quản lý vùng và bộ phận chống thất thoát, rà soát camera, quy trình nhận hàng và xử lý trách nhiệm đúng quy định.",en:"Do not falsify reason codes or deduct wages without investigation; inform the area manager and loss prevention, review cameras and receiving, and handle liability by the rules."},shortcut:{vi:"Ghi phần thiếu thành hàng hư hỏng và trừ đều lương ca tối để báo cáo đạt mục tiêu.",en:"Record the shortage as damage and split it across evening wages to hit the target."},wait:{vi:"Để nguyên bản nháp và chờ quản lý vùng tự phát hiện khi kiểm tra.",en:"Leave the draft unchanged and wait for the area manager to notice on audit."}},questions:{vi:["Vì sao chênh lệch sữa tươi phải mã ADMIN-ERROR chứ không phải UNKNOWN-LOSS hay DAMAGE? Bằng chứng nào chứng minh?","Trình bày cách tính tỷ lệ hao hụt và rủi ro pháp lý khi trừ lương tập thể không có biên bản."],en:["Why must the milk variance be ADMIN-ERROR rather than UNKNOWN-LOSS or DAMAGE? Which evidence proves it?","Explain the shrink rate calculation and the legal risk of deducting team wages without a formal record."]},hints:{vi:["Đặt bản nháp cạnh biên bản đối chiếu nhận hàng, xác định chênh lệch phát sinh ở khâu nào.","Theo SOP mục 3.2, loại phần đã được nhà cung cấp xác nhận bù trước khi chia cho doanh thu thuần.","Đọc lại SOP mục 4.2: số liệu kiểm kê phải trung thực; trách nhiệm cá nhân chỉ xử lý sau khi xác minh."],en:["Place the draft next to the receiving reconciliation and find at which step the variance arose.","Per SOP 3.2, remove the supplier-credited part before dividing by net sales.","Re-read SOP 4.2: count data must be truthful; personal liability follows only after investigation."]}},learning:{summary:{vi:"Quản lý cửa hàng bán lẻ chuỗi điều hành toàn bộ một cửa hàng: doanh số, lợi nhuận, nhân sự, tồn kho, trưng bày, dịch vụ khách hàng, an toàn và tuân thủ tiêu chuẩn của chuỗi. Nghề đòi hỏi khả năng lập lịch ca, huấn luyện đội ngũ, đọc báo cáo bán hàng, kiểm soát hao hụt và hàng cận hạn, xử lý sự cố tại chỗ và giữ trung thực tuyệt đối trong số liệu kiểm kê, tiền mặt.",en:"A chain retail store manager runs a whole store: sales, profit, staff, stock, displays, customer service, safety and compliance with chain standards. The role needs shift planning, team coaching, reading sales reports, controlling shrink and near-expiry goods, handling incidents on the spot and absolute honesty in stock count and cash figures."},responsibilities:{vi:["Lập kế hoạch doanh số, lịch ca, phân công và giám sát chất lượng phục vụ.","Kiểm soát nhận hàng, tồn kho, hạn sử dụng theo FEFO và kiểm kê định kỳ.","Triển khai trưng bày theo planogram, chương trình khuyến mại và giá niêm yết đúng.","Quản lý tiền mặt, két, đối soát POS và phòng chống thất thoát.","Bảo đảm an toàn thực phẩm, phòng cháy chữa cháy, an toàn lao động và xử lý khiếu nại."],en:["Plan sales and shifts, assign tasks and monitor service quality.","Control receiving, stock and expiry dates by FEFO and run periodic counts.","Implement planogram displays, promotions and correct shelf prices.","Manage cash, the safe, POS reconciliation and loss prevention.","Ensure food safety, fire safety, occupational safety and complaint handling."]},competencies:[{name:{vi:"Lãnh đạo đội ngũ ca",en:"Shift team leadership"},desc:{vi:"Tuyển, đào tạo, xếp ca hợp lý và giữ động lực cho nhân viên bán hàng, thu ngân.",en:"Hire, train, schedule fairly and motivate sales and cashier staff."}},{name:{vi:"Vận hành & tồn kho",en:"Operations & inventory"},desc:{vi:"Kiểm soát nhận hàng, xoay vòng hàng, hàng cận hạn và chênh lệch kiểm kê.",en:"Control receiving, stock rotation, near-expiry goods and count variances."}},{name:{vi:"Phân tích kinh doanh cửa hàng",en:"Store business analysis"},desc:{vi:"Đọc doanh số theo giờ, ngành hàng, giá trị giỏ hàng để điều chỉnh nhân sự và trưng bày.",en:"Read sales by hour, category and basket value to adjust staffing and displays."}},{name:{vi:"Trải nghiệm khách hàng",en:"Customer experience"},desc:{vi:"Giữ cửa hàng sạch, đủ hàng, thanh toán nhanh và xử lý khiếu nại tại chỗ.",en:"Keep the store clean, stocked and fast at checkout and resolve complaints on the spot."}},{name:{vi:"Liêm chính & tuân thủ",en:"Integrity & compliance"},desc:{vi:"Báo cáo số liệu thật, xử lý kỷ luật, bồi thường đúng luật lao động.",en:"Report real figures and handle discipline and liability under labor law."}}],knowledge:{vi:["Bộ luật Lao động 2019: thời giờ làm việc, làm thêm giờ, kỷ luật, bồi thường thiệt hại; khấu trừ lương không quá 30% tiền lương thực trả hằng tháng.","Luật An toàn thực phẩm 2010: điều kiện bảo quản, truy xuất nguồn gốc và xử lý thực phẩm hết hạn.","Quản lý tồn kho bán lẻ: FIFO, FEFO, kiểm kê chu kỳ, phân loại hao hụt rõ nguyên nhân và không rõ nguyên nhân.","Planogram, quản trị không gian kệ và nguyên tắc trưng bày theo hành vi mua sắm.","Quy định hiện hành về phòng cháy, chữa cháy và cứu nạn, cứu hộ đối với cơ sở kinh doanh."],en:["Labor Code 2019: working hours, overtime, discipline and damages; wage deductions capped at 30% of the monthly net wage.","Food Safety Law 2010: storage conditions, traceability and handling expired food.","Retail inventory control: FIFO, FEFO, cycle counts and known versus unknown shrink.","Planograms, shelf space management and display principles based on shopper behavior.","Current fire prevention, firefighting and rescue rules for business premises."]},tools:["Hệ thống POS","Phần mềm ERP / quản lý kho","Máy quét mã vạch cầm tay","Hệ thống camera giám sát","Ứng dụng lập lịch ca"],kpis:{vi:["Doanh số so với kế hoạch và doanh thu trên mỗi mét vuông.","Tỷ lệ hao hụt so với doanh thu thuần.","Tỷ lệ hàng hết trên kệ và giá trị hàng hủy do hết hạn.","Điểm đánh giá của khách hàng bí mật và mức hài lòng khách hàng."],en:["Sales versus plan and sales per square meter.","Shrink as a share of net sales.","Out-of-shelf rate and value of expired write-offs.","Mystery shopper score and customer satisfaction."]},day:[{time:"06:30",vi:"Mở cửa hàng, kiểm tra an toàn, két tiền đầu ca và chất lượng hàng tươi.",en:"Open the store, check safety, the opening float and fresh produce quality."},{time:"08:30",vi:"Giám sát nhận hàng, đếm thực tế trước khi ký phiếu giao.",en:"Supervise receiving and count physically before signing delivery notes."},{time:"11:00",vi:"Kiểm tra trưng bày, giá niêm yết, hàng cận hạn và bổ sung kệ giờ cao điểm.",en:"Check displays, shelf prices, near-expiry items and peak-hour replenishment."},{time:"14:00",vi:"Huấn luyện nhân viên mới, lập lịch ca tuần và xử lý khiếu nại.",en:"Coach new staff, build the weekly rota and handle complaints."},{time:"21:30",vi:"Đối soát POS, két tiền, chênh lệch tồn và gửi báo cáo ngày.",en:"Reconcile POS, cash and stock variances and send the daily report."}],mistakes:{vi:["Ký nhận đủ hàng theo phiếu giao mà không đếm thực tế.","Gộp mọi chênh lệch vào hao hụt không rõ nguyên nhân hoặc ghi sai mã để đẹp báo cáo.","Trừ lương tập thể khi chưa có biên bản, chưa xác minh và vượt giới hạn luật cho phép."],en:["Signing for full deliveries without a physical count.","Lumping all variances into unknown shrink or using false codes to look good.","Deducting team wages without a record or investigation, or beyond legal limits."]},career:[{vi:"Nhân viên bán hàng / thu ngân",en:"Sales associate or cashier"},{vi:"Trưởng ca cửa hàng",en:"Shift leader"},{vi:"Quản lý cửa hàng",en:"Store manager"},{vi:"Quản lý vùng cửa hàng",en:"Area store manager"}],glossary:[{term:"Shrinkage",vi:"Hao hụt: phần hàng mất mát do trộm cắp, hư hỏng, lỗi chứng từ hoặc không rõ nguyên nhân.",en:"Stock loss from theft, damage, paperwork errors or unknown causes."},{term:"FEFO",vi:"Hàng hết hạn trước xuất trước, áp dụng cho hàng có hạn sử dụng.",en:"First expired, first out, used for goods with expiry dates."},{term:"Planogram",vi:"Sơ đồ trưng bày quy định vị trí, số mặt hàng và thứ tự sản phẩm trên kệ.",en:"A shelf map defining product positions, facings and order."},{term:"Cycle count",vi:"Kiểm kê chu kỳ: đếm luân phiên từng nhóm hàng thay vì đóng cửa kiểm kê toàn bộ.",en:"Counting product groups in rotation instead of a full shutdown count."},{term:"Mystery shopper",vi:"Khách hàng bí mật đánh giá dịch vụ, trưng bày theo tiêu chuẩn của chuỗi.",en:"An anonymous evaluator who rates service and displays against chain standards."}],quiz:[{q:{vi:"Chênh lệch kiểm kê 9000000 đồng, trong đó 1500000 do nhà cung cấp giao thiếu đã xác nhận bù; doanh thu thuần 600000000 đồng. Tỷ lệ hao hụt là bao nhiêu?",en:"Count shortage is 9000000 VND, of which 1500000 is a credited supplier short-delivery; net sales are 600000000 VND. What is the shrink rate?"},options:{vi:["1,50%","1,00%","0,25%","1,25%"],en:["1.50%","1.00%","0.25%","1.25%"]},answer:3,explain:{vi:"Loại phần đã được bù trước: (9000000 - 1500000) / 600000000 = 1,25%.",en:"(9000000 - 1500000) / 600000000 = 1.25%."}},{q:{vi:"Theo Bộ luật Lao động 2019, khấu trừ tiền lương hằng tháng để bồi thường thiệt hại không được vượt quá mức nào?",en:"Under the Labor Code 2019, what is the cap on monthly wage deductions for damages?"},options:{vi:["10% tiền lương","30% tiền lương thực trả hằng tháng","50% tiền lương","Toàn bộ tiền lương"],en:["10% of wages","30% of the monthly net wage","50% of wages","The whole wage"]},answer:1,explain:{vi:"Khấu trừ không quá 30% tiền lương thực trả hằng tháng và phải theo đúng trình tự xử lý bồi thường.",en:"Deductions may not exceed 30% of the monthly net wage and must follow the proper liability procedure."}},{q:{vi:"Cửa hàng phó đề nghị ghi phần thiếu thành hàng hư hỏng để đạt KPI hao hụt. Bạn làm gì?",en:"The assistant manager suggests booking the shortage as damage to hit the shrink KPI. What do you do?"},options:{vi:["Đồng ý vì giúp cả cửa hàng có thưởng","Ghi một nửa là hư hỏng cho cân bằng","Từ chối, giữ mã đúng, báo quản lý vùng và chống thất thoát để điều tra","Xóa phiếu kiểm kê và đếm lại đến khi khớp"],en:["Agree so the store gets its bonus","Book half as damage to balance it","Refuse, keep true codes and report to the area manager and loss prevention","Delete the count sheet and recount until it matches"]},answer:2,explain:{vi:"Ghi sai mã che giấu nguyên nhân thật, làm chuỗi không xử lý được rủi ro và là hành vi gian lận số liệu.",en:"False codes hide the real cause, stop the chain from fixing risk and are data fraud."}},{q:{vi:"FEFO trong quản lý hàng có hạn sử dụng nghĩa là gì?",en:"What does FEFO mean for dated goods?"},options:{vi:["Hàng hết hạn trước xuất trước","Hàng nhập trước xuất trước","Hàng nhập sau xuất trước","Hàng giá cao xuất trước"],en:["First expired, first out","First in, first out","Last in, first out","Highest price out first"]},answer:0,explain:{vi:"FEFO ưu tiên bán hàng có hạn dùng gần nhất, giảm hàng hủy và rủi ro an toàn thực phẩm.",en:"FEFO sells the nearest expiry first, cutting write-offs and food safety risk."}}],tools_en:["POS system","ERP / inventory management software","Handheld barcode scanners","CCTV surveillance system","Shift scheduling app"]}},"KK-335":{scenario:{company:"Sóc Nâu English Online",supervisor:{name:"Đinh Thị Mai",role:{vi:"Trưởng nhóm Telesales",en:"Telesales Team Lead"}},ref_code:"OD-2217",title:{vi:"Đúng ưu đãi. Đúng số tiền. Đúng lời hứa.",en:"Right offer. Right amount. Honest promise."},brief:{vi:"Bạn kiểm tra đơn OD-2217 vừa chốt qua điện thoại: khách đã học gói 12 tháng năm trước, gói hết hạn cách đây 2 tháng, không có mã giới thiệu. Gói 12 tháng giá niêm yết 7200000 đồng. Ưu đãi mô phỏng: NEW30 giảm 30% chỉ cho khách chưa từng mua; RENEW15 giảm 15% cho khách cũ gia hạn trong 6 tháng sau hết hạn; REFER10 giảm 10% khi có mã giới thiệu. Khách trả góp 6 kỳ qua thẻ. Sửa mã ưu đãi và số tiền mỗi kỳ, rồi lập báo cáo có căn cứ.",en:"You are checking order OD-2217 closed by phone: the customer took the 12-month package last year, it expired 2 months ago, and there is no referral code. The 12-month package lists at 7200000 VND. Training offers: NEW30 gives 30% off for first-time buyers only; RENEW15 gives 15% off for returning customers renewing within 6 months of expiry; REFER10 gives 10% off with a referral code. The customer pays in 6 card installments. Correct the promo code and the installment amount, then write an evidence-based report."},reference_title:{vi:"Chính sách ưu đãi & bảng tính trả góp đã duyệt · OD-2217",en:"Approved offer policy & installment sheet · OD-2217"},fields:[{id:"PROMO_CODE",label:{vi:"Mã ưu đãi áp dụng",en:"Applied promo code"},initial:"NEW30",expected:"RENEW15",choices:["NEW30","RENEW15","REFER10"],reference:"Chính sách ưu đãi tháng",hint:{vi:"Tra lịch sử mua của khách trên CRM rồi đối chiếu điều kiện đối tượng của từng mã.",en:"Check the customer's purchase history in the CRM and match each code's eligibility."}},{id:"INSTALL_AMT",label:{vi:"Số tiền mỗi kỳ trả góp (VND)",en:"Amount per installment (VND)"},initial:"840000",expected:"1050600",reference:"Bảng tính trả góp",ref_value:{vi:"Giá niêm yết 7200000 đồng; khách cũ hết hạn 2 tháng; trả góp 6 kỳ qua thẻ",en:"List price 7200000 VND; returning customer expired 2 months ago; 6 card installments"},hint:{vi:"Bản nháp dùng sai tỷ lệ ưu đãi và quên phí chuyển đổi trả góp.",en:"The draft uses the wrong discount rate and forgets the installment conversion fee."}}],sop32:{vi:"Số tiền mỗi kỳ = giá niêm yết x (1 - tỷ lệ ưu đãi hợp lệ) x (1 + phí chuyển đổi trả góp 3%) / số kỳ. Phí 3% là số liệu mô phỏng và phải được báo rõ cho khách trước khi chốt.",en:"Amount per installment = list price x (1 - valid discount) x (1 + 3% installment conversion fee) / number of installments. The 3% fee is a training figure and must be disclosed before closing."},context:{label:"CRM-CALL / OD-2217",metrics:[{label:{vi:"Giá niêm yết gói 12 tháng",en:"12-month list price"},value:"7,200,000 VND"},{label:{vi:"Số kỳ trả góp",en:"Installments"},value:"6"},{label:{vi:"Phí chuyển đổi mô phỏng",en:"Training conversion fee"},value:"3%"},{label:{vi:"Số tháng từ khi hết hạn",en:"Months since expiry"},value:"2"}]},crisis:{vi:"Trưởng phòng kinh doanh nhắn cả nhóm: “Cuối tháng rồi, cứ nói với khách là học xong cam kết đầu ra IELTS 7.0, không đạt hoàn 100%, và ưu đãi chỉ còn hôm nay dù chương trình kéo dài đến cuối tháng.”",en:"The sales director messages the team: “It is month end. Tell customers we guarantee an IELTS 7.0 result or a 100% refund, and that the offer ends today even though it runs to month end.”"},options:{safe:{vi:"Từ chối hứa đầu ra và tạo khan hiếm giả; chỉ dùng kịch bản, chính sách hoàn tiền đã duyệt, báo Trưởng nhóm và bộ phận kiểm soát chất lượng cuộc gọi; đề xuất mời khách học thử, kiểm tra trình độ.",en:"Refuse the outcome guarantee and fake urgency; use only the approved script and refund policy, inform the team lead and call QA; propose a trial class and placement test."},shortcut:{vi:"Nói theo chỉ đạo cho kịp chỉ tiêu, nếu khách khiếu nại thì để bộ phận chăm sóc xử lý.",en:"Say it as instructed to hit the target and let customer care deal with complaints."},wait:{vi:"Tạm ngừng gọi, không phản hồi và chờ xem đồng nghiệp làm thế nào.",en:"Stop calling, give no reply and wait to see what colleagues do."}},questions:{vi:["Vì sao đơn OD-2217 phải dùng RENEW15 thay vì NEW30 hay REFER10? Dữ liệu CRM nào chứng minh?","Trình bày cách tính số tiền mỗi kỳ và rủi ro khi hứa cam kết đầu ra hoặc tạo khan hiếm giả qua điện thoại."],en:["Why must order OD-2217 use RENEW15 instead of NEW30 or REFER10? Which CRM data proves it?","Explain the installment calculation and the risk of promising guaranteed results or fake urgency by phone."]},hints:{vi:["Đặt bản nháp cạnh chính sách ưu đãi, kiểm tra khách thuộc nhóm đối tượng nào và có mã giới thiệu không.","Tính theo SOP mục 3.2: ưu đãi trước, cộng phí chuyển đổi rồi chia đều cho số kỳ.","Đọc lại SOP mục 4.2: không đưa thông tin gian dối cho khách; chỉ đạo sai phải được báo cáo."],en:["Place the draft next to the offer policy and check the customer's segment and referral status.","Compute per SOP 3.2: discount first, add the conversion fee, then divide by the installments.","Re-read SOP 4.2: never give customers false information; wrong instructions must be escalated."]}},learning:{summary:{vi:"Chuyên viên bán hàng qua điện thoại (inside sales, telesales) tư vấn và chốt đơn từ xa qua cuộc gọi, tin nhắn, video: gọi danh sách khách hàng tiềm năng hợp lệ, khai thác nhu cầu, giới thiệu sản phẩm phù hợp, xử lý từ chối, áp dụng đúng ưu đãi và hoàn tất đơn hàng trên CRM. Nghề đòi hỏi giọng nói rõ ràng, kỹ năng đặt câu hỏi, tính giá chính xác, chịu áp lực chỉ tiêu và tuân thủ nghiêm quy định về cuộc gọi quảng cáo, dữ liệu cá nhân và quyền lợi người tiêu dùng.",en:"An inside sales or telesales executive advises and closes deals remotely by call, message and video: calling lawful prospect lists, discovering needs, presenting the right product, handling objections, applying the correct offer and completing the order in the CRM. The role needs a clear voice, questioning skills, accurate pricing, resilience under targets and strict compliance with marketing call, personal data and consumer protection rules."},responsibilities:{vi:["Gọi danh sách khách hàng tiềm năng có nguồn hợp lệ, loại bỏ số đã đăng ký không nhận quảng cáo.","Khai thác nhu cầu và tư vấn gói phù hợp theo kịch bản, chính sách đã duyệt.","Áp dụng đúng mã ưu đãi, tính giá, trả góp và xác nhận lại điều khoản trước khi chốt.","Ghi kết quả cuộc gọi, mã trạng thái và lịch gọi lại đầy đủ trên CRM.","Phối hợp chăm sóc khách sau bán và báo cáo tỷ lệ chuyển đổi hằng ngày."],en:["Call lawfully sourced prospect lists and remove numbers registered as do-not-call.","Discover needs and recommend the right package using the approved script and policy.","Apply the correct promo code, price and installments and confirm terms before closing.","Log call results, disposition codes and callbacks fully in the CRM.","Coordinate after-sales care and report daily conversion rates."]},competencies:[{name:{vi:"Giao tiếp qua giọng nói",en:"Voice communication"},desc:{vi:"Mở lời tự tin, nói rõ, nhịp độ phù hợp và tạo thiện cảm trong 30 giây đầu.",en:"Open confidently, speak clearly at the right pace and build rapport in 30 seconds."}},{name:{vi:"Khai thác nhu cầu",en:"Needs discovery"},desc:{vi:"Dùng câu hỏi mở, kỹ thuật SPIN để hiểu mục tiêu, khó khăn và khả năng chi trả.",en:"Use open and SPIN questions to understand goals, pain points and budget."}},{name:{vi:"Xử lý từ chối",en:"Objection handling"},desc:{vi:"Lắng nghe, xác nhận, trả lời bằng giá trị thật và kiểm tra lại mối quan tâm của khách.",en:"Listen, acknowledge, answer with real value and check the concern again."}},{name:{vi:"Chính xác giá & điều khoản",en:"Price & terms accuracy"},desc:{vi:"Áp đúng ưu đãi, phí trả góp và đọc lại tổng chi phí cho khách trước khi chốt.",en:"Apply the right offer and fees and read back the total cost before closing."}},{name:{vi:"Tuân thủ & trung thực",en:"Compliance & honesty"},desc:{vi:"Không hứa sai sự thật, không tạo khan hiếm giả, tôn trọng yêu cầu ngừng liên hệ.",en:"No false promises or fake urgency, and respect requests to stop contact."}}],knowledge:{vi:["Nghị định 91/2020/NĐ-CP về chống tin nhắn rác, thư điện tử rác, cuộc gọi rác: danh sách không quảng cáo, khung giờ và tần suất gọi theo quy định.","Luật Bảo vệ quyền lợi người tiêu dùng 2023: giao dịch từ xa, nghĩa vụ cung cấp thông tin trung thực, cấm thông tin gian dối.","Quy định về bảo vệ dữ liệu cá nhân: nguồn dữ liệu hợp pháp, sự đồng ý và quyền phản đối tiếp thị của khách.","Kỹ thuật bán hàng tư vấn SPIN (Tình huống, Vấn đề, Hệ quả, Lợi ích) và mô hình xử lý từ chối.","Cách tính ưu đãi, trả góp, phí chuyển đổi và nghĩa vụ công bố đầy đủ chi phí cho khách."],en:["Decree 91/2020/ND-CP on spam messages, emails and calls: do-not-call list and regulated calling hours and frequency.","Consumer Protection Law 2023: remote transactions, the duty to give truthful information and the ban on deceptive claims.","Personal data protection rules: lawful data sources, consent and the customer's right to object to marketing.","SPIN consultative selling (Situation, Problem, Implication, Need-payoff) and objection handling models.","Calculating discounts, installments and conversion fees and the duty to disclose all costs."]},tools:["Tổng đài VoIP / auto dialer","Hệ thống CRM","Kịch bản cuộc gọi số hóa","Công cụ ghi âm & chấm điểm cuộc gọi","Cổng thanh toán và trả góp"],kpis:{vi:["Tỷ lệ chuyển đổi từ cuộc gọi kết nối sang đơn hàng.","Doanh thu chốt mỗi ngày và mỗi giờ gọi.","Tỷ lệ đơn hủy, hoàn tiền do tư vấn sai (mục tiêu bằng 0).","Điểm kiểm soát chất lượng cuộc gọi về tuân thủ kịch bản."],en:["Conversion rate from connected calls to orders.","Revenue closed per day and per calling hour.","Cancellations or refunds caused by wrong advice (target zero).","Call QA score for script compliance."]},day:[{time:"08:15",vi:"Họp đầu ca, cập nhật ưu đãi đang chạy và danh sách gọi đã lọc số từ chối.",en:"Shift huddle on current offers and the call list cleaned of opt-outs."},{time:"08:30",vi:"Gọi khung giờ sáng cho khách mới và khách cũ sắp hết hạn gói.",en:"Morning calling block for new prospects and customers near expiry."},{time:"13:30",vi:"Gọi lại theo lịch hẹn, tư vấn chi tiết và gửi đường dẫn thanh toán.",en:"Scheduled callbacks, detailed advice and sending payment links."},{time:"15:30",vi:"Rà soát đơn đã chốt: mã ưu đãi, số tiền trả góp, xác nhận thanh toán.",en:"Review closed orders: promo codes, installment amounts and payment confirmation."},{time:"17:30",vi:"Nghe lại cuộc gọi cùng bộ phận chất lượng và báo cáo kết quả ngày.",en:"Review recorded calls with QA and report the day's results."}],mistakes:{vi:["Áp mã ưu đãi cho sai đối tượng khiến đơn bị điều chỉnh, khách mất niềm tin.","Báo số tiền trả góp mà quên phí chuyển đổi, khách khiếu nại sau khi thanh toán.","Hứa cam kết kết quả, tạo khan hiếm giả hoặc tiếp tục gọi số đã từ chối."],en:["Applying an offer to the wrong segment so the order must be corrected and trust is lost.","Quoting installments without the conversion fee, leading to complaints after payment.","Promising guaranteed results, faking urgency or calling numbers that opted out."]},career:[{vi:"Nhân viên telesales",en:"Telesales agent"},{vi:"Chuyên viên inside sales",en:"Inside sales executive"},{vi:"Trưởng nhóm telesales",en:"Telesales team lead"},{vi:"Quản lý trung tâm bán hàng từ xa",en:"Remote sales center manager"}],glossary:[{term:"Call disposition",vi:"Mã trạng thái kết quả cuộc gọi như quan tâm, gọi lại, không nghe máy, từ chối liên hệ.",en:"A call outcome code such as interested, callback, no answer or do not call."},{term:"DNC",vi:"Danh sách không nhận cuộc gọi quảng cáo; số trong danh sách phải được loại khỏi chiến dịch.",en:"Do-not-call list; listed numbers must be removed from campaigns."},{term:"Conversion rate",vi:"Tỷ lệ cuộc gọi kết nối hoặc khách tiềm năng chuyển thành đơn hàng.",en:"Share of connected calls or prospects that become orders."},{term:"SPIN",vi:"Kỹ thuật đặt câu hỏi theo Tình huống, Vấn đề, Hệ quả, Lợi ích mong muốn.",en:"Questioning on Situation, Problem, Implication and Need-payoff."},{term:"Call QA",vi:"Chấm điểm chất lượng cuộc gọi theo tiêu chí kịch bản, thái độ và tuân thủ.",en:"Scoring recorded calls on script, attitude and compliance criteria."}],quiz:[{q:{vi:"Gói 6000000 đồng, ưu đãi 15%, phí chuyển đổi trả góp 2%, trả 3 kỳ. Số tiền mỗi kỳ là bao nhiêu?",en:"A 6000000 VND package, 15% off, 2% conversion fee, 3 installments. What is each installment?"},options:{vi:["1700000 đồng","1734000 đồng","2000000 đồng","1445000 đồng"],en:["1700000 VND","1734000 VND","2000000 VND","1445000 VND"]},answer:1,explain:{vi:"6000000 x 85% = 5100000; x 1,02 = 5202000; chia 3 kỳ = 1734000 đồng.",en:"6000000 x 85% = 5100000; x 1.02 = 5202000; divided by 3 = 1734000 VND."}},{q:{vi:"Khách cũ hết hạn gói 4 tháng, không có mã giới thiệu. Theo chính sách trong bài, mã nào hợp lệ?",en:"A returning customer expired 4 months ago with no referral code. Under the training policy, which code is valid?"},options:{vi:["NEW30","REFER10","RENEW15","Không mã nào"],en:["NEW30","REFER10","RENEW15","None"]},answer:2,explain:{vi:"RENEW15 dành cho khách cũ gia hạn trong 6 tháng sau hết hạn; NEW30 chỉ cho khách chưa từng mua.",en:"RENEW15 is for returning customers within 6 months of expiry; NEW30 is for first-time buyers only."}},{q:{vi:"Cấp trên yêu cầu hứa cam kết đầu ra và nói ưu đãi chỉ còn hôm nay dù không đúng. Bạn làm gì?",en:"A manager tells you to promise guaranteed results and say the offer ends today when it does not. What do you do?"},options:{vi:["Từ chối, chỉ dùng thông tin đã duyệt và báo trưởng nhóm, bộ phận chất lượng","Làm theo vì là chỉ đạo","Chỉ nói với khách có vẻ dễ chốt","Nói nhưng không ghi vào CRM"],en:["Refuse, use only approved information and report to the team lead and QA","Comply because it is an instruction","Say it only to easy prospects","Say it but keep it out of the CRM"]},answer:0,explain:{vi:"Thông tin gian dối, khan hiếm giả vi phạm quyền lợi người tiêu dùng và dẫn tới khiếu nại, hoàn tiền, xử phạt.",en:"False claims and fake urgency breach consumer rights and lead to complaints, refunds and penalties."}},{q:{vi:"Khách nói “đừng gọi cho tôi nữa”. Mã trạng thái cuộc gọi đúng là gì?",en:"The customer says “do not call me again”. What is the correct disposition?"},options:{vi:["CALLBACK","NO-ANSWER","INTERESTED","DNC, ghi nhận từ chối và ngừng liên hệ"],en:["CALLBACK","NO-ANSWER","INTERESTED","DNC, record the opt-out and stop contact"]},answer:3,explain:{vi:"Yêu cầu ngừng liên hệ phải được ghi nhận ngay và áp dụng cho mọi chiến dịch sau.",en:"An opt-out must be recorded at once and applied to all later campaigns."}}],tools_en:["VoIP PBX / auto dialer","CRM system","Digital call scripts","Call recording & scoring tool","Payment and installment gateway"]}},"KK-336":{scenario:{company:"Riverbend Beverages",supervisor:{name:"Trần Minh Châu",role:{vi:"Trưởng phòng Trade Marketing",en:"Trade Marketing Manager"}},ref_code:"TMP-2611",title:{vi:"Trả thưởng theo kệ thật, không theo phiếu đăng ký.",en:"Pay for the real shelf, not the sign-up form."},brief:{vi:"Bạn quyết toán chương trình trưng bày quý IV TMP-2611 cho tạp hóa GT-4417. Nhân viên bán hàng đăng ký gói DP-A, nhưng ảnh chấm điểm cho thấy cửa hàng chỉ có 9 mặt trưng bày (facing) và không có kệ riêng. Kết quả chấm điểm: tháng 10 đạt, tháng 11 không đạt (hết hàng 2 SKU chủ lực), tháng 12 đạt. Đối chiếu bản quyết toán nháp với biên bản chấm điểm, sửa gói trưng bày và tiền thưởng (nghìn đồng), rồi lập báo cáo có căn cứ.",en:"You are settling Q4 display program TMP-2611 for grocery outlet GT-4417. The sales rep registered package DP-A, but the audit photos show only 9 facings and no dedicated rack. Audit results: October passed, November failed (2 core SKUs out of stock), December passed. Compare the draft settlement with the audit record, correct the display package and the reward (thousand VND), then write an evidence-based report."},reference_title:{vi:"Biên bản chấm điểm trưng bày đã duyệt · TMP-2611",en:"Approved display audit record · TMP-2611"},fields:[{id:"DISPLAY_PKG",label:{vi:"Gói trưng bày được quyết toán",en:"Settled display package"},initial:"DP-A",expected:"DP-B",choices:["DP-A","DP-B","DP-C"],reference:"Kết quả chấm điểm quý IV",hint:{vi:"Gói xét theo kệ thực tế: DP-A cần từ 12 facing và kệ riêng, DP-B từ 8 facing, DP-C từ 4 facing.",en:"The package follows the actual shelf: DP-A needs 12+ facings and a rack, DP-B 8+ facings, DP-C 4+ facings."}},{id:"REWARD_K",label:{vi:"Tiền thưởng trưng bày (nghìn đồng)",en:"Display reward (thousand VND)"},initial:"1500",expected:"700",reference:"Bảng mức thưởng & tháng đạt",ref_value:{vi:"Mức mô phỏng: DP-A 500, DP-B 350, DP-C 200 nghìn đồng/tháng; số tháng đạt chuẩn 2/3",en:"Training rates: DP-A 500, DP-B 350, DP-C 200 thousand VND/month; months passed 2/3"},hint:{vi:"Chỉ nhân mức thưởng với số tháng có biên bản chấm điểm đạt, không nhân với thời hạn chương trình.",en:"Multiply the rate only by months with a passed audit, not by the program length."}}],sop32:{vi:"Thưởng trưng bày = mức thưởng của gói đạt thực tế x số tháng có biên bản chấm điểm đạt; tháng không đạt không chi, không chụp bù (mức thưởng là số liệu mô phỏng).",en:"Display reward = rate of the package actually achieved x number of months with a passed audit; failed months are not paid and never re-shot (rates are training data)."},context:{label:"DMS / TMP-2611 · GT-4417",metrics:[{label:{vi:"Facing thực tế",en:"Actual facings"},value:"9"},{label:{vi:"Tháng đạt chuẩn",en:"Months passed"},value:"2/3"},{label:{vi:"Gói đã đăng ký",en:"Registered package"},value:"DP-A"}]},crisis:{vi:"Giám sát bán hàng nhắn: “Cứ quyết toán đủ DP-A ba tháng, chủ tiệm là khách lớn, cắt thưởng là họ chuyển kệ cho đối thủ. Ảnh tháng 11 để anh chụp bù rồi gửi em.”",en:"The sales supervisor messages you: “Just settle DP-A for all three months, the owner is a big customer and will give the shelf to a competitor if we cut. I will re-shoot November photos and send them.”"},options:{safe:{vi:"Quyết toán DP-B cho 2 tháng đạt theo biên bản, từ chối ảnh chụp bù, báo trưởng phòng Trade Marketing và đề xuất hỗ trợ cửa hàng nâng lên DP-A từ kỳ sau.",en:"Settle DP-B for the 2 passed months per the audit, refuse re-shot photos, inform the Trade Marketing Manager and offer to help the outlet reach DP-A next cycle."},shortcut:{vi:"Chi đủ DP-A ba tháng để giữ quan hệ với chủ tiệm, dùng ảnh chụp bù làm chứng từ.",en:"Pay DP-A for all three months to keep the owner happy and file the re-shot photos as evidence."},wait:{vi:"Treo hồ sơ quyết toán đến khi giám sát và chủ tiệm tự thống nhất với nhau.",en:"Hold the settlement until the supervisor and the owner agree between themselves."}},questions:{vi:["Vì sao cửa hàng GT-4417 chỉ được quyết toán DP-B và 700 nghìn đồng? Dữ liệu chấm điểm nào chứng minh?","Nếu chấp nhận ảnh chụp bù tháng 11, công ty gặp rủi ro gì về kiểm soát chi phí và gian lận chứng từ?"],en:["Why is outlet GT-4417 settled at DP-B and 700 thousand VND only? Which audit data proves it?","If the re-shot November photos were accepted, what cost-control and document-fraud risks would the company face?"]},hints:{vi:["Đặt phiếu đăng ký cạnh biên bản chấm điểm và đánh dấu dòng gói trưng bày đang lệch.","Theo SOP mục 3.2, chỉ đếm các tháng có kết quả chấm điểm đạt khi tính thưởng.","Đọc SOP mục 4.2: chứng từ trưng bày phải do người chấm điểm độc lập chụp đúng kỳ, mọi yêu cầu chụp bù phải báo cáo."],en:["Put the sign-up form next to the audit record and flag the display package line that differs.","Per SOP 3.2, count only months with a passed audit when computing the reward.","Read SOP 4.2: display evidence must be shot in-period by an independent auditor and any re-shoot request must be escalated."]}},learning:{summary:{vi:"Chuyên viên Trade Marketing & Trưng bày điểm bán biến chiến lược thương hiệu thành hành động tại kệ: thiết kế chương trình trưng bày, khuyến mại kênh, vật phẩm quảng cáo tại điểm bán (POSM) và tiêu chuẩn cửa hàng hoàn hảo cho kênh truyền thống (GT) và hiện đại (MT). Nghề đòi hỏi hiểu người mua sắm, tính hiệu quả đầu tư từng đồng ngân sách trade và kiểm soát chặt chứng từ chấm điểm để tiền thưởng đến đúng điểm bán đạt chuẩn.",en:"A Trade Marketing & Merchandising Executive turns brand strategy into action at the shelf: designing display programs, channel promotions, point-of-sale materials (POSM) and perfect store standards for general trade (GT) and modern trade (MT). The role requires shopper understanding, return-on-investment thinking for every trade budget unit and tight control of audit evidence so rewards reach only compliant outlets."},responsibilities:{vi:["Thiết kế chương trình trưng bày, khuyến mại kênh và cơ chế thưởng theo phân hạng điểm bán.","Xây dựng planogram, tiêu chuẩn cửa hàng hoàn hảo và hướng dẫn đội bán hàng triển khai.","Lập kế hoạch sản xuất, phân bổ và kiểm soát vật phẩm POSM theo từng khu vực.","Tổ chức chấm điểm trưng bày bằng ảnh, đối chiếu dữ liệu và quyết toán thưởng cho điểm bán.","Đo hiệu quả chương trình (sản lượng tăng thêm, ROI) và đề xuất tối ưu cho kỳ sau."],en:["Design display programs, channel promotions and reward mechanics by outlet tier.","Build planograms and perfect store standards and coach the sales force on execution.","Plan production, allocation and control of POSM for each region.","Run photo-based display audits, reconcile data and settle outlet rewards.","Measure program results (incremental volume, ROI) and propose improvements for the next cycle."]},competencies:[{name:{vi:"Thấu hiểu người mua sắm",en:"Shopper insight"},desc:{vi:"Hiểu hành trình mua tại điểm bán, vị trí kệ, ngang tầm mắt và yếu tố kích hoạt mua ngẫu hứng.",en:"Understand the in-store path to purchase, shelf positions, eye level and impulse triggers."}},{name:{vi:"Thiết kế cơ chế trade",en:"Trade mechanics design"},desc:{vi:"Xây cơ chế thưởng, chiết khấu, trưng bày có điều kiện đo được và phù hợp phân hạng điểm bán.",en:"Build reward, discount and display mechanics with measurable conditions that fit outlet tiers."}},{name:{vi:"Phân tích hiệu quả",en:"Effectiveness analysis"},desc:{vi:"Tách sản lượng nền và sản lượng tăng thêm để tính ROI thực của từng chương trình.",en:"Separate baseline and incremental volume to compute the true ROI of each program."}},{name:{vi:"Kiểm soát chứng từ",en:"Evidence control"},desc:{vi:"Đối chiếu ảnh chấm điểm, dữ liệu DMS và đơn hàng để chống chi sai, chi khống.",en:"Reconcile audit photos, DMS data and orders to prevent wrong or fictitious payouts."}},{name:{vi:"Phối hợp liên phòng ban",en:"Cross-functional coordination"},desc:{vi:"Làm việc với Brand, Sales, Tài chính, nhà cung cấp POSM và đơn vị chấm điểm độc lập.",en:"Work with Brand, Sales, Finance, POSM suppliers and independent audit vendors."}}],knowledge:{vi:["Luật Thương mại số 36/2005/QH11 và Nghị định 81/2018/NĐ-CP về xúc tiến thương mại (khuyến mại, trưng bày, hội chợ).","Cấu trúc kênh phân phối GT, MT, kênh tiêu dùng tại chỗ và vai trò nhà phân phối.","Nguyên tắc trưng bày: planogram, khối thương hiệu, ngang tầm mắt, FIFO, tỷ lệ chiếm kệ (share of shelf).","Chỉ số phân phối: độ phủ số (numeric distribution), độ phủ có trọng số (weighted distribution), tỷ lệ hết hàng.","Đánh giá hiệu quả khuyến mại: sản lượng nền, sản lượng tăng thêm, ROI và chi phí trade trên doanh thu."],en:["Commercial Law No. 36/2005/QH11 and Decree 81/2018/ND-CP on trade promotion (promotions, displays, fairs).","Channel structure of GT, MT, on-premise and the distributor's role.","Merchandising principles: planogram, brand blocking, eye level, FIFO, share of shelf.","Distribution metrics: numeric distribution, weighted distribution, out-of-stock rate.","Promotion evaluation: baseline volume, incremental volume, ROI and trade spend to revenue."]},tools:["DMS (Distributor Management System)","Ứng dụng chấm điểm trưng bày bằng ảnh","Phần mềm thiết kế planogram","Microsoft Excel / Power BI","Bản đồ tuyến bán hàng (route map)"],kpis:{vi:["Tỷ lệ điểm bán đạt chuẩn trưng bày theo chấm điểm độc lập.","Tỷ lệ chiếm kệ và tỷ lệ hết hàng tại điểm bán trọng điểm.","ROI chương trình trade dựa trên sản lượng tăng thêm.","Tỷ lệ quyết toán sai hoặc thiếu chứng từ (mục tiêu bằng 0)."],en:["Share of outlets meeting display standards in independent audits.","Share of shelf and out-of-stock rate at key outlets.","Trade program ROI based on incremental volume.","Rate of wrong or unsupported settlements (target zero)."]},day:[{time:"08:00",vi:"Xem bảng điều khiển chấm điểm hôm qua, lọc điểm bán không đạt và hết hàng.",en:"Review yesterday's audit dashboard and filter failed and out-of-stock outlets."},{time:"09:30",vi:"Đi thị trường cùng giám sát bán hàng, kiểm tra planogram tại 6 cửa hàng trọng điểm.",en:"Visit the market with a sales supervisor and check planograms at 6 key outlets."},{time:"13:30",vi:"Đối chiếu ảnh chấm điểm với dữ liệu DMS, lập bảng quyết toán thưởng trưng bày.",en:"Match audit photos with DMS data and prepare the display reward settlement."},{time:"15:30",vi:"Họp Brand và Tài chính về ngân sách POSM và cơ chế chương trình quý tới.",en:"Meet Brand and Finance on POSM budget and next quarter's program mechanics."},{time:"17:00",vi:"Cập nhật báo cáo ROI chương trình và gửi danh sách điểm bán cần hỗ trợ.",en:"Update the program ROI report and send the list of outlets needing support."}],mistakes:{vi:["Trả thưởng theo gói đăng ký thay vì kết quả chấm điểm thực tế tại kệ.","Tính ROI trên toàn bộ doanh số thay vì sản lượng tăng thêm so với nền.","Chấp nhận ảnh chụp bù, ảnh cũ hoặc ảnh do người hưởng lợi tự chụp làm chứng từ."],en:["Paying by the registered package instead of the actual audited shelf.","Computing ROI on total sales instead of incremental volume over baseline.","Accepting re-shot, old or self-taken photos from beneficiaries as evidence."]},career:[{vi:"Nhân viên trưng bày (merchandiser)",en:"Merchandiser"},{vi:"Chuyên viên Trade Marketing",en:"Trade Marketing Executive"},{vi:"Quản lý Trade Marketing kênh / khu vực",en:"Channel / Regional Trade Marketing Manager"},{vi:"Giám đốc Trade Marketing & Phát triển kênh",en:"Head of Trade Marketing & Channel Development"}],glossary:[{term:"Facing",vi:"Một mặt sản phẩm quay ra phía người mua ở hàng đầu tiên của kệ, đơn vị đếm mức độ hiện diện.",en:"One product face turned toward shoppers on the front row of a shelf, the unit of shelf presence."},{term:"Planogram",vi:"Sơ đồ quy định vị trí, số facing và thứ tự sản phẩm trên kệ.",en:"A diagram that defines product positions, facings and order on the shelf."},{term:"POSM",vi:"Vật phẩm quảng cáo tại điểm bán như kệ, wobbler, poster, tủ mát mang thương hiệu.",en:"Point-of-sale materials such as racks, wobblers, posters and branded coolers."},{term:"Share of shelf",vi:"Tỷ lệ chiều dài kệ hoặc số facing của thương hiệu trên tổng ngành hàng tại điểm bán.",en:"The brand's share of shelf length or facings within the category at an outlet."},{term:"GT / MT",vi:"Kênh truyền thống (tạp hóa, chợ) và kênh hiện đại (siêu thị, cửa hàng tiện lợi).",en:"General trade (groceries, wet markets) and modern trade (supermarkets, convenience stores)."}],quiz:[{q:{vi:"Cửa hàng đăng ký gói cao nhưng chấm điểm chỉ đạt gói thấp hơn. Quyết toán theo căn cứ nào?",en:"An outlet registered a top package but its audit meets only a lower one. What is the settlement basis?"},options:{vi:["Gói đã đăng ký","Kết quả chấm điểm thực tế","Đề xuất của giám sát bán hàng","Doanh số tháng cao nhất"],en:["The registered package","The actual audit result","The sales supervisor's proposal","The best month's sales"]},answer:1,explain:{vi:"Thưởng trưng bày trả cho kệ thực tế đạt chuẩn, căn cứ là biên bản chấm điểm độc lập đúng kỳ.",en:"Display rewards pay for the shelf actually achieved, evidenced by an independent in-period audit."}},{q:{vi:"Chương trình tạo doanh số 900 thùng, sản lượng nền là 700 thùng, chi phí tương đương 100 thùng. Sản lượng tăng thêm là bao nhiêu?",en:"A program delivers 900 cases, baseline is 700 cases and cost equals 100 cases. What is the incremental volume?"},options:{vi:["900 thùng","800 thùng","100 thùng","200 thùng"],en:["900 cases","800 cases","100 cases","200 cases"]},answer:3,explain:{vi:"Sản lượng tăng thêm = 900 - 700 = 200 thùng; ROI phải tính trên phần tăng thêm này.",en:"Incremental volume = 900 - 700 = 200 cases; ROI must be computed on this increment."}},{q:{vi:"Vị trí nào trên kệ thường có khả năng được người mua chú ý nhất?",en:"Which shelf position usually gets the most shopper attention?"},options:{vi:["Ngang tầm mắt","Sát sàn","Trên cùng sát trần","Sau quầy thu ngân, khuất tầm nhìn"],en:["Eye level","Floor level","Top shelf near the ceiling","Behind the counter, out of sight"]},answer:0,explain:{vi:"Vùng ngang tầm mắt được nhìn thấy nhiều nhất nên thường dành cho sản phẩm chủ lực.",en:"The eye-level zone is seen most, so it is usually reserved for core products."}},{q:{vi:"Giám sát bán hàng đề nghị chụp bù ảnh tháng không đạt để chi đủ thưởng. Bạn làm gì?",en:"A sales supervisor offers to re-shoot photos for a failed month to pay the full reward. What do you do?"},options:{vi:["Nhận ảnh chụp bù vì khách hàng quan trọng","Chi đủ rồi trừ vào kỳ sau","Từ chối, quyết toán đúng biên bản và báo cấp trên","Xóa tháng không đạt khỏi hệ thống"],en:["Accept the re-shoot because the customer matters","Pay in full and deduct next cycle","Refuse, settle per the audit and escalate","Delete the failed month from the system"]},answer:2,explain:{vi:"Ảnh chụp bù là chứng từ không trung thực; phải quyết toán theo biên bản và báo cáo áp lực gian lận.",en:"Re-shot photos are dishonest evidence; settle per the audit and escalate the fraud pressure."}}],tools_en:["DMS (Distributor Management System)","Photo-based display audit app","Planogram design software","Microsoft Excel / Power BI","Sales route map"]}},"KK-337":{scenario:{company:"Nimbus Ledger Software",supervisor:{name:"Doãn Khải Nguyên",role:{vi:"Trưởng bộ phận Thành công Khách hàng",en:"Head of Customer Success"}},ref_code:"QBR-5208",title:{vi:"Sức khỏe khách hàng đo bằng dữ liệu sử dụng.",en:"Customer health is measured by usage data."},brief:{vi:"Bạn chuẩn bị báo cáo danh mục quý QBR-5208. Khách hàng lớn nhất ACC-7731 mua 200 giấy phép, chỉ 84 người dùng hoạt động hằng tuần và còn 1 sự cố P1 mở 9 ngày, dù nhà tài trợ chấm NPS 9. ARR đầu kỳ của danh mục 5000 triệu đồng; mở rộng 650, thu hẹp 200, rời bỏ 300, khách hàng mới 1100 (triệu đồng, số liệu mô phỏng). Sửa trạng thái sức khỏe và NRR trên bản nháp, rồi lập báo cáo có căn cứ.",en:"You are preparing quarterly portfolio review QBR-5208. The largest account ACC-7731 bought 200 licenses, has only 84 weekly active users and one P1 incident open for 9 days, although the sponsor gave an NPS of 9. Opening portfolio ARR is 5000 million VND; expansion 650, contraction 200, churn 300, new logos 1100 (million VND, training data). Correct the health status and NRR in the draft, then write an evidence-based report."},reference_title:{vi:"Bảng chấm điểm sức khỏe & ARR đã duyệt · QBR-5208",en:"Approved health scorecard & ARR ledger · QBR-5208"},fields:[{id:"HEALTH",label:{vi:"Trạng thái sức khỏe ACC-7731",en:"ACC-7731 health status"},initial:"GREEN",expected:"RED",choices:["GREEN","AMBER","RED"],reference:"Thẻ điểm sức khỏe ACC-7731",hint:{vi:"Quy tắc: RED nếu tỷ lệ sử dụng giấy phép dưới 50% hoặc có P1 mở quá 7 ngày; AMBER 50-69%; GREEN từ 70% và không có P1.",en:"Rule: RED if license utilization is below 50% or a P1 is open over 7 days; AMBER 50-69%; GREEN 70%+ with no P1."}},{id:"NRR_PCT",label:{vi:"Tỷ lệ giữ chân doanh thu ròng NRR (%)",en:"Net revenue retention NRR (%)"},initial:"125",expected:"103",reference:"Sổ biến động ARR quý",ref_value:{vi:"ARR đầu kỳ 5000; mở rộng 650; thu hẹp 200; rời bỏ 300; khách mới 1100 (triệu đồng)",en:"Opening ARR 5000; expansion 650; contraction 200; churn 300; new logos 1100 (million VND)"},hint:{vi:"NRR chỉ đo nhóm khách hàng đã có từ đầu kỳ, doanh thu khách hàng mới không được cộng vào.",en:"NRR measures only the cohort present at the start of the period; new-logo revenue is excluded."}}],sop32:{vi:"NRR = (ARR đầu kỳ + mở rộng - thu hẹp - rời bỏ) / ARR đầu kỳ x 100; không cộng ARR của khách hàng mới ký trong kỳ. GRR tính tương tự nhưng không cộng mở rộng.",en:"NRR = (opening ARR + expansion - contraction - churn) / opening ARR x 100; never add ARR from new logos signed in the period. GRR is the same without expansion."},context:{label:"CS PLATFORM / QBR-5208",metrics:[{label:{vi:"Người dùng hoạt động / giấy phép",en:"Active users / licenses"},value:"84 / 200"},{label:{vi:"Sự cố P1 đang mở",en:"Open P1 incidents"},value:"1 (9 ngày / days)"},{label:{vi:"ARR đầu kỳ (triệu đồng)",en:"Opening ARR (million VND)"},value:"5000"}]},crisis:{vi:"Trưởng nhóm bán hàng nhắn: “Để ACC-7731 màu GREEN cho dự báo gia hạn đẹp, và cứ hứa với khách tính năng báo cáo tùy chỉnh sẽ có trong tháng sau dù lộ trình chưa duyệt, ký xong tính tiếp.”",en:"The sales lead messages you: “Keep ACC-7731 GREEN so the renewal forecast looks good, and promise the customer custom reporting next month even though the roadmap is not approved, we will sort it out after signing.”"},options:{safe:{vi:"Giữ RED theo dữ liệu, lập kế hoạch phục hồi gồm xử lý dứt điểm P1 và đào tạo người dùng, báo trưởng bộ phận; chỉ trao đổi lộ trình đã được bộ phận sản phẩm công bố.",en:"Keep RED per the data, build a recovery plan to close the P1 and train users, inform the Head of CS; share only roadmap items Product has published."},shortcut:{vi:"Đổi sang GREEN trong CRM và hứa miệng tính năng mới để khách ký gia hạn sớm.",en:"Switch to GREEN in the CRM and verbally promise the new feature to get an early renewal."},wait:{vi:"Không cập nhật trạng thái, chờ đến kỳ gia hạn xem khách có tự ký không.",en:"Leave the status untouched and wait to see whether the customer renews on its own."}},questions:{vi:["Vì sao ACC-7731 phải xếp RED dù nhà tài trợ chấm NPS 9? Hãy dẫn tỷ lệ sử dụng và sự cố P1.","Trình bày cách tính NRR 103% và rủi ro nếu báo cáo NRR có cộng doanh thu khách hàng mới hoặc hứa lộ trình chưa duyệt."],en:["Why must ACC-7731 be RED even though the sponsor gave an NPS of 9? Cite utilization and the P1 incident.","Explain how you reached NRR 103% and the risks of including new-logo revenue or promising an unapproved roadmap."]},hints:{vi:["Tính tỷ lệ người dùng hoạt động trên số giấy phép rồi so với ngưỡng của thẻ điểm sức khỏe.","Theo SOP mục 3.2, tách riêng doanh thu khách hàng mới trước khi tính NRR.","Đọc SOP mục 4.2: trạng thái sức khỏe phản ánh dữ liệu, mọi cam kết tính năng phải được bộ phận sản phẩm phê duyệt."],en:["Compute active users over licenses and compare with the health scorecard thresholds.","Per SOP 3.2, set new-logo revenue aside before computing NRR.","Read SOP 4.2: health status reflects data and every feature commitment needs Product approval."]}},learning:{summary:{vi:"Chuyên viên Thành công Khách hàng (CSM) trong doanh nghiệp SaaS đồng hành cùng khách hàng sau khi ký hợp đồng: dẫn dắt triển khai, thúc đẩy mức độ sử dụng, đo sức khỏe tài khoản, tổ chức họp đánh giá định kỳ và bảo vệ doanh thu gia hạn, mở rộng. Nghề đòi hỏi đọc dữ liệu sử dụng sản phẩm, hiểu mục tiêu kinh doanh của khách và trung thực khi báo cáo rủi ro rời bỏ.",en:"A Customer Success Manager (CSM) in a SaaS business partners with customers after signing: leading onboarding, driving adoption, measuring account health, running periodic business reviews and protecting renewal and expansion revenue. The role requires reading product usage data, understanding customer business goals and reporting churn risk honestly."},responsibilities:{vi:["Dẫn dắt giai đoạn triển khai và đưa khách hàng đến giá trị đầu tiên đúng hạn.","Theo dõi chỉ số sử dụng, chấm điểm sức khỏe tài khoản và cảnh báo sớm nguy cơ rời bỏ.","Lập kế hoạch thành công (success plan) và tổ chức họp đánh giá kinh doanh định kỳ (QBR).","Phối hợp hỗ trợ kỹ thuật và sản phẩm để xử lý sự cố, đưa phản hồi vào lộ trình.","Quản lý gia hạn, nhận diện cơ hội mở rộng và dự báo ARR của danh mục phụ trách."],en:["Lead onboarding and bring customers to first value on schedule.","Track usage metrics, score account health and flag churn risk early.","Build success plans and run quarterly business reviews (QBR).","Work with Support and Product to resolve incidents and feed the roadmap.","Manage renewals, spot expansion opportunities and forecast portfolio ARR."]},competencies:[{name:{vi:"Đọc dữ liệu sử dụng",en:"Usage analytics"},desc:{vi:"Phân tích người dùng hoạt động, tính năng được dùng và xu hướng để nhận diện rủi ro trước khi khách lên tiếng.",en:"Analyze active users, feature adoption and trends to spot risk before the customer speaks up."}},{name:{vi:"Tư vấn giá trị",en:"Value consulting"},desc:{vi:"Gắn sản phẩm với chỉ số kinh doanh của khách và chứng minh giá trị đạt được bằng số liệu.",en:"Link the product to the customer's business metrics and prove realized value with data."}},{name:{vi:"Quản trị quan hệ nhiều tầng",en:"Multi-level relationships"},desc:{vi:"Xây quan hệ với nhà tài trợ, quản trị viên và người dùng cuối, không phụ thuộc một đầu mối.",en:"Build relationships with sponsors, admins and end users instead of a single contact."}},{name:{vi:"Chỉ số SaaS",en:"SaaS metrics"},desc:{vi:"Tính đúng ARR, NRR, GRR, tỷ lệ rời bỏ và dự báo gia hạn theo định nghĩa thống nhất.",en:"Compute ARR, NRR, GRR, churn and renewal forecasts with consistent definitions."}},{name:{vi:"Trung thực & tuân thủ",en:"Integrity & compliance"},desc:{vi:"Báo cáo rủi ro đúng thực tế, không hứa ngoài thẩm quyền và bảo vệ dữ liệu khách hàng.",en:"Report risk truthfully, never promise beyond authority and protect customer data."}}],knowledge:{vi:["Chỉ số doanh thu định kỳ: MRR, ARR, NRR, GRR, tỷ lệ rời bỏ theo logo và theo doanh thu.","Mô hình chấm điểm sức khỏe: chỉ báo dẫn dắt (mức sử dụng, sự cố) và chỉ báo trễ (NPS, gia hạn).","Vòng đời khách hàng SaaS: triển khai, sử dụng, gia hạn, mở rộng, và khung kế hoạch thành công.","Quản lý sự cố và mức độ ưu tiên P1-P4 theo cam kết chất lượng dịch vụ (SLA).","Nghị định 13/2023/NĐ-CP về bảo vệ dữ liệu cá nhân và thỏa thuận xử lý dữ liệu với khách hàng."],en:["Recurring revenue metrics: MRR, ARR, NRR, GRR, logo churn and revenue churn.","Health scoring models: leading indicators (usage, incidents) and lagging ones (NPS, renewals).","The SaaS customer lifecycle: onboarding, adoption, renewal, expansion and success plan frameworks.","Incident management and P1-P4 priorities under service level agreements (SLA).","Decree 13/2023/ND-CP on personal data protection and data processing agreements with customers."]},tools:["Nền tảng Customer Success","CRM","Công cụ phân tích hành vi sản phẩm","Hệ thống ticket hỗ trợ","Khảo sát NPS / CSAT","Microsoft Excel / BI"],kpis:{vi:["Tỷ lệ giữ chân doanh thu ròng (NRR) và gộp (GRR) của danh mục.","Tỷ lệ gia hạn đúng hạn theo số tài khoản.","Thời gian đạt giá trị đầu tiên (time-to-value) của khách hàng mới.","Tỷ lệ tài khoản RED có kế hoạch phục hồi trong 5 ngày làm việc."],en:["Portfolio net (NRR) and gross (GRR) revenue retention.","On-time renewal rate by account count.","Time-to-value for new customers.","Share of RED accounts with a recovery plan within 5 business days."]},day:[{time:"08:30",vi:"Xem bảng sức khỏe danh mục, lọc tài khoản giảm sử dụng và sự cố quá hạn.",en:"Review the portfolio health board and filter accounts with falling usage or overdue incidents."},{time:"10:00",vi:"Họp triển khai với khách hàng mới, chốt mốc đạt giá trị đầu tiên.",en:"Run an onboarding call with a new customer and agree the first-value milestone."},{time:"13:30",vi:"Phối hợp kỹ thuật xử lý sự cố P1 và cập nhật khách hàng bằng văn bản.",en:"Work with Support on a P1 incident and update the customer in writing."},{time:"15:00",vi:"Chuẩn bị tài liệu QBR: giá trị đạt được, rủi ro và kế hoạch quý tới.",en:"Prepare QBR material: realized value, risks and next quarter's plan."},{time:"17:00",vi:"Cập nhật dự báo gia hạn, ghi chú CRM và chuyển phản hồi cho bộ phận sản phẩm.",en:"Update the renewal forecast, log CRM notes and pass feedback to Product."}],mistakes:{vi:["Đánh giá sức khỏe theo cảm tình của một đầu mối thay vì dữ liệu sử dụng thực tế.","Cộng doanh thu khách hàng mới vào NRR làm danh mục trông khỏe hơn thực tế.","Hứa tính năng hoặc ưu đãi chưa được phê duyệt để chốt gia hạn."],en:["Judging health by one contact's goodwill instead of actual usage data.","Adding new-logo revenue to NRR so the portfolio looks healthier than it is.","Promising unapproved features or discounts to close a renewal."]},career:[{vi:"Chuyên viên hỗ trợ triển khai khách hàng",en:"Customer Onboarding Specialist"},{vi:"Chuyên viên Thành công Khách hàng (CSM)",en:"Customer Success Manager"},{vi:"CSM cấp cao / Trưởng nhóm khách hàng chiến lược",en:"Senior CSM / Strategic Accounts Lead"},{vi:"Giám đốc Thành công Khách hàng",en:"Director / VP of Customer Success"}],glossary:[{term:"ARR",vi:"Doanh thu định kỳ hằng năm từ các hợp đồng thuê bao đang hiệu lực.",en:"Annual recurring revenue from active subscription contracts."},{term:"NRR",vi:"Tỷ lệ giữ chân doanh thu ròng của nhóm khách hàng hiện hữu, gồm mở rộng, trừ thu hẹp và rời bỏ.",en:"Net revenue retention of the existing cohort, including expansion minus contraction and churn."},{term:"Health score",vi:"Điểm tổng hợp từ mức sử dụng, sự cố, mức độ gắn kết để dự báo khả năng gia hạn.",en:"A composite score of usage, incidents and engagement used to predict renewal."},{term:"QBR",vi:"Họp đánh giá kinh doanh hằng quý với khách hàng về giá trị đạt được và kế hoạch tiếp theo.",en:"Quarterly business review with the customer on realized value and next steps."},{term:"Time-to-value",vi:"Thời gian từ khi ký hợp đồng đến khi khách hàng đạt kết quả có ý nghĩa đầu tiên.",en:"Time from contract signature to the customer's first meaningful outcome."}],quiz:[{q:{vi:"ARR đầu kỳ 1000, mở rộng 150, thu hẹp 50, rời bỏ 100, khách mới 300. NRR bằng bao nhiêu?",en:"Opening ARR 1000, expansion 150, contraction 50, churn 100, new logos 300. What is NRR?"},options:{vi:["130%","100%","115%","85%"],en:["130%","100%","115%","85%"]},answer:1,explain:{vi:"NRR = (1000 + 150 - 50 - 100) / 1000 = 100%; khách hàng mới không tính vào NRR.",en:"NRR = (1000 + 150 - 50 - 100) / 1000 = 100%; new logos are excluded from NRR."}},{q:{vi:"Chỉ báo nào cảnh báo sớm nhất nguy cơ rời bỏ?",en:"Which indicator gives the earliest warning of churn?"},options:{vi:["Hóa đơn gia hạn bị từ chối","Thư thông báo chấm dứt hợp đồng","Người dùng hoạt động giảm liên tục nhiều tuần","Báo cáo doanh thu cuối năm"],en:["A rejected renewal invoice","A termination notice","Active users falling for several weeks","The year-end revenue report"]},answer:2,explain:{vi:"Mức sử dụng giảm là chỉ báo dẫn dắt; các mục còn lại xuất hiện khi đã quá muộn.",en:"Falling usage is a leading indicator; the others appear when it is already too late."}},{q:{vi:"Bán hàng muốn bạn hứa tính năng chưa có trong lộ trình để chốt gia hạn. Bạn làm gì?",en:"Sales wants you to promise a feature not on the roadmap to close a renewal. What do you do?"},options:{vi:["Từ chối hứa, ghi nhận nhu cầu, báo cấp trên và trao đổi đúng lộ trình đã công bố","Hứa miệng, không ghi vào hợp đồng","Hứa bằng email để khách yên tâm","Im lặng để bán hàng tự xử lý"],en:["Decline, log the need, escalate and share only the published roadmap","Promise verbally, keep it out of the contract","Promise by email to reassure the customer","Stay silent and let Sales handle it"]},answer:0,explain:{vi:"Cam kết ngoài thẩm quyền gây tranh chấp và mất niềm tin; chỉ trao đổi điều đã được sản phẩm phê duyệt.",en:"Unauthorized commitments cause disputes and lost trust; share only what Product has approved."}},{q:{vi:"GRR khác NRR ở điểm nào?",en:"How does GRR differ from NRR?"},options:{vi:["GRR cộng thêm khách hàng mới","GRR chỉ tính theo số logo","GRR luôn lớn hơn NRR","GRR không cộng doanh thu mở rộng nên tối đa 100%"],en:["GRR adds new logos","GRR counts logos only","GRR is always above NRR","GRR excludes expansion so it caps at 100%"]},answer:3,explain:{vi:"GRR chỉ phản ánh doanh thu giữ lại sau thu hẹp và rời bỏ, không cộng mở rộng nên không vượt 100%.",en:"GRR reflects revenue kept after contraction and churn, without expansion, so it cannot exceed 100%."}}],tools_en:["Customer Success platform","CRM","Product analytics tools","Support ticketing system","NPS / CSAT surveys","Microsoft Excel / BI"]}}}),n.JobLabContentClusters=(n.JobLabContentClusters||[]).concat(4)})(window.KKR);
